Object.assign(window.TEM8_DICTIONARY, {"sin":{"media":{"uk":"media/uk/sin__gb_1.mp3","us":"media/us/sin__us_1.mp3"},"oxford":{"phon":"sɪn","pos":"noun","senses":[{"en":"an offence against God or against a religious or moral law","cn":"罪，罪恶，罪过（对神的冒犯或对宗教戒律、道德规范的违犯）","g":"[countable]","lab":"North American English","ex":{"en":"to commit a sin","cn":"犯罪"}},{"en":"the act of breaking a religious or moral law","cn":"罪行，犯罪（违犯宗教戒律、道德规范的行为）","g":"[uncountable]","ex":{"en":"a life of sin","cn":"罪过的一生"}},{"en":"an action that people think is very bad","cn":"过错；过失；恶行","g":"[countable, usually singular]","lab":"informal","ex":{"en":"It's a sin to waste taxpayers' money like that.","cn":"这样挥霍纳税人的钱太不应该。"}},{"en":"to break a religious or moral law","cn":"犯戒律；犯过失","ex":{"en":"Forgive me, Lord, for I have sinned.","cn":"主啊，宽恕我吧，我犯了罪。"},"pos":"verb"},{"en":"sine","cn":"正弦","pos":"abbreviation"},{"en":"Social Insurance number (= a number that the Canadian government uses to identify you, and that you use when you fill out official forms, apply for a job, etc.)","cn":"（加拿大）社会保险号码","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"罪;罪过;罪孽","en":"Sin or a sin is an action or type of behaviour which is believed to break the laws of God.","ex":{"en":"The Vatican's teaching on abortion is clear: it is a sin","cn":"罗马教廷对堕胎的教义非常清楚：这是罪过。"}},{"pos":"VERB 动词","cn":"犯戒律;犯过失","en":"If you sin, you do something that is believed to break the laws of God.","ex":{"en":"The Spanish Inquisition charged him with sinning against God and man","cn":"西班牙宗教法庭指控他亵渎上帝和人类。"}},{"pos":"N-COUNT 可数名词","cn":"罪恶;恶行;不道德的行为","en":"A sin is any action or behaviour that people disapprove of or consider morally wrong.","ex":{"en":"...the sin of arrogant hard-heartedness","cn":"傲慢无情的恶行"}},{"pos":"PHRASE 短语","cn":"同居","en":"If you say that a man and a woman are living in sin, you mean that they are living together as a couple although they are not married.","ex":{"en":"She was living in sin with her boyfriend.","cn":"她和男友同居。"}},{"pos":"","cn":"","en":"a multitude of sins→see: ;"}]},"examples":[{"en":"She works with us in Accounts, for her sins!","cn":"她跟我们一样也在账务室做事，活该如此！"},{"en":"Confess your sins to God and he will forgive you.","cn":"向上帝忏悔，上帝就会宽恕你。"}]},"sinks":{"oxford":{"phon":"sɪŋk","pos":"verb","senses":[{"en":"to go down below the surface or towards the bottom of a liquid or soft substance","cn":"下沉；下陷；沉没"},{"en":"to damage a boat or ship so that it goes below the surface of the sea, etc.","cn":"使下沉；使沉没"}]},"media":{"uk":"media/uk/sink__gb_1.mp3","us":"media/us/sink__us_1.mp3"}},"sideburns":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(男子的)鬓角","en":"If a man has sideburns, he has a strip of hair growing down the side of each cheek.","ex":{"en":"...a young man with long sideburns.","cn":"留着长鬓角的年轻人"}}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdesideburns.mp3","us":"media/ldoce/hwd/ame/a/sideburns.mp3"}},"sincere":{"oxford":{"phon":"sɪnˈsɪə(r)","pos":"adjective","senses":[{"en":"showing what you really think or feel","cn":"真诚的；诚挚的；诚恳的","ex":{"en":"a sincere apology","cn":"诚恳的道歉"}},{"en":"saying only what you really think or feel","cn":"诚实的；坦率的","ex":{"en":"He seemed sincere enough when he said he wanted to help.","cn":"他表示愿意帮忙，样子很真诚。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"诚恳的;真挚的;真诚的","en":"If you say that someone is sincere, you approve of them because they really mean the things they say. You can also describe someone's behaviour and beliefs as sincere .","ex":{"en":"He's sincere in his views","cn":"他的观点很诚恳。"}}]},"media":{"uk":"media/uk/sincere__gb_1.mp3","us":"media/us/sincere__us_1.mp3"},"examples":[{"en":"I can say in all sincerity that I knew nothing of these plans.","cn":"我可以十分坦诚地说，这些计划我一无所知。"},{"en":"He seemed sincere enough when he said he wanted to help.","cn":"他表示愿意帮忙，样子很真诚。"}]},"sixteen":{"media":{"uk":"media/uk/sixteen__gb_1.mp3","us":"media/us/sixteen__us_1.mp3"},"oxford":{"phon":"ˌsɪksˈtiːn","pos":"number","senses":[{"en":"16","cn":"十六"}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 16","en":"Sixteen is the number 16.","ex":{"en":"...exams taken at the age of sixteen","cn":"16 岁时参加的考试"}}]},"examples":[{"en":"He moved to London when he was sixteen (= 16 years old ) .","cn":"他十六岁那年搬到了伦敦。"},{"en":"sixteen years later","cn":"十六年后"}]},"similarity":{"media":{"uk":"media/uk/similarity__gb_1.mp3","us":"media/us/similarity__us_1.mp3"},"oxford":{"phon":"ˌsɪməˈlærəti","pos":"noun","senses":[{"en":"the state of being similar to somebody/something but not exactly the same","cn":"相似性；相仿性；类似性","g":"[uncountable, singular]","ex":{"en":"The report highlights the similarity between the two groups.","cn":"这份报告强调两组之间的相似性。"}},{"en":"a feature that things or people have that makes them like each other","cn":"相似处；相似点；类似的地方","g":"[countable]","ex":{"en":"a study of the similarities and differences between the two countries","cn":"对这两个国家的异同点的研究"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"相像;类似;近似","en":"If there is a similarity between two or more things, they are similar to each other.","ex":{"en":"The astonishing similarity between my brother and my first-born son","cn":"我弟弟和我的大儿子长得惊人地相似"}},{"pos":"N-COUNT 可数名词","cn":"相似处;相似点;类似的地方","en":"Similarities are features that things have which make them similar to each other.","ex":{"en":"There were significant similarities between mother and son","cn":"母子之间有很多相像的地方。"}}]},"examples":[{"en":"They are both doctors but that is where the similarity ends.","cn":"两人都是医生，但他们的相似之处仅此而已。"},{"en":"The karate bout has many similarities to a boxing match.","cn":"空手道比赛和拳击比赛有许多类似的地方。"}]},"si":{"oxford":{"phon":"ˌes ˈaɪ","pos":"abbreviation","senses":[{"en":"International System (used to describe units of measurement; from French ‘Système International’)","cn":"国际单位制（源自法语 Système International）","ex":{"en":"SI units","cn":"国际单位"}}]},"media":{"uk":"media/uk/si__gb_1.mp3","us":"media/us/si__us_1.mp3"},"examples":[{"en":"SI units","cn":"国际单位"}]},"sixty":{"media":{"uk":"media/uk/sixty__gb_1.mp3","us":"media/us/sixty__us_1.mp3"},"oxford":{"phon":"ˈsɪksti","pos":"","senses":[{"en":"60","cn":"六十"},{"en":"numbers, years or temperatures from 60 to 69","cn":"六十几；六十年代","g":"[plural]"}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 60","en":"Sixty is the number 60.","ex":{"en":"...the sunniest April in Britain for more than sixty years.","cn":"英国 60 多年以来阳光最灿烂的4月"}},{"pos":"N-PLURAL 复数名词","cn":"六十几(指 60 至 69 之间的数字)","en":"When you talk about the sixties, you are referring to numbers between 60 and 69. For example, if you are in your sixties, you are aged between 60 and 69. If the temperature is in the sixties, it is between 60 and 69 degrees.","ex":{"en":"...a lively widow in her sixties.","cn":"一位年过花甲、精神矍铄的寡妇"}},{"pos":"N-PLURAL 复数名词","cn":"二十世纪六十年代(指1960年至1969年)","en":"The sixties is the decade between 1960 and 1969.","ex":{"en":"In the sixties there were the deaths of the two Kennedy brothers and Martin Luther King.","cn":"20 世纪 60 年代，肯尼迪兄弟和马丁·路德·金先后去世。"}}]},"examples":[{"en":"The book was written in the sixties.","cn":"这本书写于六十年代。"},{"en":"the student riots in Paris in the late sixties","cn":"六十年代末巴黎的学生骚乱"}]},"sickness":{"media":{"uk":"media/uk/sickness__gb_1.mp3","us":"media/us/sickness__us_1.mp3"},"oxford":{"phon":"ˈsɪknəs","pos":"noun","senses":[{"en":"illness; bad health","cn":"疾病；不健康","g":"[uncountable]","ex":{"en":"She's been off work because of sickness.","cn":"她因病没有上班。"}},{"en":"a particular type of illness or disease","cn":"…病；…症","g":"[uncountable, countable, usually singular]","ex":{"en":"travel/radiation sickness","cn":"旅行眩晕；辐射病"}},{"en":"the feeling that you are likely to vomit (= bring food back up from the stomach to the mouth); the fact of vomiting","cn":"恶心；呕吐","g":"[uncountable]","lab":"especially British English","ex":{"en":"symptoms include sickness and diarrhoea","cn":"症状包括呕吐和腹泻"}},{"en":"a feeling of being very sad, disappointed or full of horror","cn":"悲伤；失望；惊恐","g":"[singular]","ex":{"en":"He felt a sickness rise in him at the thought of leaving.","cn":"一想到要离开，他就感到一阵恶心。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"患病;生病;不健康","en":"Sickness is the state of being ill or unhealthy.","ex":{"en":"In fifty-two years of working he had one week of sickness","cn":"在52 年的工作中他仅病过一周。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"恶心;呕吐感","en":"Sickness is the uncomfortable feeling that you are going to vomit.","ex":{"en":"He felt a great rush of sickness","cn":"他忽然觉得非常想吐。"}},{"pos":"N-VAR 可变名词","cn":"病症;疾病","en":"A sickness is a particular illness.","ex":{"en":"...radiation sickness.","cn":"辐射病"}}]},"examples":[{"en":"The sickness passed off after a while.","cn":"过了一会儿，就不觉得恶心了。"},{"en":"She's been off work because of sickness.","cn":"她因病没有上班。"}]},"significance":{"media":{"uk":"media/uk/significance__gb_1.mp3","us":"media/us/significance__us_1.mp3"},"oxford":{"phon":"sɪɡˈnɪfɪkəns","pos":"noun","senses":[{"en":"the importance of something, especially when this has an effect on what happens in the future","cn":"（尤指对将来有影响的）重要性，意义","ex":{"en":"a decision of major political significance","cn":"具有重大政治意义的决定"}},{"en":"the meaning of something","cn":"意思；含义","ex":{"en":"She couldn't grasp the full significance of what he had said.","cn":"她未能充分领会他那番话的意思。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"重要性;意义","en":"The significance of something is the importance that it has, usually because it will have an effect on a situation or shows something about a situation.","ex":{"en":"Ideas about the social significance of religion have changed over time","cn":"关于宗教的社会意义的看法已经随着时间的变迁而改变。"}}]},"examples":[{"en":"The new drug has great significance for the treatment of the disease.","cn":"这种新药对于这种病的治疗有重大的意义。"},{"en":"They discussed the statistical significance of the results.","cn":"他们讨论了这些结果在统计学上的意义。"}]},"sings":{"oxford":{"phon":"sɪŋ","pos":"verb","senses":[{"en":"to make musical sounds with your voice in the form of a song or tune","cn":"唱（歌）；演唱"},{"en":"to make high musical sounds","cn":"鸣；啼；啼啭"}]},"media":{"uk":"media/uk/sing__gb_1.mp3","us":"media/us/sing__us_1.mp3"}},"silver":{"media":{"uk":"media/uk/silver__gb_1.mp3","us":"media/us/silver__us_1.mp3"},"oxford":{"phon":"ˈsɪlvə(r)","pos":"noun","senses":[{"en":"a chemical element. Silver is a shiny, grey-white precious metal used for making coins, jewellery, beautiful objects, etc.","cn":"银","g":"[uncountable]","ex":{"en":"a silver ring/chain","cn":"银戒指；银链"}},{"en":"a shiny grey-white colour","cn":"银色；银白色；银灰色","g":"[uncountable]","ex":{"en":"There was a streak of silver in her hair.","cn":"她头上有一绺银发。"}},{"en":"dishes, beautiful objects, etc. that are made of silver","cn":"银器","g":"[uncountable]","ex":{"en":"Thieves stole £5 000 worth of silver.","cn":"窃贼偷走了价值 5 000 英镑的银器。"}},{"en":"coins that are made of silver or a metal that looks like silver","cn":"银币（银或似银金属制成的硬币）","g":"[uncountable]","ex":{"en":"I need £2 in silver for the parking meter.","cn":"我需要在停车收费器里投 2 英镑银币。"}},{"en":"a medal that is given to the person or the team that wins the second prize in a race or competition","cn":"银质奖章；银牌","g":"[uncountable, countable]","ex":{"en":"She won silver in last year's championships.","cn":"她在去年的锦标赛上获得银牌。"}},{"en":"shiny grey-white in colour","cn":"银色的；银白色的；银灰色的","ex":{"en":"a silver car","cn":"银灰色汽车"},"pos":"adjective"},{"en":"to cover the surface of something with a thin layer of silver or something that looks like silver","cn":"给…镀（或包）银；给…镀（或包）似银的物质","g":"[usually passive]","pos":"verb"},{"en":"to make something become bright like silver","cn":"使具有银色光泽；使变成银色","lab":"especially literary","ex":{"en":"Moonlight was silvering the countryside.","cn":"月光下的乡村泛着银光。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"银","en":"Silver is a valuable pale grey metal that is used for making jewellery and ornaments.","ex":{"en":"...a hand-crafted brooch made from silver.","cn":"一枚手工银制胸针"}},{"pos":"N-UNCOUNT 不可数名词","cn":"银币","en":"Silver consists of coins that are made from silver or that look like silver.","ex":{"en":"...the basement where £150,000 in silver was buried.","cn":"埋有 150,000 英镑银币的地下室"}},{"pos":"N-UNCOUNT 不可数名词","cn":"银器(尤指餐具)","en":"You can use silver to refer to all the things in a house that are made of silver, especially the cutlery and dishes.","ex":{"en":"He beat the rugs and polished the silver.","cn":"他拍打去地毯上的灰尘，还擦拭了银器。"}},{"pos":"COLOUR 颜色词","cn":"银色;银灰色;银白色","en":"Silver is used to describe things that are shiny and pale grey in colour.","ex":{"en":"He had thick silver hair which needed cutting.","cn":"他浓密的银发该理理了。"}},{"pos":"N-VAR 可变名词","cn":"同 silver medal","en":"A silver is the same as a silver medal .","ex":{"en":"Britain went on to take bronze and then followed it up by winning silver in the World Cup.","cn":"英国斩获了铜牌，接下来又赢得了世界杯的银牌。"}},{"pos":"","cn":"","en":"born with a silver spoon in your mouth→see: ;"}]},"examples":[{"en":"I need £2 in silver for the parking meter.","cn":"我需要在停车收费器里投 2 英镑银币。"},{"en":"They've had to sell the family silver to pay the bills.","cn":"他们不得已卖掉家传的银器去支付账单。"}]},"sitting":{"media":{"uk":"media/uk/sitting__gb_1.mp3","us":"media/us/sitting__us_1.mp3"},"oxford":{"phon":"ˈsɪtɪŋ","pos":"noun","senses":[{"en":"a period of time during which a court or a parliament deals with its business","cn":"（法院或议会的）开会，会议，开庭（期间）","ex":{"en":"late-night sittings in the House of Commons","cn":"下议院深夜开会"}},{"en":"a time when a meal is served in a hotel, etc. to a number of people at the same time","cn":"（旅馆等分段安排客人用餐的）一轮，一次","ex":{"en":"A hundred people can be served at one sitting (= at the same time).","cn":"可同时供一百人就餐。"}},{"en":"a period of time that a person spends sitting and doing an activity","cn":"一次（坐着活动的时间）","ex":{"en":"I read the book in one sitting.","cn":"我坐下来一口气就把那本书看完了。"}},{"en":"a period of time when somebody sits or stands to have their picture painted or be photographed","cn":"（摆姿势让人画像或拍照的）一次（时间）","ex":{"en":"It took three sittings to complete the portrait.","cn":"花了三坐才完成这幅肖像。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(因场地限制而分批用餐的)一批，一轮","en":"A sitting is one of the periods when a meal is served when there is not enough space for everyone to eat at the same time.","ex":{"en":"Dinner was in two sittings.","cn":"分两批吃晚饭。"}},{"pos":"N-COUNT 可数名词","cn":"召开会议;举行例会","en":"A sitting of a parliament, legislature, court, or other official body is one of the occasions when it meets in order to carry out its work.","ex":{"en":"...the recent emergency sittings of the UN Security Council.","cn":"联合国安全理事会最近召开的几次紧急会议"}},{"pos":"ADJ 形容词","cn":"(总统或议员)现任的，在任期内的","en":"A sitting president or member of parliament is a present one, not a future or past one.","ex":{"en":"...the greatest clash in our history between a sitting president and an ex-president.","cn":"在我们的历史上发生的现任总统与前任总统之间最为严重的一次冲突"}},{"pos":"PHRASE 短语","cn":"处于优越地位;处于优势","en":"If you are sitting pretty, you are in a very favourable situation.","ex":{"en":"If we'd let them buy it for a quarter of a million, we'd be sitting pretty by now.","cn":"要是当初我们让他以 25 万的价钱买下来的话，我们现在就会处于上风了。"}}]},"examples":[{"en":"I read the book in one sitting.","cn":"我坐下来一口气就把那本书看完了。"},{"en":"A hundred people can be served at one sitting (= at the same time).","cn":"可同时供一百人就餐。"}]},"silt":{"media":{"uk":"media/uk/silt__gb_1.mp3","us":"media/us/silt__us_1.mp3"},"oxford":{"phon":"sɪlt","pos":"noun","senses":[{"en":"sand, mud, etc. that is carried by flowing water and is left at the mouth of a river or in a harbour","cn":"（沉积在河口或港口的）泥沙，淤泥，粉砂","ex":{"en":"The wreck was covered in a fine layer of silt.","cn":"沉船被一层薄薄的淤泥覆盖。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"淤泥;泥沙","en":"Silt is fine sand, soil, or mud which is carried along by a river.","ex":{"en":"The lake was almost solid with silt and vegetation.","cn":"湖里几乎快被淤泥和植物填满了。"}},{"pos":"","cn":"","en":"相关词组：silt up"}]},"examples":[{"en":"Sand has silted up the river delta.","cn":"泥沙把这条河的三角洲淤塞了。"},{"en":"The harbour has now silted up.","cn":"港口现已淤塞。"}]},"site":{"media":{"uk":"media/uk/site__gb_1.mp3","us":"media/us/site__us_1.mp3"},"oxford":{"phon":"saɪt","pos":"noun","senses":[{"en":"a place where a building, town, etc. was, is or will be located","cn":"（建筑物、城镇等的）地点，位置，建筑工地","ex":{"en":"the site of a sixteenth-century abbey","cn":"一座十六世纪修道院的旧址"}},{"en":"a place where something has happened","cn":"现场；发生地","ex":{"en":"the site of the battle","cn":"战场"}},{"en":"a place that is used for a particular activity","cn":"场所；地点","ex":{"en":"a caravan site","cn":"旅行拖车停车点"}},{"en":"a place connected to the internet, where a company or an organization, or an individual person, puts information","cn":"站点；网站","ex":{"en":"online dating sites","cn":"婚恋网站"}},{"en":"to build or place something in a particular position","cn":"使位于；使坐落于","ex":{"en":"The castle is magnificently sited high up on a cliff.","cn":"城堡坐落在高高的悬崖上，十分壮观。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"场地;场所","en":"A site is a piece of ground that is used for a particular purpose or where a particular thing happens.","ex":{"en":"He became a hod carrier on a building site.","cn":"他在建筑工地上当起了小工。"}},{"pos":"N-COUNT 可数名词","cn":"地点;遗址;原址","en":"The site of an important event is the place where it happened.","ex":{"en":"Scientists have described the Aral sea as the site of the worst ecological disaster on earth","cn":"科学家把咸海描述成地球上最严重的生态灾难发生地。"}},{"pos":"N-COUNT 可数名词","cn":"(建造房屋等的)地皮，地基，遗址","en":"A site is a piece of ground where something such as a statue or building stands or used to stand.","ex":{"en":"...the site of Moses' tomb.","cn":"摩西的墓址"}},{"pos":"N-COUNT 可数名词","cn":"同 website","en":"A site is the same as a website ."},{"pos":"VERB 动词","cn":"使坐落在;给…选址","en":"If something is sited in a particular place or position, it is put there or built there.","ex":{"en":"He said chemical weapons had never been sited in Germany.","cn":"他声称从未在德国部署过化学武器。"}},{"pos":"PHRASE 短语","cn":"在现场;临场","en":"If someone or something is on site, they are in a particular area or group of buildings where people work, study, or stay.","ex":{"en":"It is cheaper to have extra building work done when the builder is on site.","cn":"建筑工在现场干活时，让他额外做工的话工钱会便宜一些。"}},{"pos":"PHRASE 短语","cn":"不在场;离开","en":"If someone or something is off site, they are away from a particular area or group of buildings where people work, study, or stay.","ex":{"en":"There is ample car parking off site.","cn":"外面有很多地方可以停车。"}}]},"examples":[{"en":"All the materials are on site so that work can start immediately.","cn":"所有材料都已运抵工地，可以立即开工。"},{"en":"The castle is magnificently sited high up on a cliff.","cn":"城堡坐落在高高的悬崖，十分壮观。"}]},"simultaneously":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if two or more people or things do the same thing together , they do it at the same time and usually in the same place","cn":""},{"en":"if two or more things happen at once , they happen at the same time and this is annoying or causes problems","cn":""}]},"examples":[{"en":"They grabbed each other’s hands in simultaneous panic.","cn":"","src":"ld"},{"en":"Up to twenty users can have simultaneous access to the system.","cn":"","src":"ld"}],"media":{"uk":"media/uk/simultaneously__gb_1.mp3","us":"media/us/simultaneously__us_1.mp3"},"oxford":{"phon":"ˌsɪmlˈteɪniəsli","pos":"adverb","senses":[{"en":"at the same time as something else","cn":"同时发生（或进行）地；同步地","ex":{"en":"The game will be broadcast simultaneously on TV and radio.","cn":"比赛将同时在电视和电台转播。"}}]}},"silence":{"media":{"uk":"media/uk/silence__gb_1.mp3","us":"media/us/silence__us_1.mp3"},"oxford":{"phon":"ˈsaɪləns","pos":"noun","senses":[{"en":"a complete lack of noise or sound","cn":"寂静；无声","g":"[uncountable]","ex":{"en":"Their footsteps echoed in the silence.","cn":"他们的脚步声在一片寂静中回荡着。"}},{"en":"a situation when nobody is speaking","cn":"沉默；缄默；默不作声","g":"[countable, uncountable]","ex":{"en":"an embarrassed/awkward/uncomfortable silence","cn":"难堪／尴尬／令人不安的沉默"}},{"en":"a situation in which somebody refuses to talk about something or to answer questions","cn":"缄默；缄口不谈；拒绝回答","g":"[uncountable, singular]","ex":{"en":"She broke her public silence in a TV interview.","cn":"她接受了一次电视采访，就此结束了她不在公开场合说话的状态。"}},{"en":"a situation in which people do not communicate with each other by letter or phone","cn":"没有音信；没有联系","g":"[uncountable]","ex":{"en":"The phone call came after months of silence.","cn":"几个月没有音信之后，打来了一个电话。"}},{"en":"to make somebody/something stop speaking or making a noise","cn":"使安静；使不说话","ex":{"en":"She silenced him with a glare.","cn":"她瞪了他一眼，他就不作声了。"},"pos":"verb"},{"en":"to make somebody stop expressing opinions that are opposed to yours","cn":"压制，使不再发表（反对意见）","ex":{"en":"All protest had been silenced.","cn":"一切反对的声音都被压了下去。"},"pos":"verb"},{"en":"used to tell people to be quiet","cn":"（用以让人们安静）安静，静下来","ex":{"en":"Silence in court!","cn":"法庭内保持肃静！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"沉默;缄默;不作声","en":"If there is silence, nobody is speaking.","ex":{"en":"They stood in silence","cn":"他们默不作声地站着。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"寂静;无声","en":"The silence of a place is the extreme quietness there.","ex":{"en":"...the silence of that rainless, all-concealing fog","cn":"滴雨未下、隐藏一切的大雾静默无声"}},{"pos":"N-UNCOUNT 不可数名词","cn":"缄默;绝口不提;闭口不谈","en":"Someone's silence about something is their failure or refusal to speak to other people about it.","ex":{"en":"The district court ruled that Popper's silence in court today should be entered as a plea of not guilty.","cn":"区法院裁定今天波珀在法庭上的缄默将被视作是进行无罪抗辩。"}},{"pos":"VERB 动词","cn":"使安静;使无声;使不说话","en":"To silence someone or something means to stop them speaking or making a noise.","ex":{"en":"A ringing phone silenced her","cn":"响起的电话铃声让她安静了下来。"}},{"pos":"VERB 动词","cn":"制止，使不再发表(反对意见)","en":"If someone silences you, they stop you expressing opinions that they do not agree with.","ex":{"en":"Like other tyrants, he tried to silence anyone who spoke out against him.","cn":"像其他暴君一样，他力图压制任何公开反对他的人。"}},{"pos":"VERB 动词","cn":"杀…灭口","en":"To silence someone means to kill them in order to stop them revealing something secret.","ex":{"en":"A hit man had been sent to silence her over the affair.","cn":"为了掩盖这件事，已经派出一名职业杀手去杀她灭口。"}}]},"examples":[{"en":"She broke her public silence in a TV interview.","cn":"她接受了一次电视采访，就此结束了她不在公开场合说话的状态。"},{"en":"The company's silence on the subject has been taken as an admission of guilt.","cn":"在外界看来，公司在这个问题上保持沉默便是承认有罪。"}]},"silverware":{"media":{"uk":"media/uk/silverware__gb_1.mp3","us":"media/us/silverware__us_1.mp3"},"oxford":{"phon":"ˈsɪlvəweə(r)","pos":"noun","senses":[{"en":"objects that are made of or covered with silver, especially knives, forks, dishes, etc. that are used for eating and serving food","cn":"银器，镀银器皿（尤指餐具）","ex":{"en":"a piece of silverware","cn":"一件银器"}},{"en":"knives, forks and spoons, used for eating and serving food","cn":"餐具（刀、叉和匙）","lab":"both North American English"},{"en":"a silver cup that you win in a sports competition","cn":"（体育比赛中的）银杯","lab":"British English, informal，，"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"银器(尤指餐具)","en":"You can use silverware to refer to all the things in a house that are made of silver, especially the cutlery and dishes.","ex":{"en":"There was a serving spoon missing when Nina put the silverware back in its box.","cn":"尼娜将银餐具收拾到盒子里去的时候发现少了一把调羹。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(新闻用语中有时指体育比赛中的)银杯","en":"Journalists sometimes use silverware to refer to silver cups and other prizes won by sports teams or players.","ex":{"en":"Everton paraded their recently acquired silverware.","cn":"埃弗顿展示了他们最近获得的银杯。"}}]},"examples":[{"en":"a piece of silverware","cn":"一件银器"},{"en":"The club has not yet given up hope of ending the season with some silverware.","cn":"该俱乐部仍未放弃在赛季结束时拿银杯的希望。"}]},"silent":{"media":{"uk":"media/uk/silent__gb_1.mp3","us":"media/us/silent__us_1.mp3"},"oxford":{"phon":"ˈsaɪlənt","pos":"adjective","senses":[{"en":"where there is little or no sound; making little or no sound","cn":"无声的；安静的；不喧闹的","ex":{"en":"At last the traffic fell silent.","cn":"车辆的喧嚣终于消逝了。"}},{"en":"not speaking","cn":"不说话的；沉默的","ex":{"en":"to remain/stay/keep silent","cn":"保持沉默"}},{"en":"not expressed with words or sound","cn":"不用言语表达的；无声的","g":"[only before noun]","ex":{"en":"a silent prayer/protest","cn":"默祷；无声的抗议"}},{"en":"written but not pronounced","cn":"不发音的","ex":{"en":"The ‘b’ in ‘lamb’ is silent.","cn":"lamb 中的 b 不发音。"}},{"en":"with pictures but no sound","cn":"无声的；无声电影的","g":"[only before noun]","ex":{"en":"a silent film/movie","cn":"无声电影"}},{"en":"not talking very much","cn":"很少说话的；不爱说话的；少言寡语的","g":"[only before noun]","ex":{"en":"He's the strong silent type.","cn":"他是那种强悍而沉默寡言的人。"}},{"en":"not giving information about something; refusing to speak about something","cn":"不提供情况的；未谈及的；拒绝讲的","ex":{"en":"The report is strangely silent on this issue.","cn":"很奇怪，报告对这个问题避而不谈。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉默的;不说话的","en":"Someone who is silent is not speaking.","ex":{"en":"Trish was silent because she was reluctant to put her thoughts into words","cn":"特里西一直不说话，因为她不愿意吐露内心的想法。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"寡言少语的;很少说话的;不爱说话的","en":"If you describe someone as a silent person, you mean that they do not talk to people very much, and sometimes give the impression of being unfriendly.","ex":{"en":"He was a serious, silent man.","cn":"他是个一本正经、寡言少语的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无声的;寂静的;不出声的","en":"A place that is silent is completely quiet, with no sound at all. Something that is silent makes no sound at all.","ex":{"en":"The room was silent except for John's crunching","cn":"屋子里一片寂静，只有约翰发出的咀嚼声。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"只字不提的;不愿讲的","en":"If someone is silent about something, they do not tell people anything about it, because they think it is a private matter or because they want to keep the information secret.","ex":{"en":"Douglas was noticeably silent about his feelings for his father","cn":"道格拉斯明显不愿提及自己对父亲的感情。"}},{"pos":"ADJ 形容词","cn":"(情感、行为等)无声的，不用言语表达的","en":"A silent emotion or action is not expressed in speech.","ex":{"en":"The attacker still stood there, watching her with silent contempt","cn":"袭击者还站在那里，用一种鄙夷的眼神一言不发地看着她。"}},{"pos":"ADJ 形容词","cn":"(电影)无声的","en":"A silent film has pictures usually accompanied by music but does not have the actors' voices or any other sounds.","ex":{"en":"...one of the famous silent films of Charlie Chaplin.","cn":"查理·卓别林著名的默片之一"}},{"pos":"ADJ 形容词","cn":"(单词中的字母)不发音的","en":"A silent letter in a word is written but not pronounced. For example, the 'k' in the word 'know' is silent."}]},"examples":[{"en":"They huddled together in silent groups.","cn":"他们一群群地围在一起，默不作声。"},{"en":"The report is strangely silent on this issue.","cn":"很奇怪，报告对这个问题避而不谈。"}]},"simple":{"media":{"uk":"media/uk/simple__gb_1.mp3","us":"media/us/simple__us_1.mp3"},"oxford":{"phon":"ˈsɪmpl","pos":"adjective","senses":[{"en":"not complicated; easy to understand or do","cn":"易于理解的；易做的；简单的","sc":"easy","ex":{"en":"a simple solution/explanation/question/task/example","cn":"简单的解决办法／解释／问题／任务／例子"}},{"en":"basic or plain without anything extra or unnecessary","cn":"朴素的；简朴的；不加装饰的","sc":"basic/plain","ex":{"en":"simple but elegant clothes","cn":"素雅的衣服"}},{"en":"used before a noun to emphasize that it is exactly that and nothing else","cn":"（用在名词前表示强调）纯粹的，完全的，不折不扣的","sc":"for emphasis","ex":{"en":"We cannot ignore the simple fact that the country cannot sustain the current level of economic growth.","cn":"我们不能忽略的基本事实是，国家不可能维持目前的经济增长水平。"}},{"en":"consisting of only a few parts; not complicated in structure","cn":"组成部分少的；结构简单的","g":"[usually before noun]","lab":"grammar","sc":"with few parts","ex":{"en":"simple forms of life, for example amoebas","cn":"如变形虫之类的简单生命形式"}},{"en":"ordinary; not special","cn":"普通的；一般的；平凡的","g":"[only before noun]","sc":"ordinary","ex":{"en":"I'm a simple country girl.","cn":"我是一个普普通通的乡村姑娘。"}},{"en":"slow to learn; having a learning disability","cn":"学习速度慢；有学习障碍","g":"[not usually before noun]","lab":"old-fashioned, offensive，，","sc":"slow to learn"},{"en":"used to describe the present or past tense of a verb that is formed without using an auxiliary verb, as in She loves him (= the simple present tense) or He arrived late (= the simple past tense)","cn":"（无须用助动词构成的动词时态）简单的，一般的","sc":"grammar"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简单的;简明的;易于理解的","en":"If you describe something as simple, you mean that it is not complicated, and is therefore easy to understand.","ex":{"en":"...simple pictures and diagrams.","cn":"简单的图画和图表"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简朴的;朴素的;不加装饰的","en":"If you describe people or things as simple, you mean that they have all the basic or necessary things they require, but nothing extra.","ex":{"en":"The Holy Family Church was closed and the parish now celebrates mass in this simple side chapel","cn":"圣家堂关闭了，现在该教区的居民在它旁边的简陋的小教堂里做弥撒。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好办的;容易的;易解决的;简单的","en":"If a problem is simple or if its solution is simple, the problem can be solved easily.","ex":{"en":"Some puzzles look difficult but once the solution is known are actually quite simple","cn":"有些谜语看似难解，可一旦知道了谜底其实十分简单。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易做的;易完成的;易解决的","en":"A simple task is easy to do.","ex":{"en":"The job itself had been simple enough","cn":"工作本身十分容易。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"头脑简单的;愚笨的;迟钝的","en":"If you say that someone is simple, you mean that they are not very intelligent and have difficulty learning things.","ex":{"en":"He was simple as a child.","cn":"他头脑简单地像个孩子。"}},{"pos":"ADJ 形容词","cn":"(强调原因)纯粹的，完全的","en":"You use simple to emphasize that the thing you are referring to is the only important or relevant reason for something.","ex":{"en":"His refusal to talk was simple stubbornness.","cn":"他拒绝交谈完全是因为固执。"}},{"pos":"ADJ 形容词","cn":"(动词时态)一般的，简单的","en":"In grammar, simple tenses are ones which are formed without an auxiliary verb 'be', for example 'I dressed and went for a walk' and 'This tastes nice'. Simple verb groups are used especially to refer to completed actions, regular actions, and situations."},{"pos":"ADJ 形容词","cn":"(语法上指句子)简单的","en":"In English grammar, a simple sentence consists of one main clause."}]},"examples":[{"en":"We lost because we played badly. It's as simple as that.","cn":"我们输了是因为我们打得不好。原因就这么简单。"},{"en":"I had to do it for the simple reason that (= because) I couldn't trust anyone else.","cn":"我之所以这么做，纯粹是因为我信不过任何人。"}]},"sigh":{"oxford":{"phon":"saɪ","pos":"verb","senses":[{"en":"to take and then let out a long deep breath that can be heard, to show that you are disappointed, sad, tired, etc.","cn":"叹气；叹息","g":"[intransitive]","ex":{"en":"He sighed deeply at the thought.","cn":"想到这里，他深深叹了口气。"}},{"en":"to say something with a sigh","cn":"叹着气说；叹息道","g":"[transitive]","ex":{"en":"‘Oh well, better luck next time,’ she sighed.","cn":"“唉，就这样了，但愿下一次运气好些。”她叹息道。"}},{"en":"to make a long sound like a sigh","cn":"悲鸣","g":"[intransitive]","lab":"literary","ex":{"en":"the sighing of the wind through the trees","cn":"风穿过树林的叹息"}},{"en":"an act or the sound of sighing","cn":"叹气；叹息","ex":{"en":"to give/heave/let out a sigh","cn":"发出叹息"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"叹气;叹息;深呼气","en":"When you sigh, you let out a deep breath, as a way of expressing feelings such as disappointment, tiredness, or pleasure.","ex":{"en":"Michael sighed wearily","cn":"迈克尔疲惫地叹了口气。"}},{"pos":"VERB 动词","cn":"叹着气说;叹息道","en":"If you sigh something, you say it with a sigh.","ex":{"en":"'Oh, sorry. I forgot.' — 'Everyone forgets,' the girl sighed.","cn":"“哦，对不起，我忘了。”——“每个人都有忘事的时候，”那女孩叹着气说道。"}},{"pos":"VERB 动词","cn":"(风)发出叹息般的声音，悲鸣","en":"If the wind sighs through a place, it moves through the place with a sound like a sigh.","ex":{"en":"The wind sighed through the valley.","cn":"风在山谷里呼啸而过。"}},{"pos":"PHRASE 短语","cn":"松了口气;如释重负","en":"If people breathe or heave a sigh of relief, they feel happy that something unpleasant has not happened or is no longer happening.","ex":{"en":"There was a big sigh of relief once the economic reform plan was agreed","cn":"经济改革计划一获批准，人们都大大舒了一口气。"}}]},"media":{"uk":"media/uk/sigh__gb_1.mp3","us":"media/us/sigh__us_1.mp3"},"examples":[{"en":"‘Oh well, better luck next time,’ she sighed. “","cn":"唉，就这样了，但愿下一次运气好些。”她叹息道。"},{"en":"She sighed with relief that it was all over.","cn":"事情总算全都过去了，她轻松地舒了一口气。"}]},"situated":{"media":{"uk":"media/uk/situated__gb_1.mp3","us":"media/us/situated__us_1.mp3"},"oxford":{"phon":"ˈsɪtʃueɪtɪd","pos":"adjective","senses":[{"en":"in a particular place or position","cn":"位于；坐落在","ex":{"en":"My bedroom was situated on the top floor of the house.","cn":"我的卧室在房子的顶层。"}},{"en":"in a particular situation or in particular circumstances","cn":"处于…状况；处境…","ex":{"en":"Small businesses are well situated to benefit from the single market.","cn":"小企业所处的形势有利于从单一市场中受益。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"坐落在…的;位于…的","en":"If something is situated in a particular place or position, it is in that place or position.","ex":{"en":"His hotel is situated in one of the loveliest places on the Loire","cn":"他下榻的旅馆位于卢瓦河畔最漂亮的地方之一。"}}]},"examples":[{"en":"The hotel is beautifully situated in a quiet spot near the river.","cn":"旅馆环境优美，坐落在河边一个僻静的地方。"},{"en":"All the best theatres and restaurants are situated within a few minutes' walk of each other.","cn":"所有最好的剧院和饭店相隔只有几分钟的路。"}]},"size":{"media":{"uk":"media/uk/size__gb_1.mp3","us":"media/us/size__us_1.mp3"},"oxford":{"phon":"saɪz","pos":"noun","senses":[{"en":"how large or small a person or thing is","cn":"大小","g":"[uncountable, countable]","sc":"how large/small","ex":{"en":"population/sample/group/class size","cn":"人口／样本／小组／班级的大小"}},{"en":"the large amount or extent of something","cn":"大量；大规模","g":"[uncountable]","sc":"how large/small","ex":{"en":"You should have seen the size of their house!","cn":"你真该看看他们的房子有多大！"}},{"en":"one of a number of standard measurements in which clothes, shoes and other goods are made and sold","cn":"尺码；号","g":"[countable, uncountable]","sc":"of clothes/shoes/goods","ex":{"en":"The jacket was the wrong size.","cn":"这件夹克尺码不对。"}},{"en":"having the size mentioned","cn":"…大小的；…规模的","sc":"-sized/-size","ex":{"en":"a medium-sized house","cn":"中等大小的房子"}},{"en":"a sticky substance that is used for making material stiff or for preparing walls for wallpaper","cn":"（使织物等坚挺的）胶料，浆料；（贴壁纸用的）涂料","g":"[uncountable]","sc":"sticky substance"},{"en":"to mark the size of something; to give a size to something","cn":"标定…的大小；确定…的尺寸","g":"[usually passive]","sc":"give size","ex":{"en":"The screws are sized in millimetres.","cn":"这些螺丝是用毫米标定大小的。"},"pos":"verb"},{"en":"to change the size of something","cn":"改变…的大小","g":"[usually passive]","sc":"change size","ex":{"en":"The fonts can be sized according to what effect you want.","cn":"可根据你想要的效果改变字号。"},"pos":"verb"},{"en":"to cover something with a sticky substance called size","cn":"上胶料；上浆；上涂料","sc":"make sticky","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"大小;数量;规模","en":"The size of something is how big or small it is. Something's size is determined by comparing it to other things, counting it, or measuring it.","ex":{"en":"Scientists have found the bones of a hoofed grazing animal about the size of a small horse","cn":"科学家们已经发现了一种约有马驹般大小的有蹄草食性动物的骨骼。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"巨大;庞大","en":"The size of something is the fact that it is very large.","ex":{"en":"He knows the size of the task","cn":"他明白这个任务有多艰巨。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指衣服、鞋子等的)尺寸，尺码，号","en":"A size is one of a series of graded measurements, especially for things such as clothes or shoes.","ex":{"en":"My sister is the same height but only a size 12","cn":"我姐姐是一样的身高，不过只穿 12 号的。"}},{"pos":"PHRASE 短语","cn":"使有自知之明;灭…的嚣张气焰","en":"If someone is cut down to size, something happens to make them realize that they are not as important as they think they are.","ex":{"en":"The once-powerful post unions have been cut down to size.","cn":"一度很强势的邮政联盟已经威风不再。"}},{"pos":"PHRASE 短语","cn":"把…修改到合适的尺寸","en":"If an object is cut to size, its size is altered to make it suitable for a particular purpose.","ex":{"en":"Every piece of timber was planed, cut to size and stained with cedar preservative.","cn":"每根木材都被刨平了，切割成一定尺寸，并涂上了雪松防腐剂。"}},{"pos":"PHRASE 短语","cn":"(试试)大小;(试试)是否合适","en":"If you try something on for size, you try it to see if it is suitable for you.","ex":{"en":"She was trying on an $8,000 jacket for size","cn":"她正在试穿一件价值 8,000 美元的短外套。"}},{"pos":"","cn":"","en":"comes in all shapes and sizes→see: ;"},{"pos":"","cn":"","en":"相关词组：size up"}]},"examples":[{"en":"‘So they won't pay up?’ ‘That's about the size of it.’ “","cn":"这么说他们不愿意打算还清欠款？” “基本是这样。”"},{"en":"The facilities are excellent for a town that size.","cn":"对于如此规模的一个城镇来说，其市政设施堪称一流。"}]},"sixth":{"oxford":{"phon":"sɪksθ","pos":"ordinal number","senses":[{"en":"6th","cn":"第六","ex":{"en":"Today is the sixth (of May).","cn":"今天是五月六日。"}},{"en":"each of six equal parts of something","cn":"六分之一","pos":"noun"}]},"collins":{"senses":[{"pos":"ORD 序数词","cn":"第六","en":"The sixth item in a series is the one that you count as number six.","ex":{"en":"...the sixth round of the World Cup.","cn":"世界杯第六轮的比赛"}},{"pos":"FRACTION 分数词","cn":"六分之一","en":"A sixth is one of six equal parts of something.","ex":{"en":"The company yesterday shed a sixth of its workforce.","cn":"这家公司昨天裁掉了 1/6 的员工。"}}]},"media":{"uk":"media/uk/sixth__gb_1.mp3","us":"media/us/sixth__us_1.mp3"},"examples":[{"en":"About one sixth of the children admitted to taking drugs.","cn":""},{"en":"her sixth birthday","cn":"她的6岁生日"}]},"single":{"media":{"img":["media/pic/beds_comp.jpg","media/thumb/singlebed.jpg"],"uk":"media/uk/single__gb_1.mp3","us":"media/us/single__us_1.mp3"},"oxford":{"phon":"ˈsɪŋɡl","pos":"adjective","senses":[{"en":"only one","cn":"仅有一个的；单一的；单个的","g":"[only before noun]","lab":"British English","sc":"one","ex":{"en":"He sent her a single red rose.","cn":"他送给她一枝红玫瑰。"}},{"en":"intended to be used by only one person","cn":"单人的","g":"[only before noun]","sc":"for one person","ex":{"en":"a single room","cn":"单人房间"}},{"en":"not married or having a romantic relationship with somebody","cn":"单身的；未婚的；无伴侣的","sc":"not married","ex":{"en":"a single person/woman/man","cn":"单身人士／女士／男士"}},{"en":"a single ticket, etc. can be used for travelling to a place but not back again","cn":"单程的","g":"[only before noun]","lab":"British English","sc":"ticket","ex":{"en":"a single ticket","cn":"单程票"}},{"en":"used to emphasize that you are referring to one particular person or thing on its own","cn":"（特指某人或事物）","g":"[only before noun]","sc":"for emphasis","ex":{"en":"Unemployment is the single most important factor in the growing crime rates.","cn":"失业是犯罪率日益上升最重要的一个因素。"}},{"en":"a ticket that allows you to travel to a place but not back again","cn":"单程票","g":"[countable]","lab":"British English","sc":"ticket","ex":{"en":"How much is a single to York?","cn":"去约克的单程票多少钱？"},"pos":"noun"},{"en":"a room in a hotel, etc. for one person","cn":"（旅馆等的）单人房间","g":"[countable]","sc":"room","ex":{"en":"Singles are available from £50 per night.","cn":"单人房间一晚 50 英镑起。"},"pos":"noun"},{"en":"people who are not married and do not have a romantic relationship with somebody else","cn":"单身者；无伴侣者","g":"[plural]","sc":"unmarried people","ex":{"en":"They organize parties for singles.","cn":"他们为单身者组织聚会。"},"pos":"noun"},{"en":"a piece of recorded music, usually popular music, that consists of one song; a CD that a single is recorded on","cn":"单曲（常指流行音乐）；单曲激光唱片","g":"[countable]","sc":"music","ex":{"en":"The band releases its new single next week.","cn":"这支乐队将于下周发行新的单曲唱片。"},"pos":"noun"},{"en":"a note that is worth one dollar","cn":"一美元纸币","g":"[countable]","lab":"North American English","sc":"money","pos":"noun"},{"en":"a game when only one player plays against one other; a series of two or more of these games","cn":"单打（比赛）","g":"[uncountable + singular or plural verb]","sc":"in sport","ex":{"en":"the women’s singles champion","cn":"女子单打冠军"},"pos":"noun"},{"en":"a hit from which a player scores one run (= point)","cn":"一分打","g":"[countable]","sc":"in sport","pos":"noun"},{"en":"a hit that only allows the player to run to first base","cn":"一垒打","g":"[countable]","sc":"in sport","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"单个的;单一的;唯一的","en":"You use single to emphasize that you are referring to one thing, and no more than one thing.","ex":{"en":"A single shot rang out","cn":"传来一声响亮的枪声。"}},{"pos":"ADJ 形容词","cn":"单独的;各自的","en":"You use single to indicate that you are considering something on its own and separately from other things like it.","ex":{"en":"Every single house in town had been damaged","cn":"镇上每栋房子都遭到了破坏。"}},{"pos":"ADJ 形容词","cn":"单身的;未婚的","en":"Someone who is single is not married. You can also use single to describe someone who does not have a girlfriend or boyfriend.","ex":{"en":"Is it difficult being a single mother?","cn":"做单身妈妈难吗？"}},{"pos":"ADJ 形容词","cn":"(房间)单人的，单人使用的","en":"A single room is a room intended for one person to stay or live in.","ex":{"en":"A single room at the Astir Hotel costs £56 a night.","cn":"阿斯蒂尔酒店的单人间价格是 56 英镑一晚。"}},{"pos":"ADJ 形容词","cn":"(床)单人的","en":"A single bed is wide enough for one person to sleep in."},{"pos":"ADJ 形容词","cn":"(票)单程的","en":"A single ticket is a ticket for a journey from one place to another but not back again.","ex":{"en":"The price of a single ticket is thirty-nine pounds.","cn":"单程票的价格是 39 英镑。"}},{"pos":"N-COUNT 可数名词","cn":"(只录几首短歌的)单曲唱片;(激光唱片上的)主打歌曲，单曲","en":"A single or a CD single is a CD which has a few short songs on it. You can also refer to the main song on a CD as a single .","ex":{"en":"Kids today don't buy singles","cn":"现在的孩子都不买单曲唱片了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(网球或羽毛球的)单打比赛","en":"Singles is a game of tennis or badminton in which one player plays another. The plural singles can be used to refer to one or more of these matches.","ex":{"en":"Boris Becker of Germany won the men's singles","cn":"德国的鲍里斯·贝克尔赢得男单冠军。"}},{"pos":"N-COUNT 可数名词","cn":"(板球中的)一分打;(棒球中的)一垒打","en":"In cricket, a single is a hit from which one run is scored. In baseball, a single is a hit by which a batter reaches first base."},{"pos":"See also:","cn":"","en":"in single file→see: ;"},{"pos":"","cn":"","en":"相关词组：single out"}]},"examples":[{"en":"All these jobs can now be done by one single machine.","cn":"所有这些工作现在只用一台机器就可以完成。"},{"en":"He was singled out as the outstanding performer of the games.","cn":"他被评选为这次运动会表现最出色的运动员。"}]},"sister":{"media":{"uk":"media/uk/sister__gb_1.mp3","us":"media/us/sister__us_1.mp3"},"oxford":{"phon":"ˈsɪstə(r)","pos":"noun","senses":[{"en":"a girl or woman who has the same mother and father as another person","cn":"姐姐；妹妹","lab":"informal","ex":{"en":"She's my sister.","cn":"她是我姐姐。"}},{"en":"used for talking to or about other members of a women’s organization or other women who have the same ideas, purpose, etc. as yourself","cn":"（称志同道合者）姐妹","ex":{"en":"They supported their sisters in the dispute.","cn":"在争论中，她们支持自己的姐妹。"}},{"en":"a senior female nurse who is in charge of a hospital ward","cn":"护士长","lab":"British English"},{"en":"a female member of a religious group, especially a nun","cn":"女教友；（尤指）修女","ex":{"en":"Sister Mary","cn":"修女玛丽"}},{"en":"(in the US) a member of a sorority (= a club for a group of female students at a college or university)","cn":"（美国大学）女生联谊会会员","ex":{"en":"Carolyn's sorority sisters at Indiana University","cn":"卡罗琳在印第安纳大学女生联谊会的姐妹们"}},{"en":"used by black people as a form of address for a black woman","cn":"（黑人的互相称谓）大姐","lab":"North American English, informal，，"},{"en":"a thing that belongs to the same type or group as something else","cn":"同类型的；同一批的；如同姐妹的","ex":{"en":"our sister company in Italy","cn":"我们在意大利的姊妹公司"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"姐;妹","en":"Your sister is a girl or woman who has the same parents as you.","ex":{"en":"His sister Sarah helped him.","cn":"他姐姐萨拉帮助了他。"}},{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"修女;女教友","en":"Sister is a title given to a woman who belongs to a religious community.","ex":{"en":"Sister Francesca entered the chapel.","cn":"弗朗西丝卡修女走进了小教堂。"}},{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"护士长;高级护士","en":"A sister is a senior female nurse who supervises part of a hospital.","ex":{"en":"Ask to speak to the sister on the ward","cn":"请求和病房里的护士长说话。"}},{"pos":"N-COUNT 可数名词","cn":"(同一种族、宗教、国家或职业的)姐妹;同道中的女性;志同道合的女士","en":"You can describe a woman as your sister if you feel a connection with her, for example because she belongs to the same race, religion, country, or profession.","ex":{"en":"Modern woman has been freed from many of the duties that befell her sisters in times past.","cn":"现代女性已经从许多压在旧时女性身上的责任中解放出来了。"}},{"pos":"ADJ 形容词","cn":"同类型的;相关联的;如同姐妹的","en":"You can use sister to describe something that is of the same type or is connected in some way to another thing you have mentioned. For example, if a company has a sister company, they are connected.","ex":{"en":"...the International Monetary Fund and its sister organisation, the World Bank.","cn":"国际货币基金组织及其姊妹机构——世界银行"}}]},"examples":[{"en":"My best friend has been like a sister to me (= very close).","cn":"我最要好的一个朋友待我亲如姐妹。"},{"en":"They supported their sisters in the dispute.","cn":"在争论中，她们支持自己的姐妹。"}]},"singular":{"oxford":{"phon":"ˈsɪŋɡjələ(r)","pos":"noun","senses":[{"en":"a form of a noun or verb that refers to one person or thing","cn":"单数；单数形式","ex":{"en":"The singular of ‘bacteria’ is ‘bacterium’.","cn":"bacteria 的单数形式是 bacterium。"}},{"en":"connected with or having the singular form","cn":"单数的；单数形式的","lab":"grammar","ex":{"en":"a singular noun/verb/ending","cn":"单数名词／动词／词尾"},"pos":"adjective"},{"en":"very great or obvious","cn":"非凡的；突出的；显著的","lab":"formal","ex":{"en":"landscape of singular beauty","cn":"无比优美的风景"},"pos":"adjective"},{"en":"unusual; strange","cn":"奇特的；奇怪的；异常的","lab":"literary","ex":{"en":"a singular style of dress","cn":"奇特的服装款式"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"单数的;单数形式的","en":"The singular form of a word is the form that is used when referring to one person or thing.","ex":{"en":"...the fifteen case endings of the singular form of the Finnish noun","cn":"芬兰语的名词单数形式的 15 种格尾"}},{"pos":"N-SING 单数名词","cn":"(名词的)单数，单数形式","en":"The singular of a noun is the form of it that is used to refer to one person or thing.","ex":{"en":"The singular of Inuit is Inuk.","cn":"Inuit (依努依特人)的单数形式是 Inuk。"}},{"pos":"ADJ 形容词","cn":"非凡的;突出的;显著的","en":"Singular means very great and remarkable.","ex":{"en":"...a smile of singular sweetness","cn":"无比甜美的微笑"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"异常的;奇特的;奇怪的","en":"If you describe someone or something as singular, you mean that they are strange or unusual.","ex":{"en":"Cardinal Meschia was without doubt a singular character","cn":"红衣主教梅斯基亚无疑是个怪人。"}}]},"media":{"uk":"media/uk/singular__gb_1.mp3","us":"media/us/singular__us_1.mp3"},"examples":[{"en":"The singular of ‘bacteria’ is ‘bacterium’. * bacteria","cn":"的单数形式是 bacterium。"},{"en":"The verb should be in the singular.","cn":"这个动词应当用单数形式。"}]},"six":{"media":{"uk":"media/uk/six__gb_1.mp3","us":"media/us/six__us_1.mp3"},"oxford":{"phon":"sɪks","pos":"number","senses":[{"en":"6","cn":"六","ex":{"en":"There are six cookies left.","cn":"还剩下六块饼干。"}},{"en":"a hit that scores six runs (= points)","cn":"六分打；六分球"}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 6","en":"Six is the number 6.","ex":{"en":"...a glorious career spanning more than six decades.","cn":"延续 60 余载的辉煌事业"}},{"pos":"N-COUNT 可数名词","cn":"(板球中)得 6 分的击球，以 6 分记的击球","en":"In cricket, if a player hits a six, they score six runs by hitting the ball so that it crosses the boundary at the edge of the playing area before it touches the ground."},{"pos":"PHRASE 短语","cn":"使颇为不安;使受严重影响","en":"If someone or something is hit for six or knocked for six, they are very upset or badly affected by an experience or piece of news.","ex":{"en":"The loss of my wife hit me for six; it took me months to recover","cn":"丧妻之痛令我彻底崩溃，几个月之后才恢复过来。"}},{"pos":"PHRASE 短语","cn":"困惑的;混乱的;杂乱无章的","en":"If you say that someone or something is at sixes and sevens, you mean that they are confused or disorganized.","ex":{"en":"The government is at sixes and sevens over the issue of domestic security.","cn":"在国内安全问题上，政府一片混乱。"}}]},"examples":[{"en":"She arrived just after six (= six o'clock ) .","cn":"她六点刚过就到了。"},{"en":"He learnt to play the violin when he was six (= six years old ) .","cn":"他六岁学拉小提琴。"}]},"sidewalk":{"media":{"uk":"media/uk/sidewalk__gb_1.mp3","us":"media/us/sidewalk__us_1.mp3"},"oxford":{"phon":"ˈsaɪdwɔːk","pos":"noun","senses":[{"en":"a flat part at the side of a road for people to walk on","cn":"（马路边的）人行道","ex":{"en":"Elm trees lined the sidewalks.","cn":"路边有一排榆树。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"人行道","en":"A sidewalk is a path with a hard surface by the side of a road.","ex":{"en":"Two men and a woman were walking briskly down the sidewalk toward him.","cn":"两名男子和一名女子正轻快地沿人行道朝他走过去。"}}]}},"sink":{"media":{"uk":"media/uk/sink__gb_1.mp3","us":"media/us/sink__us_1.mp3","img":["media/ldoce/img/sink.jpg"]},"oxford":{"phon":"sɪŋk","pos":"verb","senses":[{"en":"to go down below the surface or towards the bottom of a liquid or soft substance","cn":"下沉；下陷；沉没","g":"[intransitive]","sc":"in water/mud, etc.","ex":{"en":"The ship sank to the bottom of the sea.","cn":"船沉入海底。"}},{"en":"to damage a boat or ship so that it goes below the surface of the sea, etc.","cn":"使下沉；使沉没","g":"[transitive]","sc":"boat","ex":{"en":"The battleship was sunk by a torpedo.","cn":"战列舰被鱼雷击沉。"}},{"en":"to move downwards, especially by falling or sitting down","cn":"倒下；坐下","g":"[intransitive]","sc":"fall/sit down","ex":{"en":"I sank into an armchair.","cn":"我坐到扶手椅上。"}},{"en":"to move slowly downwards","cn":"下沉；下陷；沉降","g":"[intransitive]","sc":"move downwards","ex":{"en":"The sun was sinking in the west.","cn":"太阳西下。"}},{"en":"to decrease in amount, volume, strength, etc.","cn":"降低；减少；减弱","g":"[intransitive]","sc":"become weaker","ex":{"en":"The pound has sunk to its lowest recorded level against the dollar.","cn":"英镑对美元的比价降到了有记录以来最低水平。"}},{"en":"to become quieter","cn":"变低；变小","g":"[intransitive]","sc":"of voice","ex":{"en":"Her voice sank to a whisper.","cn":"她的声音变成了耳语。"}},{"en":"to make a deep hole in the ground","cn":"挖，掘（深坑、深洞）","g":"[transitive]","sc":"dig in ground","ex":{"en":"to sink a well/shaft/mine","cn":"掘水井／竖井／矿井"}},{"en":"to place something in the ground by digging","cn":"埋入；打下","g":"[transitive]","sc":"dig in ground","ex":{"en":"to sink a post into the ground","cn":"在地下埋入一根杆子"}},{"en":"to prevent somebody or somebody’s plans from succeeding","cn":"使失败；使受挫；阻挠","g":"[transitive]","lab":"informal","sc":"prevent success","ex":{"en":"I think I've just sunk my chances of getting the job.","cn":"我想，我刚刚葬送了得到那份工作的机会。"}},{"en":"to hit a ball into a hole in golf or snooker","cn":"（高尔夫球）击球入洞；（斯诺克）击球入袋","g":"[transitive]","sc":"ball","ex":{"en":"He sank a 12-foot putt to win the match.","cn":"他以一记 12 英尺的轻击入洞赢了比赛。"}},{"en":"to drink something quickly, especially a large amount of alcohol","cn":"猛喝；灌","g":"[transitive]","lab":"British English, informal，，","sc":"alcohol","ex":{"en":"They sank three pints each in 10 minutes.","cn":"他们在 10 分钟内每人喝了三品脱。"}},{"en":"a large open container in a kitchen that has taps to supply water and that you use for washing dishes in","cn":"（厨房里的）洗涤池，洗碗槽","ex":{"en":"Don't just leave your dirty plates in the sink!","cn":"别把脏盘子往洗碗槽里一放就不管了！"},"pos":"noun"},{"en":"a large bowl that has taps and is fixed to the wall in a bathroom, used for washing your hands and face in","cn":"（卫生间里的）洗手盆，洗脸盆","lab":"both especially North American English","pos":"noun"},{"en":"located in a poor area where social conditions are bad","cn":"位于贫穷地区的；贫民窟的","ex":{"en":"the misery of life in sink estates","cn":"贫民窟里的悲惨生活"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(厨房里的)洗涤池，洗碗槽，水槽","en":"A sink is a large fixed container in a kitchen, with taps to supply water. It is mainly used for washing dishes.","ex":{"en":"The sink was full of dirty dishes.","cn":"水槽里堆满了脏碟子。"}},{"pos":"N-COUNT 可数名词","cn":"同 washbasin 或 basin","en":"A sink is the same as a washbasin or basin .","ex":{"en":"The bathroom is furnished with 2 toilets, 2 showers, and 2 sinks.","cn":"卫生间里装了两个抽水马桶、两个淋浴器、和两个洗脸盆。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)下沉;(使)沉没","en":"If a boat sinks or if someone or something sinks it, it disappears below the surface of a mass of water.","ex":{"en":"In a naval battle your aim is to sink the enemy's ship","cn":"在海战中目标就是击沉敌船。"}},{"pos":"VERB 动词","cn":"下沉;沉没","en":"If something sinks, it disappears below the surface of a mass of water.","ex":{"en":"A fresh egg will sink and an old egg will float.","cn":"新鲜鸡蛋会沉下去而不新鲜的会浮在上面。"}},{"pos":"VERB 动词","cn":"缓慢下降;下陷;沉降","en":"If something sinks, it moves slowly downwards.","ex":{"en":"Far off to the west the sun was sinking","cn":"远处夕阳西下。"}},{"pos":"VERB 动词","cn":"坐下;跪下","en":"If you sink, you move into a lower position, for example by sitting down in a chair or kneeling.","ex":{"en":"Kate laughed, and sank down again to her seat","cn":"凯特笑了，又坐回到她的座位上。"}},{"pos":"VERB 动词","cn":"下降;减少;下跌","en":"If something sinks to a lower level or standard, it falls to that level or standard.","ex":{"en":"Share prices would have sunk — hurting small and big investors","cn":"股票价格就会下跌——大小投资者均会遭受打击。"}},{"pos":"ADJ 形容词","cn":"贫困的;条件不好的","en":"People use sink school or sink estate to refer to a school or housing estate that is in a very poor area with few resources.","ex":{"en":"...unemployed teenagers from sink estates","cn":"来自贫困地区的无业青少年"}},{"pos":"VERB 动词","cn":"(声音)变小，降低，变低","en":"If your voice sinks, it becomes quieter.","ex":{"en":"Her voice sank, and he moved closer to catch what she was saying","cn":"她的声音变小了，他走近了些想听清楚她在说什么。"}},{"pos":"VERB 动词","cn":"逐渐陷入(某种令人不快的心情、状态或处境)","en":"To sink into an unpleasant or undesirable mood, situation, or state means to pass gradually into it.","ex":{"en":"She'd sometimes sink into depression","cn":"她有时会陷入忧郁之中。"}},{"pos":"VERB 动词","cn":"(心情)变得沉重;(情绪)变低落","en":"If your heart or your spirits sink, you become depressed or lose hope.","ex":{"en":"My heart sank because I thought he was going to dump me for another girl","cn":"我的心情一下子很沮丧，以为他要为了另一个女孩和我分手。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)埋入;(把…)打入;(使)插入","en":"If something sharp sinks or is sunk into something solid, it goes deeply into it.","ex":{"en":"He sinks the needle into my arm","cn":"他将针插入我的胳膊。"}},{"pos":"VERB 动词","cn":"挖，掘(井、矿井、深洞等)","en":"If someone sinks a well, mine, or other large hole, they make a deep hole in the ground, usually by digging or drilling.","ex":{"en":"...the site where Stephenson sank his first mineshaft","cn":"斯蒂芬森挖掘第一口竖井的地方"}},{"pos":"VERB 动词","cn":"把(资金)投入(企业或项目)","en":"If you sink money into a business or project, you spend money on it in the hope of making more money.","ex":{"en":"He has already sunk $25million into the project.","cn":"他在这项目上已经投资了 2,500 万美元了。"}},{"pos":"VERB 动词","cn":"猛喝，灌(酒)","en":"If someone sinks a number of alcoholic drinks, they drink them quickly.","ex":{"en":"She sank two glasses of white wine.","cn":"她一口气干了两杯白葡萄酒。"}},{"pos":"VERB 动词","cn":"(高尔夫球)击(球)入洞;(斯诺克)击(球)入袋","en":"In golf, snooker, and some other games, if you sink a ball or a putt, you successfully hit the ball into a hole.","ex":{"en":"He sank two crucial putts in the last three holes.","cn":"他在最后的三洞中完成了两个非常关键的击球入洞。"}},{"pos":"PHRASE 短语","cn":"自己努力以求生存;不自立,必沉沦","en":"If you say that someone will have to sink or swim, you mean that they will have to succeed through their own efforts, or fail. to sink without trace→see: ;","ex":{"en":"The government doesn't want to force inefficient firms to sink or swim too quickly","cn":"政府并不想迫使效率低的公司过快地自生自灭。"}},{"pos":"","cn":"","en":"相关词组：sink in"}]},"examples":[{"en":"I think I've just sunk my chances of getting the job.","cn":"我想，都是我自己不好，葬送了得到那份工作的机会。"},{"en":"Stealing from your friends? How could you sink so low?","cn":"偷到你的朋友头上了？你怎么能堕落到这种地步呢？"}]},"siege":{"media":{"uk":"media/uk/siege__gb_1.mp3","us":"media/us/siege__us_1.mp3"},"oxford":{"phon":"siːdʒ","pos":"noun","senses":[{"en":"a military operation in which an army tries to capture a town by surrounding it and stopping the supply of food, etc. to the people inside","cn":"（军队对城镇的）围困，包围，围攻，封锁","ex":{"en":"the siege of Troy","cn":"特洛伊之围"}},{"en":"a situation in which the police surround a building where people are living or hiding, in order to make them come out","cn":"（警察对建筑物的）包围，封锁","ex":{"en":"The siege was finally brought to an end when the terrorists surrendered.","cn":"随着恐怖分子投降，围攻终于结束。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(军队或警察对某地的)围困，包围，围攻","en":"A siege is a military or police operation in which soldiers or police surround a place in order to force the people there to come out or give up control of the place.","ex":{"en":"We must do everything possible to lift the siege","cn":"我们必须尽一切可能解除包围。"}},{"pos":"PHRASE 短语","cn":"(警察、士兵、新闻记者等)包围，围住","en":"If police, soldiers, or journalists lay siege to a place, they surround it in order to force the people there to come out or give up control of the place.","ex":{"en":"The rebels laid siege to the governor's residence","cn":"叛乱者包围了总督府。"}},{"pos":"PHRASE 短语","cn":"遭受严厉批评;承受巨大压力","en":"If someone or something is under siege, they are being severely criticized or put under a great deal of pressure.","ex":{"en":"The guy'll think he's under siege","cn":"那家伙会认为他承受了巨大压力。"}}]},"examples":[{"en":"The police placed the city centre under a virtual state of siege (= it was hard to get in or out).","cn":"警方可说是已封锁了市中心。"},{"en":"The siege was finally lifted (= ended) after six months.","cn":"六个月后封锁最终解除了。"}]},"sing":{"media":{"uk":"media/uk/sing__gb_1.mp3","us":"media/us/sing__us_1.mp3"},"oxford":{"phon":"sɪŋ","pos":"verb","senses":[{"en":"to make musical sounds with your voice in the form of a song or tune","cn":"唱（歌）；演唱","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"I just can't sing in tune!","cn":"我一唱就走调！"}},{"en":"to make high musical sounds","cn":"鸣；啼；啼啭","g":"[intransitive]","ex":{"en":"The birds were singing outside my window.","cn":"鸟儿在我窗外啼啭。"}},{"en":"to make a high ringing sound like a whistle (= a small metal or plastic tube that you blow to make a loud high sound)","cn":"呜呜作响；发嗖嗖声","g":"[intransitive]","ex":{"en":"Bullets sang past my ears.","cn":"子弹嗖嗖地从我耳边飞过。"}},{"en":"an act of singing","cn":"唱歌","ex":{"en":"Let's have a sing.","cn":"我们来唱歌吧。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"","cn":"唱(歌);演唱","en":"When you sing, you make musical sounds with your voice, usually producing words that fit a tune.","ex":{"en":"I can't sing","cn":"我不会唱歌。"}},{"pos":"","cn":"(鸟类或昆虫)鸣叫，啼，啁啾，啼啭","en":"When birds or insects sing, they make pleasant high-pitched sounds.","ex":{"en":"Birds were already singing in the garden.","cn":"小鸟已经在花园里歌唱了。"}},{"pos":"","cn":"(尤指同一组织里的人)口径一致，意见一致","en":"If you say that people, especially people in the same organization, are singing from the same hymn sheet or are singing from the same song sheet, you mean that they are saying the same things in public about something and appear to agree about it.","ex":{"en":"We should bring together the departments so that we're all singing from the same hymn sheet.","cn":"我们应该把各部门联合起来，这样我们就能意见一致了。"}},{"pos":"See also:","cn":"","en":"to sing someone's praises→see: ;"},{"pos":"","cn":"","en":"相关词组：sing along sing out"}]},"examples":[{"en":"A voice suddenly sang out above the rest.","cn":"在一片嘈杂声中突然传出一个人的声音。"},{"en":"Now I'd like to sing a song by the Beatles.","cn":"现在我来唱一首披头士乐队的歌。"}]},"simplify":{"media":{"uk":"media/uk/simplify__gb_1.mp3","us":"media/us/simplify__us_1.mp3"},"oxford":{"phon":"ˈsɪmplɪfaɪ","pos":"verb","senses":[{"en":"to make something easier to do or understand","cn":"使简化；使简易","ex":{"en":"The application forms have now been simplified.","cn":"申请表格现已简化了。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"简化;使易懂;使简洁","en":"If you simplify something, you make it easier to understand or you remove the things which make it complex.","ex":{"en":"...a plan to simplify the complex social security system","cn":"简化复杂的社会保障体系的计划"}}]},"examples":[{"en":"I hope his appointment will simplify matters.","cn":"我希望他任命以后事情会好办一些。"},{"en":"a simplified version of the story for young children","cn":"供小朋友阅读的故事简写本"}]},"sizes":{"oxford":{"phon":"saɪz","pos":"noun","senses":[{"en":"how large or small a person or thing is","cn":"大小"},{"en":"the large amount or extent of sth","cn":"大量；大规模"}]},"media":{"uk":"media/uk/size__gb_1.mp3","us":"media/us/size__us_1.mp3"}},"sit":{"media":{"uk":"media/uk/sit__gb_1.mp3","us":"media/us/sit__us_1.mp3"},"oxford":{"phon":"sɪt","pos":"verb","senses":[{"en":"to rest your weight on your bottom with your back straight, for example on/in a chair","cn":"坐","g":"[intransitive]","sc":"on chair, etc.","ex":{"en":"She sat and stared at the letter in front of her.","cn":"她坐在那儿，凝视着面前的那封信。"}},{"en":"to put somebody in a sitting position","cn":"使坐；使就座","g":"[transitive]","sc":"on chair, etc.","ex":{"en":"He lifted the child and sat her on the wall.","cn":"他抱起孩子，让她坐在墙头上。"}},{"en":"to be in a particular place","cn":"位于（某处）；坐落在；被放在","g":"[intransitive]","sc":"of things","ex":{"en":"A large bus was sitting outside.","cn":"外面停着一辆大巴士。"}},{"en":"to have an official position as something or as a member of something","cn":"（在…中）任职；任（…的）代表；担任","g":"[intransitive]","sc":"have official position","ex":{"en":"He was sitting as a temporary judge.","cn":"由他担任临时法官。"}},{"en":"to meet in order to do official business","cn":"开会；开庭","g":"[intransitive]","sc":"of parliament, etc.","ex":{"en":"Parliament sits for less than six months of the year.","cn":"议会一年的开会时间不足六个月。"}},{"en":"to do an exam","cn":"参加考试；应试","g":"[transitive, intransitive]","lab":"rather formal","sc":"exam","ex":{"en":"Candidates will sit the examinations in June.","cn":"考生将在六月参加考试。"}},{"en":"to rest on a branch, etc. or to stay on a nest to keep the eggs warm","cn":"停落；栖；孵（卵）","g":"[intransitive]","sc":"of bird"},{"en":"to sit on its bottom with its front legs straight","cn":"蹲；坐","g":"[intransitive]","sc":"of dog","ex":{"en":"Rover! Sit!","cn":"罗弗！蹲下！"}},{"en":"to take care of babies or children for a short time while their parents are out","cn":"代人临时照看小孩；当临时保姆","g":"[intransitive]","lab":"especially North American English","sc":"take care of children","ex":{"en":"Who's sitting for you?","cn":"谁给你看着孩子呢？"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"坐","en":"If you are sitting somewhere, for example in a chair, your bottom is resting on the chair and the upper part of your body is upright.","ex":{"en":"Mother was sitting in her chair in the kitchen","cn":"妈妈坐在厨房里的椅子上。"}},{"pos":"VERB 动词","cn":"就座;坐下","en":"When you sit somewhere, you lower your body until you are sitting on something.","ex":{"en":"He set the cases against a wall and sat on them","cn":"他把箱子靠墙放好，然后坐在上面。"}},{"pos":"VERB 动词","cn":"使坐下;使就座","en":"If you sit someone somewhere, you tell them to sit there or put them in a sitting position.","ex":{"en":"He used to sit me on his lap","cn":"他过去常常让我坐在他的腿上。"}},{"pos":"VERB 动词","cn":"坐着让人画像(或照相)","en":"If you sit for an artist or photographer, you place yourself in a sitting position so you can be painted or photographed.","ex":{"en":"A person may well have been sitting for the artist for eight hours at a stretch.","cn":"为了让画家给自己画像，一个人很有可能连续坐上 8 个钟头。"}},{"pos":"VERB 动词","cn":"参加(考试)","en":"If you sit an examination, you do it.","ex":{"en":"June and July are the traditional months for sitting exams.","cn":"6 月和 7 月是传统的考试月份。"}},{"pos":"","cn":"","en":"→see usage note at:"},{"pos":"VERB 动词","cn":"作为…的成员","en":"If you sit on a committee or other official group, you are a member of it.","ex":{"en":"He was asked to sit on numerous committees","cn":"他受邀担任过许多委员会的委员。"}},{"pos":"VERB 动词","cn":"(议会)开会;(法院)开庭","en":"When a parliament, legislature, court, or other official body sits, it officially carries out its work.","ex":{"en":"Parliament sits for only 28 weeks out of 52","cn":"在一年 52 周当中只有 28 周是议会开会的时间。"}},{"pos":"VERB 动词","cn":"位于;坐落在","en":"If a building or object sits in a particular place, it is in that place.","ex":{"en":"Our new house sat next to a stream","cn":"我们的新房子坐落在一条小溪旁。"}},{"pos":"VERB 动词","cn":"代人临时照看小孩;当临时保姆","en":"To sit for someone means the same as to babysit for them.","ex":{"en":"I've asked Mum to sit for us next Saturday.","cn":"我已经拜托妈妈下周六为我们临时照看一下孩子。"}},{"pos":"PHRASE 短语","cn":"呆在原处不动;不轻举妄动","en":"If you sit tight, you remain in the same place or situation and do not take any action, usually because you are waiting for something to happen. to sit on the fence→see: ;","ex":{"en":"Sit tight. I'll be right back","cn":"你留在这儿别动，我马上就回来。"}},{"pos":"","cn":"","en":"相关词组：sit around sit back sit by sit down sit in on sit on sit out sit through sit up"}]},"examples":[{"en":"Most of the students sit at least 5 GCSEs.","cn":"大多数学生至少参加 5 门普通中等教育证书考试。"},{"en":"She's not the kind of person who can sit back and let others do all the work.","cn":"她不是那种自己歇着，什么活儿都让别人干的人。"}]},"sickening":{"media":{"uk":"media/uk/sickening__gb_1.mp3","us":"media/us/sickening__us_1.mp3"},"oxford":{"phon":"ˈsɪkənɪŋ","pos":"adjective","senses":[{"en":"making you feel shocked or full of horror","cn":"让人厌恶的；令人作呕的；令人震惊的","ex":{"en":"She was the victim of a sickening attack.","cn":"她是一次令人发指的袭击事件的受害者。"}},{"en":"making you afraid that somebody has been badly hurt or that something has been broken","cn":"给人以不祥感觉的；让人觉得不妙的","g":"[usually before noun]","ex":{"en":"Her head hit the ground with a sickening thud.","cn":"她的头撞在地上，那声闷响让人揪心。"}},{"en":"making you feel jealous or annoyed because you wish you had something that somebody else has","cn":"令人忌妒的；让人烦恼的","lab":"informal","ex":{"en":"‘She's off to the Bahamas for a month.’ ‘How sickening!’","cn":"“她去巴哈马群岛了，要待一个月。”“多让人忌妒哇！”"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人恐惧的;令人厌恶的;令人作呕的","en":"You describe something as sickening when it gives you feelings of horror or disgust, or makes you feel sick in your stomach.","ex":{"en":"This was a sickening attack on a pregnant and defenceless woman","cn":"这一起对毫无防御能力的孕妇的袭击，令人无比震惊。"}}]},"examples":[{"en":"‘She's off to the Bahamas for a month.’ ‘How sickening!’ “","cn":"她去巴哈马群岛了，要待一个月。” “多让人忌妒哇！”"},{"en":"Her head hit the ground with a sickening thud.","cn":"她的头撞在地上，那声闷响让人揪心。"}]},"significant":{"media":{"uk":"media/uk/significant__gb_1.mp3","us":"media/us/significant__us_1.mp3"},"oxford":{"phon":"sɪɡˈnɪfɪkənt","pos":"adjective","senses":[{"en":"large or important enough to have an effect or to be noticed","cn":"有重大意义的；显著的","ex":{"en":"There are no significant differences between the two groups of students.","cn":"这两组学生没有明显差别。"}},{"en":"having a particular meaning","cn":"有某种意义的","ex":{"en":"The fact that her remarks were leaked to the media in advance is highly significant.","cn":"她的话被提前透露给了媒体，这很能说明问题。"}},{"en":"having a special or secret meaning that is not understood by everyone","cn":"别有含义的；意味深长的","g":"[usually before noun]","ex":{"en":"a significant look/smile","cn":"意味深长的眼神／微笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"数量相当大的;显著的","en":"A significant amount or effect is large enough to be important or affect a situation to a noticeable degree.","ex":{"en":"A small but significant number of 11-year-olds are illiterate.","cn":"数量不多但仍有相当一部分 11 岁孩子是文盲。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"重要的;有意义的","en":"A significant fact, event, or thing is one that is important or shows something.","ex":{"en":"Time would appear to be the significant factor in this whole drama.","cn":"时间似乎是整部剧中一个举足轻重的因素。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"别有含义的;意味深远的","en":"A significant action or gesture is intended to have a special meaning.","ex":{"en":"Mrs Bycraft gave Rose a significant glance.","cn":"拜克拉夫特夫人意味深长地瞥了罗丝一眼。"}}]},"examples":[{"en":"It is significant that he changed his will only days before his death.","cn":"他在临终前几天修改遗嘱，这很能说明问题。"},{"en":"The results of the experiment are not statistically significant.","cn":"从统计学的观点看，实验结果意义不明显。"}]},"singing":{"media":{"uk":"media/uk/singing__gb_1.mp3","us":"media/us/singing__us_1.mp3","img":["media/ldoce/img/singing.jpg"]},"oxford":{"phon":"ˈsɪŋɪŋ","pos":"noun","senses":[{"en":"the activity of making musical sounds with your voice","cn":"唱歌；歌唱","ex":{"en":"the beautiful singing of birds","cn":"鸟儿动听的歌唱"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"唱歌;歌唱","en":"Singing is the activity of making musical sounds with your voice.","ex":{"en":"...a people's carnival, with singing and dancing in the streets.","cn":"人们在街头载歌载舞的民族狂欢节"}}]},"examples":[{"en":"She has a beautiful singing voice.","cn":"她有一副唱歌的好嗓子。"},{"en":"There was singing and dancing all night.","cn":"通宵唱歌跳舞。"}]},"sighed":{"oxford":{"phon":"saɪ","pos":"verb","senses":[{"en":"to take and then let out a long deep breath that can be heard, to show that you are disappointed, sad, tired, etc.","cn":"叹气；叹息"},{"en":"to say sth with a sigh","cn":"叹着气说；叹息道"}]}},"silkily":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"looking bright and smooth, and reflecting light","cn":""},{"en":"used about hair or fur that looks shiny and healthy. Glossy magazines and books use expensive shiny paper","cn":""}]},"examples":[{"en":"the silky fabric of her dress","cn":"","src":"ld"}],"media":{"uk":"media/uk/silkily__gb_1.mp3","us":"media/us/silkily__us_1.mp3"},"oxford":{"phon":"ˈsɪlkəli","pos":"adverb","senses":[{"en":"in a smooth and gentle way","cn":"柔和的；温和的；轻柔的","ex":{"en":"‘How have I changed?’ he asked silkily.","cn":"“我哪里变了？”他柔声问道。"}},{"en":"in a way that is soft, smooth and shiny like silk","cn":"丝绸一样的；柔软光洁的","ex":{"en":"Her hair draped silkily over her shoulders.","cn":"她的头发柔滑地披在肩上。"}}]}},"side":{"media":{"img":["media/pic/polygons_comp.jpg","media/thumb/pentagon.jpg"],"uk":"media/uk/side__gb_1.mp3","us":"media/us/side__us_1.mp3"},"oxford":{"phon":"saɪd","pos":"noun","senses":[{"en":"either of the two halves of a surface, an object or an area that is divided by an imaginary central line","cn":"（由想象的中线分出的）一边，一侧","g":"[countable, usually singular]","sc":"left/right","ex":{"en":"the right side of the brain","cn":"脑的右半部"}},{"en":"a position or an area to the left or right of something","cn":"（事物左方或右方的）一旁，一边，一侧","g":"[countable, usually singular]","sc":"left/right","ex":{"en":"He crossed the bridge to the other side of the river.","cn":"他过桥到了河对岸。"}},{"en":"one of the flat surfaces of something that is not the top or bottom, front or back","cn":"侧面","g":"[countable]","sc":"not top or bottom","ex":{"en":"A notice was stuck to the side of the filing cabinet.","cn":"文件柜的一侧贴着一张通知。"}},{"en":"the vertical or sloping surface around something, but not the top or bottom of it","cn":"斜面；垂直面","g":"[countable]","sc":"not top or bottom","ex":{"en":"A path went up the side of the hill.","cn":"沿着山坡往上有一条小路。"}},{"en":"a part near the edge of something; an area just beyond the edge of something","cn":"边缘；边","g":"[countable]","sc":"edge","ex":{"en":"The stream flows into the south side of the lake.","cn":"那小溪汇入湖的南侧。"}},{"en":"either the right or left part of a person’s body, from the armpit (= where the arm joins the body) to the hip (= where the leg joins the body)","cn":"侧面；胁","g":"[countable, usually singular]","sc":"of body","ex":{"en":"I've got a stitch in my side (= a sudden pain from running or laughing).","cn":"我胁下岔气了。"}},{"en":"either of two surfaces of something flat and thin, such as paper or cloth","cn":"一面","g":"[countable]","sc":"of something flat and thin","ex":{"en":"The upper side of the leaf was a much darker green.","cn":"叶子的正面是更深的暗绿色。"}},{"en":"the amount of writing needed to fill one side of a sheet of paper","cn":"一面纸的文字","g":"[countable]","sc":"page","ex":{"en":"He told us not to write more than three sides.","cn":"他告诉我们写字不要超过三面纸。"}},{"en":"any of the flat surfaces of a solid object","cn":"（立体的）面","g":"[countable]","sc":"mathematics","ex":{"en":"A cube has six sides.","cn":"立方体有六面。"}},{"en":"any of the lines that form a flat shape such as a square or triangle","cn":"（平面图形的）边","g":"[countable]","sc":"mathematics","ex":{"en":"a shape with five sides","cn":"五边形"}},{"en":"used in adjectives to state the number or type of sides","cn":"（构成形容词）有…面（或边）的","sc":"-sided","ex":{"en":"a six-sided object","cn":"六面体"}},{"en":"a place or position very near to somebody/something","cn":"近旁；旁边；身边","g":"[singular]","sc":"near to somebody/something","ex":{"en":"Her husband stood at her side.","cn":"她丈夫站在她身边。"}},{"en":"one of the two or more people or groups taking part in an argument, war, etc.","cn":"一方；一派","g":"[countable]","sc":"in war/argument","ex":{"en":"Both sides agreed to restore diplomatic relations.","cn":"双方同意恢复外交关系。"}},{"en":"one of the opinions, attitudes, or positions held by somebody in an argument, a business arrangement, etc.","cn":"一方的意见（或态度、立场）","g":"[countable]","sc":"in war/argument","ex":{"en":"We heard both sides of the argument.","cn":"我们听过了辩论双方的意见。"}},{"en":"a particular aspect of something, especially a situation or a person’s character","cn":"方面","g":"[countable]","sc":"aspect","ex":{"en":"These poems reveal her gentle side.","cn":"这些诗显示出她温柔的一面。"}},{"en":"a feeling that you are better than other people","cn":"优越感；架子","g":"[uncountable]","lab":"British English, informal，，","sc":"feeling that you are better","ex":{"en":"There was no side to him at all.","cn":"他一点架子也没有。"}},{"en":"a sports team","cn":"运动队","g":"[countable]","sc":"sports team","ex":{"en":"As captain, Pryce is confident of leading his side to victory.","cn":"作为队长，普赖斯自信能率领队伍取胜。"}},{"en":"the part of your family that people belong to who are related either to your mother or to your father","cn":"母系；父系；血统","g":"[countable]","sc":"of family","ex":{"en":"a cousin on my father’s side (= a child of my father’s brother or sister)","cn":"我父亲那边的表亲"}},{"en":"a side dish (= a small amount of food, for example a salad, served with the main course of a meal)","cn":"与自己所处情况不同的一面；事物的另一面","g":"[countable]","lab":"North American English, informal，，","sc":"food","ex":{"en":"Your dinner comes with a choice of two sides.","cn":"您的正餐有两道配菜可供选择。"}},{"en":"one of the two halves of an animal that has been killed for meat","cn":"一扇（牛肉／熏猪肉等）","g":"[countable]","sc":"meat"},{"en":"a television channel","cn":"电视频道","g":"[countable]","lab":"old-fashioned, British English, informal，，，，","sc":"TV channel","ex":{"en":"What's on the other side?","cn":"另一个频道上演什么？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一侧;一边;一旁","en":"The side of something is a position to the left or right of it, rather than in front of it, behind it, or on it.","ex":{"en":"On one side of the main entrance there's a red plaque.","cn":"大门口的一侧有块红色的匾额。"}},{"pos":"N-COUNT 可数名词","cn":"侧面","en":"The side of an object, building, or vehicle is any of its flat surfaces which is not considered to be its front, its back, its top, or its bottom.","ex":{"en":"We put a notice on the side of the box.","cn":"我们在箱子的一侧贴了警示标。"}},{"pos":"N-COUNT 可数名词","cn":"(洞或容器垂直的)内侧面，内壁","en":"The sides of a hollow or a container are its inside vertical surfaces.","ex":{"en":"The rough rock walls were like the sides of a deep canal","cn":"凸凹不平的石墙就像一条很深的运河的河岸。"}},{"pos":"N-COUNT 可数名词","cn":"边;边缘","en":"The sides of an area or surface are its edges.","ex":{"en":"Park on the side of the road.","cn":"靠路边停车。"}},{"pos":"N-COUNT 可数名词","cn":"(某地区、表面或物体一分为二的)一边，一侧","en":"The two sides of an area, surface, or object are its two halves.","ex":{"en":"She turned over on her stomach on the other side of the bed","cn":"她翻了个身趴在了床的另一边。"}},{"pos":"N-COUNT 可数名词","cn":"(有车流来往的道路的)方向，侧","en":"The two sides of a road are its two halves on which traffic travels in opposite directions.","ex":{"en":"It had gone on to the wrong side of the road and hit a car coming in the other direction.","cn":"它驶上了逆行车道，撞上了对面驶来的一辆汽车。"}},{"pos":"N-COUNT 可数名词","cn":"(城镇或世界的)另一端，遥远的地方","en":"If you talk about the other side of a town or of the world, you mean a part of the town or of the world that is very far from where you are.","ex":{"en":"He lives the other side of London","cn":"他住在伦敦的另一端。"}},{"pos":"N-COUNT 可数名词","cn":"(人体自腋下至臀部的)体侧,肋部","en":"Your sides are the parts of your body between your front and your back, from under your arms to your hips.","ex":{"en":"His arms were limp at his sides","cn":"他的双臂无力地垂在身体两侧。"}},{"pos":"N-COUNT 可数名词","cn":"(在…)身边，(在…)旁边(给予支持或安慰)","en":"If someone is by your side or at your side, they stay near you and give you comfort or support.","ex":{"en":"He was constantly at his wife's side","cn":"他对他的妻子始终不离不弃。"}},{"pos":"N-COUNT 可数名词","cn":"(纸张等的)一面","en":"The two sides of something flat, for example a piece of paper, are its two flat surfaces. You can also refer to one side of a piece of paper filled with writing as one side of writing.","ex":{"en":"The new copiers only copy onto one side of the paper","cn":"新复印机只能单面复印。"}},{"pos":"N-COUNT 可数名词","cn":"(磁带或唱片的)一面","en":"One side of a tape or record is what you can hear or record if you play the tape or record from beginning to end without turning it over.","ex":{"en":"We want to hear side A","cn":"我们想听 A 面。"}},{"pos":"N-COUNT 可数名词","cn":"(牛肉、猪肉等沿脊骨劈开的)一边，半只，一扇","en":"A side of beef, bacon, or other meat consists of the meat from half the animal cut along its backbone."},{"pos":"ADJ 形容词","cn":"枝节的;次要的;附带的","en":"Side is used to describe things that are not the main or most important ones of their kind.","ex":{"en":"She slipped in and out of the theatre by a side door.","cn":"她从剧院的侧门溜进溜出。"}},{"pos":"N-COUNT 可数名词","cn":"(战争、争论、谈判的)一方，一派","en":"The different sides in a war, argument, or negotiation are the groups of people who are opposing each other.","ex":{"en":"Both sides appealed for a new ceasefire","cn":"双方都呼吁达成新的停火协议。"}},{"pos":"N-COUNT 可数名词","cn":"(争论或交易中)一方的观点(或立场)","en":"The different sides of an argument or deal are the different points of view or positions involved in it.","ex":{"en":"His words drew sharp reactions from people on both sides of the issue.","cn":"他的话引起了争论双方的强烈反响。"}},{"pos":"VERB 动词","cn":"支持/共同反对","en":"If one person or country sides with another, they support them in an argument or a war. If people or countries side against another person or country, they support each other against them.","ex":{"en":"There has been much speculation that America might be siding with the rebels","cn":"有很多猜测认为美国会支持叛乱者。"}},{"pos":"N-COUNT 可数名词","cn":"运动队;球队","en":"In sport, a side is a team.","ex":{"en":"Italy were definitely a better side than Germany","cn":"意大利队明显比德国队要强。"}},{"pos":"N-COUNT 可数名词","cn":"(情况、性格等的)方面","en":"A particular side of something such as a situation or someone's character is one aspect of it.","ex":{"en":"He is in charge of the civilian side of the UN mission","cn":"他在联合国使团中负责平民方面的事务。"}},{"pos":"N-COUNT 可数名词","cn":"(亲属)母系，父系，血统","en":"The mother's side and the father's side of your family are your mother's relatives and your father's relatives.","ex":{"en":"So was your father's side more well off?","cn":"那么你父亲那边更富有一些了？"}},{"pos":"PHRASE 短语","cn":"并排;并肩","en":"If two people or things are side by side, they are next to each other.","ex":{"en":"We sat side by side on two wicker seats","cn":"我们在两把柳条椅上肩并肩坐着。"}},{"pos":"PHRASE 短语","cn":"密切(合作);和睦（相处）","en":"If people work or live side by side, they work or live closely together in a friendly way.","ex":{"en":"...areas where different nationalities have lived side by side for centuries","cn":"不同民族和睦相处了几个世纪的地区"}},{"pos":"PHRASE 短语","cn":"令(家人或朋友)失望(或难堪)","en":"If you say that someone has let the side down, you mean that they have embarrassed their family or friends by behaving badly or not doing well at something.","ex":{"en":"Brown was constantly letting the side down.","cn":"布朗不断让家人失望。"}},{"pos":"PHRASE 短语","cn":"左右,来回(移动)","en":"If something moves from side to side, it moves repeatedly to the left and to the right.","ex":{"en":"She was shaking her head from side to side.","cn":"她摇头晃脑。"}},{"pos":"PHRASE 短语","cn":"(战争、争论中)支持，站在…一边","en":"If you are on someone's side, you are supporting them in an argument or a war.","ex":{"en":"He has the Democrats on his side","cn":"他有民主党人的支持。"}},{"pos":"PHRASE 短语","cn":"对…有利;有…的优势","en":"If something is on your side or if you have it on your side, it helps you when you are trying to achieve something.","ex":{"en":"The weather is rather on our side","cn":"天气对我们非常有利。"}},{"pos":"PHRASE 短语","cn":"把…惹恼/讨…欢心","en":"If you get on the wrong side of someone, you do something to annoy them and make them dislike you. If you stay on the right side of someone, you try to please them and avoid annoying them.","ex":{"en":"I wouldn't like to get on the wrong side of him","cn":"我不想激怒他。"}},{"pos":"PHRASE 短语","cn":"稍嫌，稍偏（小或年轻)","en":"If you say that something is on the small side, you are saying politely that you think it is slightly too small. If you say that someone is on the young side, you are saying politely that you think they are slightly too young.","ex":{"en":"He's quiet and a bit on the shy side.","cn":"他很安静，略有点害羞。"}},{"pos":"PHRASE 短语","cn":"兼职;在正事之外;作为副业","en":"If someone does something on the side, they do it in addition to their main work.","ex":{"en":"...ways of making a little bit of money on the side.","cn":"兼职挣点钱的方法"}},{"pos":"PHRASE 短语","cn":"作为配菜","en":"If you have one type of food with another food on the side, you have an amount of the second food served with the first.","ex":{"en":"Serve a bowl of warm tomato sauce on the side for dipping, if desired.","cn":"如果你喜欢，可以上一碗热番茄调味汁来蘸着吃。"}},{"pos":"PHRASE 短语","cn":"暂且不管;把…暂搁置一边","en":"If you put something to one side or put it on one side, you temporarily ignore it in order to concentrate on something else.","ex":{"en":"In order to maintain profit margins health and safety regulations are often put to one side.","cn":"为了保持利润率，常置卫生和安全规章于不顾。"}},{"pos":"PHRASE 短语","cn":"把…拉到一边去(私下交谈)","en":"If you take someone to one side or draw them to one side, you speak to them privately, usually in order to give them advice or a warning.","ex":{"en":"He took Sabrina to one side and told her about the safe.","cn":"他将萨布丽娜拉到一旁，悄悄告诉她关于保险箱的事。"}},{"pos":"PHRASE 短语","cn":"(在争论或战争中)支持一方，站在…一边","en":"If you take sides or take someone's side in an argument or war, you support one of the sides against the other.","ex":{"en":"We cannot take sides in a civil war","cn":"内战中我们不能支持任何一方。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在（某一日期或事件）之前","en":"If you say that something will not happen this side of a date or event, you mean that it will not happen before that date or event.","ex":{"en":"A race between the two is now unlikely to take place this side of the world championships.","cn":"现在看来，本届世界锦标赛之前两人之间不太可能展开较量了。"}},{"pos":"","cn":"","en":"on the side of the angels→see: ; to look on the bright side→see: ; the other side of the coin→see: ; two sides of the same coin→see: ; to err on the side of something→see: ; to be on the safe side→see: ; someone's side of the story→see: ;"}]},"examples":[{"en":"At some point during the war he seems to have changed sides.","cn":"战争期间，他好像在某个时候曾经转投对方营垒。"},{"en":"We have been using both systems, side by side, for two years.","cn":"两年来，两套系统我们一直同时使用，互不影响。"}]},"signified":{"media":{"uk":"media/uk/signified__gb_1.mp3","us":"media/us/signified__us_1.mp3"},"oxford":{"phon":"ˈsɪɡnɪfaɪd","pos":"noun","senses":[{"en":"the meaning expressed by a linguistic sign, rather than its form","cn":"所指（语言符号的意义）"}]}},"simplification":{"media":{"uk":"media/uk/simplification__gb_1.mp3","us":"media/us/simplification__us_1.mp3"},"oxford":{"phon":"ˌsɪmplɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"the process of making something easier to do or understand","cn":"简化","g":"[uncountable, singular]","ex":{"en":"Complaints have led to (a) simplification of the rules.","cn":"因为人们的抱怨，规则简化了。"}},{"en":"the thing that results when you make a problem, statement, system, etc. easier to understand or do","cn":"简化的事物","g":"[countable]","ex":{"en":"A number of simplifications have been made to the taxation system.","cn":"税收制度已经历过多次简化。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"简化的事物","en":"You can use simplification to refer to the thing that is produced when you make something simpler or when you reduce it to its basic elements.","ex":{"en":"Like any such diagram, it is a simplification.","cn":"像其他这种表格一样，这是简化了的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"简化","en":"Simplification is the act or process of making something simpler.","ex":{"en":"Everyone favours the simplification of court procedures.","cn":"每个人都希望法庭程序能够简化。"}}]},"examples":[{"en":"Complaints have led to (a) simplification of the rules.","cn":"因为人们的抱怨，规则简化了。"},{"en":"A number of simplifications have been made to the taxation system.","cn":"税收制度已经历过多次简化。"}]},"simile":{"media":{"uk":"media/uk/simile__gb_1.mp3","us":"media/us/simile__us_1.mp3"},"oxford":{"phon":"ˈsɪməli","pos":"noun","senses":[{"en":"a word or phrase that compares something to something else, using the words like or as, for example a face like a mask or as white as snow; the use of such words and phrases","cn":"明喻；明喻的运用","ex":{"en":"The General liked to apply military similes to a very wide variety of matters.","cn":"这位将军喜欢把军事上的比喻广泛应用于各种事情。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"明喻","en":"A simile is an expression which describes a person or thing as being similar to someone or something else. For example, the sentences 'She runs like a deer' and 'He's as white as a sheet' contain similes."}]}},"similarly":{"media":{"uk":"media/uk/similarly__gb_1.mp3","us":"media/us/similarly__us_1.mp3"},"oxford":{"phon":"ˈsɪmələli","pos":"adverb","senses":[{"en":"in almost the same way","cn":"相似地；类似地；差不多地","ex":{"en":"It is a little cheaper than other similarly sized cars.","cn":"它比其他类似大小的车稍便宜一些。"}},{"en":"used to say that two facts, actions, statements, etc. are like each other","cn":"同样；也","ex":{"en":"The United States won most of the track and field events. Similarly, in swimming, the top three places went to Americans.","cn":"美国队赢得了田径比赛大多数项目的胜利。同样，在游泳方面，美国人也囊括了前三名。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"类似地;相似地;差不多地","en":"You use similarly to say that something is similar to something else.","ex":{"en":"Most of the men who now gathered round him again were similarly dressed.","cn":"现在再次聚集到他周围的人穿戴大都差不多。"}},{"pos":"ADV 副词","cn":"同样;也","en":"You use similarly when mentioning a fact or situation that is similar to the one you have just mentioned.","ex":{"en":"A mother recognises the feel of her child's skin when blindfolded. Similarly, she can instantly identify her baby's cry.","cn":"即便是蒙上眼睛母亲也能摸出自己孩子的肌肤。同样地，母亲也能立即听出自己孩子的哭声。"}}]},"examples":[{"en":"The United States won most of the track and field events. Similarly, in swimming, the top three places went to Americans.","cn":"美国队赢得了田径比赛大多数项目的胜利。同样，在游泳方面，美国人也囊括了前三名。"},{"en":"Husband and wife were similarly successful in their chosen careers.","cn":"夫妇俩在各自所选择的事业上都很成功。"}]},"silently":{"media":{"uk":"media/uk/silently__gb_1.mp3","us":"media/us/silently__us_1.mp3"},"oxford":{"phon":"ˈsaɪləntli","pos":"adverb","senses":[{"en":"without speaking","cn":"默默地；不说话地","ex":{"en":"They marched silently through the streets.","cn":"队伍无声地穿过街道。"}},{"en":"without making any or much sound","cn":"悄悄地；静静地","ex":{"en":"She crept silently out of the room.","cn":"她悄悄溜出房间。"}},{"en":"without using words or sounds to express something","cn":"无声地；默默地；不用言语表达地","ex":{"en":"She prayed silently.","cn":"她默默地祷告。"}}]},"examples":[{"en":"He silently agreed with much of what she had said.","cn":"对于她所讲的，有很多他暗自赞同。"},{"en":"They marched silently through the streets.","cn":"队伍无声地穿过街道。"}]},"simplicity":{"media":{"uk":"media/uk/simplicity__gb_1.mp3","us":"media/us/simplicity__us_1.mp3"},"oxford":{"phon":"sɪmˈplɪsəti","pos":"noun","senses":[{"en":"the quality of being easy to understand or use","cn":"简单（性）；容易（性）","g":"[uncountable]","ex":{"en":"the relative simplicity of the new PC","cn":"新型个人电脑的相对简易"}},{"en":"the quality of being natural and plain","cn":"质朴；淳朴","g":"[uncountable]","lab":"approving","ex":{"en":"the simplicity of the architecture","cn":"建筑风格的质朴"}},{"en":"an aspect of something that is easy, natural or plain","cn":"简单（或质朴、朴素）之处","g":"[countable, usually plural]","ex":{"en":"the simplicities of our old way of life","cn":"我们过去的生活方式的种种简朴之处"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"简单;容易;简明","en":"The simplicity of something is the fact that it is not complicated and can be understood or done easily.","ex":{"en":"The apparent simplicity of his plot is deceptive","cn":"他的故事情节貌似简单，其实不然。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"简单;质朴;朴素","en":"When you talk about something's simplicity, you approve of it because it has no unnecessary parts or complicated details.","ex":{"en":"...fussy details that ruin the simplicity of the design","cn":"破坏了这款设计简洁风格的过多的细节"}},{"pos":"PHRASE 短语","cn":"非常简单;非常容易","en":"If you say that something is simplicity itself, you are emphasizing that it is very simple or easy.","ex":{"en":"The kitchen is simplicity itself, relying on a combination of good design, craftsmanship and quality materials for its effect","cn":"厨房非常简洁，这有赖于好的设计、工艺及可体现这种效果的上乘材料。"}}]},"examples":[{"en":"For the sake of simplicity, let's divide the discussion into two parts.","cn":"为了方便起见，我们把讨论分成两部分。"},{"en":"the simplicities of our old way of life","cn":"我们过去的生活方式的种种淳朴之处"}]},"similar":{"media":{"uk":"media/uk/similar__gb_1.mp3","us":"media/us/similar__us_1.mp3"},"oxford":{"phon":"ˈsɪmələ(r)","pos":"adjective","senses":[{"en":"like somebody/something but not exactly the same","cn":"相像的；相仿的；类似的","ex":{"en":"We have very similar interests.","cn":"我们兴趣相仿。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"相像的;相仿的;类似的","en":"If one thing is similar to another, or if two things are similar, they have features that are the same.","ex":{"en":"...a savoury cake with a texture similar to that of carrot cake","cn":"口感和胡萝卜蛋糕相似的一种美味蛋糕"}}]},"examples":[{"en":"My teaching style is similar to that of most other teachers.","cn":"我的教学风格和多数教师相似。"},{"en":"All our patients have broadly similar problems.","cn":"我们所有的病人问题大致相似。"}]},"significantly":{"media":{"uk":"media/uk/significantly__gb_1.mp3","us":"media/us/significantly__us_1.mp3"},"oxford":{"phon":"sɪɡˈnɪfɪkəntli","pos":"adverb","senses":[{"en":"in a way that is large or important enough to have an effect on something or to be noticed","cn":"有重大意义地；显著地；明显地","ex":{"en":"significantly higher/lower/larger/smaller","cn":"明显地更高／更低／更大／更小"}},{"en":"in a way that has a particular meaning","cn":"有某种意义","ex":{"en":"Significantly, he did not deny that there might be an election.","cn":"值得注意的是，他没有否认可能举行选举。"}},{"en":"in a way that has a special or secret meaning","cn":"别有含义地；意味深长地","ex":{"en":"She paused significantly before she answered.","cn":"她在回答之前意味深长地停顿了一下。"}}]},"examples":[{"en":"Significantly, he did not deny that there might be an election.","cn":"值得注意的是，他没有否认可能举行选举。"},{"en":"She paused significantly before she answered.","cn":"她在回答之前意味深长地停顿了一下。"}]},"signal":{"media":{"uk":"media/uk/signal__gb_1.mp3","us":"media/us/signal__us_1.mp3"},"oxford":{"phon":"ˈsɪɡnəl","pos":"noun","senses":[{"en":"a movement or sound that you make to give somebody information, instructions, a warning, etc.","cn":"信号；暗号","lab":"North American English","ex":{"en":"a danger/warning/distress signal","cn":"危险／警告／求救信号"}},{"en":"a piece of equipment that uses different coloured lights to tell drivers to go slower, stop, etc., used especially on railways and roads","cn":"（尤指铁路和公路上的）指示灯，信号灯，红绿灯","ex":{"en":"The traffic signals were on red.","cn":"交通信号亮着红灯。"}},{"en":"a series of electrical waves that carry sounds, pictures or messages, for example to a radio, television or mobile phone","cn":"（传输声音、图像或其他信息的电波）信号","ex":{"en":"radio signals","cn":"无线电信号"}},{"en":"an event, an action, a fact, etc. that shows that something exists or is likely to happen","cn":"标志；预示；信号","ex":{"en":"The rise in inflation is a clear signal that the government's policies are not working.","cn":"通货膨胀率的上升清楚地表明，政府的政策不起作用。"}},{"en":"to make a movement or sound to give somebody a message, an order, etc.","cn":"发信号；发暗号；示意","g":"[intransitive, transitive]","ex":{"en":"Don't fire until I signal.","cn":"等我发出信号后再开枪。"},"pos":"verb"},{"en":"to show that your vehicle is going to change direction, by using lights or your arm","cn":"（用灯光或手臂）打行车转向信号","g":"[intransitive, transitive]","ex":{"en":"Did you signal before you turned right?","cn":"右转弯前你示意了吗？"},"pos":"verb"},{"en":"to be a sign that something exists or is likely to happen","cn":"标志；表明；预示","g":"[transitive]","ex":{"en":"This announcement signalled a clear change of policy.","cn":"这个声明显示政策有明显的改变。"},"pos":"verb"},{"en":"to do something to make your feelings or opinions known","cn":"表达；表示；显示","g":"[transitive]","ex":{"en":"He signalled his discontent by refusing to vote.","cn":"他拒绝投票以示不满。"},"pos":"verb"},{"en":"important, clear and definite","cn":"重大的；显要的","ex":{"en":"a signal honour","cn":"极大的荣誉"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(以手势、声音、行动等发出的)信号，暗号","en":"A signal is a gesture, sound, or action which is intended to give a particular message to the person who sees or hears it.","ex":{"en":"They fired three distress signals","cn":"他们发射了3次求救信号。"}},{"pos":"VERB 动词","cn":"(用手势、声音等)发信号，发暗号，示意","en":"If you signal to someone, you make a gesture or sound in order to send them a particular message.","ex":{"en":"The United manager was to be seen frantically signalling to McClair","cn":"一会儿可以看到曼联主教练拼命地朝麦克莱尔示意。"}},{"pos":"N-COUNT 可数名词","cn":"迹象;信号;预示","en":"If an event or action is a signal of something, it suggests that this thing exists or is going to happen.","ex":{"en":"Kurdish leaders saw the visit as an important signal of support","cn":"库尔德领导人将这次访问视作一种表示支持的重要信号。"}},{"pos":"VERB 动词","cn":"预示;表明;显示","en":"If someone or something signals an event, they suggest that the event is happening or likely to happen.","ex":{"en":"She will be signalling massive changes in energy policy","cn":"她将暗示能源政策会有重大变化。"}},{"pos":"N-COUNT 可数名词","cn":"(铁路上的)指示灯，信号灯","en":"A signal is a piece of equipment beside a railway, which indicates to train drivers whether they should stop the train or not."},{"pos":"N-COUNT 可数名词","cn":"(传输信息的无线电、光波或电流)信号","en":"A signal is a series of radio waves, light waves, or changes in electrical current which may carry information.","ex":{"en":"...high-frequency radio signals.","cn":"高频无线电信号"}},{"pos":"ADJ 形容词","cn":"重大的;显要的;非凡的","en":"You use signal to describe a success or failure when you are emphasizing the fact that it has occurred and are indicating that the consequences are significant.","ex":{"en":"His final round was a signal triumph in a career marked by many sweet moments.","cn":"最后一场比赛的胜利在他充满欣喜的职业生涯中具有非凡的意义。"}}]},"examples":[{"en":"The rise in inflation is a clear signal that the government's policies are not working.","cn":"通货膨胀率的上升清楚地表明，政府的政策不起作用。"},{"en":"The scandal surely signals the end of his political career.","cn":"毫无疑问，这桩丑闻预示他的政治生涯就此结束。"}]},"sick":{"media":{"uk":"media/uk/sick__gb_1.mp3","us":"media/us/sick__us_1.mp3"},"oxford":{"phon":"sɪk","pos":"adjective","senses":[{"en":"physically or mentally ill","cn":"（身体或精神）生病的，有病的","lab":"British English","sc":"ill","ex":{"en":"a sick child","cn":"生病的孩子"}},{"en":"feeling that you want to vomit","cn":"想呕吐；恶心","g":"[not usually before noun]","sc":"wanting to vomit","ex":{"en":"Mum, I feel sick!","cn":"妈，我想吐！"}},{"en":"feeling sick as a result of travelling on a ship, plane, etc.","cn":"晕船；晕机；晕车","sc":"-sick","ex":{"en":"seasick","cn":"晕船"}},{"en":"bored with or annoyed about something that has been happening for a long time, and wanting it to stop","cn":"（对…）厌倦的，厌烦的，厌恶的","lab":"informal","sc":"bored","ex":{"en":"I'm sick of the way you've treated me.","cn":"你对待我的那一套我都厌倦了。"}},{"en":"dealing with physical or mental pain, disease or death in a cruel way that some people think is offensive","cn":"令人毛骨悚然的；可怕的；残酷的","lab":"informal","sc":"cruel/strange","ex":{"en":"a sick joke","cn":"令人反感的笑话"}},{"en":"getting pleasure from doing strange or cruel things","cn":"变态的；病态的","lab":"informal","sc":"cruel/strange","ex":{"en":"a sick mind","cn":"变态的心理"}},{"en":"very good, a lot of fun, etc.","cn":"非常棒；极好玩","lab":"slang","sc":"good","ex":{"en":"I love that song—it’s sick!","cn":"我非常喜欢那首歌，它棒极了！"}},{"en":"food that you bring back up from your stomach through your mouth","cn":"呕吐物","g":"[uncountable]","lab":"British English, informal，，","sc":"vomit","ex":{"en":"There was a pool of sick on the carpet.","cn":"地毯上有一滩呕吐物。"},"pos":"noun"},{"en":"people who are sick","cn":"病人","g":"[plural]","sc":"ill people","ex":{"en":"to heal the sick","cn":"治愈病人"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(常指在生理上，有时也指在精神上)生病的，有病的","en":"If you are sick, you are ill. Sick usually means physically ill, but it can sometimes be used to mean mentally ill.","ex":{"en":"He's very sick. He needs medication","cn":"他病得很厉害，需要药物治疗。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"呕吐的;恶心的;想吐的","en":"If you are sick, the food that you have eaten comes up from your stomach and out of your mouth. If you feel sick, you feel as if you are going to be sick.","ex":{"en":"She got up and was sick in the handbasin","cn":"她起身在洗手池里吐了起来。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"呕吐物","en":"Sick is vomit."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"厌倦的;厌烦的;厌恶的","en":"If you say that you are sick of something or sick and tired of it, you are emphasizing that you are very annoyed by it and want it to stop.","ex":{"en":"I am sick and tired of hearing all these people moaning","cn":"我厌倦了听这些人大发牢骚。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(笑话、故事等)令人毛骨悚然的，病态的，不健康的","en":"If you describe something such as a joke or story as sick, you mean that it deals with death or suffering in an unpleasantly humorous way.","ex":{"en":"...a sick joke about a cat","cn":"关于猫的一则令人毛骨悚然的笑话"}},{"pos":"PHRASE 短语","cn":"使气愤;使厌恶;使反感","en":"If you say that something or someone makes you sick, you mean that they make you feel angry or disgusted.","ex":{"en":"It makes me sick that people commit offences and never get punished","cn":"一些人屡屡犯罪却从未受到惩戒，这真让我气愤。"}},{"pos":"PHRASE 短语","cn":"因病缺勤","en":"If you are off sick, you are not at work because you are ill.","ex":{"en":"When we are off sick, we only receive half pay.","cn":"我们请病假的时候只能拿一半薪水。"}},{"pos":"PHRASE 短语","cn":"十分担心;担心得要命","en":"If you say that you are worried sick, you are emphasizing that you are extremely worried.","ex":{"en":"He was worried sick about what our mothers would say.","cn":"对于我们双方的母亲会说什么他十分担心。"}}]},"examples":[{"en":"Britain's workers went sick (= did not go to work because they were ill) for a record number of days last year.","cn":"去年英国工人的病假天数创下了纪录。"},{"en":"People think I'm sick for having a rat as a pet.","cn":"人们认为我养只耗子当宠物是变态。"}]},"since":{"media":{"uk":"media/uk/since__gb_1.mp3","us":"media/us/since__us_1.mp3"},"oxford":{"phon":"sɪns","pos":"preposition","senses":[{"en":"from a time in the past until a later past time, or until now","cn":"自…以后；从…以来","ex":{"en":"She's been off work since Tuesday.","cn":"星期二以来她一直没上班。"}},{"en":"used when you are showing that you are angry about something","cn":"（表示气愤）何曾，什么时候","ex":{"en":"Since when did he ever listen to me?","cn":"他什么时候听过我的话？"}},{"en":"from an event in the past until a later past event, or until now","cn":"从…以后；自…以来","ex":{"en":"Cath hasn't phoned since she went to Berlin.","cn":"卡思自从去了柏林还没有打来过电话。"},"pos":"conjunction"},{"en":"because; as","cn":"因为；由于；既然","ex":{"en":"We thought that, since we were in the area, we'd stop by and see them.","cn":"我们想，既然到了这个地方，就该顺便去看看他们。"},"pos":"conjunction"},{"en":"from a time in the past until a later past time, or until now","cn":"自…以后；从…以来","ex":{"en":"She went for a run on Monday and has not been seen since.","cn":"她周一去跑步了，然后就再也没人看见过她。"},"pos":"adverb"},{"en":"at a time after a particular time in the past","cn":"此后；后来","ex":{"en":"The song topped the charts in 1957 and has since become a rock and roll classic.","cn":"这首歌在 1957 年登顶流行音乐排行榜，从此成为摇滚乐经典。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"(表示某情况自过去某时间点或某个事件以来一直持续到现在)自…以后，从…以来","en":"You use since when you are mentioning a time or event in the past and indicating that a situation has continued from then until now.","ex":{"en":"Jacques Arnold has been a member of parliament since 1987","cn":"雅克·阿诺德自 1987 年以来一直是议会议员。"}},{"pos":"PREP 介词","cn":"(表示某事件或情况从过去某时间或某个事件之后一直发生)自…以来,在…之后","en":"You use since to mention a time or event in the past when you are describing an event or situation that has happened after that time.","ex":{"en":"The percentage increase in reported crime in England and Wales this year is the highest since the war","cn":"今年英格兰和威尔士报道的犯罪增长率是战后以来最高的。"}},{"pos":"ADV 副词","cn":"(表示过去某事或某情况发生后不久又发生了另一件事)此后，后来","en":"When you are talking about an event or situation in the past, you use since to indicate that another event happened at some point later in time.","ex":{"en":"About six thousand people were arrested, several hundred of whom have since been released","cn":"约 6,000 人被捕，后来其中的几百人又被释放了。"}},{"pos":"PHRASE 短语","cn":"早就","en":"If you say that something has long since happened, you mean that it happened a long time ago.","ex":{"en":"Even though her parents have long since died, she still talks about them in the present tense.","cn":"尽管双亲早已离世，她谈论起他们时好像他们至今健在。"}},{"pos":"CONJ-SUBORD 连词","cn":"因为;由于;既然","en":"You use since to introduce reasons or explanations.","ex":{"en":"I'm forever on a diet, since I put on weight easily","cn":"我永远都在减肥，因为我很容易长胖。"}}]},"examples":[{"en":"That was years ago. I've changed jobs since then.","cn":"那是多年以前的事了。自那以来我已经换过几个工作了。"},{"en":"We thought that, since we were in the area, we'd stop by and see them.","cn":"我们想，既然到了这个地方，就该顺便去看看他们。"}]},"sideboard":{"media":{"uk":"media/uk/sideboard__gb_1.mp3","us":"media/us/sideboard__us_1.mp3"},"oxford":{"phon":"ˈsaɪdbɔːd","pos":"noun","senses":[{"en":"a piece of furniture in a dining room for putting food on before it is served, with drawers in it for storing knives, forks, etc.","cn":"餐具柜","lab":"North American English also"},{"en":"hair that grows down the sides of the face in front of the ears","cn":"（男子的）鬓角","g":"[usually plural]","lab":"British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"餐具柜;餐柜","en":"A sideboard is a long cupboard which is about the same height as a table. Sideboards are usually kept in dining rooms to put plates and glasses in."},{"pos":"N-PLURAL 复数名词","cn":"同 sideburns","en":"Sideboards are the same as sideburns ."}]}},"silk":{"media":{"uk":"media/uk/silk__gb_1.mp3","us":"media/us/silk__us_1.mp3"},"oxford":{"phon":"sɪlk","pos":"noun","senses":[{"en":"fine soft thread produced by silkworms","cn":"（蚕）丝","g":"[uncountable]","ex":{"en":"The caterpillar spins the silk around its entire body.","cn":"毛虫吐丝裹住全身。"}},{"en":"a type of fine smooth cloth made from silk thread; a piece of this cloth","cn":"丝织物；丝绸","g":"[uncountable, countable]","ex":{"en":"a silk dress/blouse/scarf/tie/sari","cn":"丝绸连衣裙／女衬衫／围巾／领带／莎丽"}},{"en":"thread made of silk used for sewing","cn":"（用于缝纫的）丝线","g":"[uncountable]"},{"en":"clothes made of silk, especially the coloured shirts worn by people riding horses in a race (= jockeys)","cn":"丝绸衣服（尤指骑师在赛马时穿的彩色赛马衫）","g":"[plural]","ex":{"en":"ladies in silks and satins","cn":"穿着锦衣华服的女士"}},{"en":"a type of lawyer who represents the government (= a King’s Counsel / Queen’s Counsel)","cn":"皇家大律师；王室法律顾问","g":"[countable]","lab":"British English, law，，","ex":{"en":"to take silk (= to become this type of lawyer)","cn":"担任皇家大律师"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"蚕丝;丝绸;丝线","en":"Silk is a substance which is made into smooth fine cloth and sewing thread. You can also refer to this cloth or thread as silk .","ex":{"en":"They continued to get their silks from China","cn":"他们继续从中国购买丝绸。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(蜘蛛等所分泌的)丝","en":"You can refer to the substance produced by some creatures such as spiders as silk .","ex":{"en":"...the silk threads of a spider's web.","cn":"蜘蛛网的丝线"}}]},"examples":[{"en":"Her skin was as smooth as silk.","cn":"她的皮肤像丝绸一样光滑。"},{"en":"to take silk (= to become this type of lawyer)","cn":"担任王室律师"}]},"sidelong":{"media":{"uk":"media/uk/sidelong__gb_1.mp3","us":"media/us/sidelong__us_1.mp3"},"oxford":{"phon":"ˈsaɪdlɒŋ","pos":"adjective","senses":[{"en":"out of the corner of your eye, especially in a way that is secret or shows that you do not approve of somebody/something","cn":"侧眼偷看的；斜着眼看的；睨视的","ex":{"en":"She cast a sidelong glance at Eric to see if he had noticed her blunder.","cn":"她偷偷斜扫了埃里克一眼，看他有没有留意到她的错误。"}},{"en":"out of the corner of your eye, especially in a way that is secret or shows that you do not approve of somebody/something","cn":"侧眼偷看的；斜着眼看的；睨视的","ex":{"en":"She looked sidelong at him.","cn":"她斜眼看他。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"斜着眼看的;侧眼看的;睨视的","en":"If you give someone a sidelong look, you look at them out of the corner of your eyes.","ex":{"en":"She gave him a quick sidelong glance.","cn":"她迅速斜眼瞥了他一眼。"}}]},"examples":[{"en":"She cast a sidelong glance at Eric to see if he had noticed her blunder.","cn":"她偷偷斜扫了埃里克一眼，看他有没有留意到她的错误。"},{"en":"She looked sidelong at him.","cn":"她斜眼看他。"}]},"sir":{"media":{"uk":"media/uk/sir__gb_1.mp3","us":"media/us/sir__us_1.mp3"},"oxford":{"phon":"sɜː(r)","pos":"noun","senses":[{"en":"used as a polite way of addressing a man whose name you do not know, for example in a shop or restaurant","cn":"（对不认识的男性的客气称呼）先生","ex":{"en":"Good morning, sir. Can I help you?","cn":"早上好，先生。您要点什么？"}},{"en":"used at the beginning of a formal business letter when you do not know the name of the man or people that you are dealing with","cn":"（正式信函中对不知其名的男性收信人的称呼）先生，阁下","ex":{"en":"Dear Sir/Sirs","cn":"亲爱的先生／诸位先生"}},{"en":"a title that is used before the first name of a man who has received one of the highest British honours (= a knight), or before the first name of a baronet","cn":"（贵族头衔，用于爵士或准男爵的名字或姓名前面）爵士","ex":{"en":"Sir Paul McCartney","cn":"保罗·麦卡特尼爵士"}},{"en":"used as a form of address to a man in a position of authority, especially in the armed forces","cn":"（对官员的称呼，尤用于军官）长官","ex":{"en":"‘Report to me tomorrow, corporal!’ ‘Yes, sir!’","cn":"“下士，明天来向我报告！”“是，长官！”"}},{"en":"used as a form of address by children in school to a male teacher","cn":"（中小学生对男教师的称呼）先生，老师","lab":"British English","ex":{"en":"Please, sir, can I open a window?","cn":"老师，请允许我打开一扇窗户好吗？"}}]},"collins":{"senses":[{"pos":"N-VOC 称呼名词","cn":"(对不知其姓名的男士或上级的尊称)先生，长官","en":"People sometimes say sir as a very formal and polite way of addressing a man whose name they do not know or a man of superior rank. For example, a shop assistant might address a male customer as sir .","ex":{"en":"Excuse me sir, but would you mind telling me what sort of car that is?","cn":"先生，请您告诉我那是什么类型的车好吗？"}},{"pos":"N-TITLE 头衔名词","cn":"(用于爵士或准男爵的姓名前)爵士","en":"Sir is the title used in front of the name of a knight or baronet.","ex":{"en":"She introduced me to Sir Tobias and Lady Clarke.","cn":"她把我引见给了托拜厄斯爵士和克拉克夫人。"}},{"pos":"CONVENTION 惯用语","cn":"(正式信函或商务信函开头的称呼语)先生，阁下(写信给某组织时使用 Dear sirs)","en":"You use the expression Dear sir at the beginning of a formal letter or a business letter when you are writing to a man. You use Dear sirs when you are writing to an organization.","ex":{"en":"Dear Sir, Your letter of the 9th October has been referred to us.","cn":"尊敬的先生，您 10 月 9 日的来信已转交我处。"}}]},"examples":[{"en":"‘Report to me tomorrow, corporal!’ ‘Yes, sir!’ “","cn":"下士，明天来向我报告！” “是，长官！”"},{"en":"‘Thank you very much.’ ‘You're welcome, sir. Have a nice day.’ “","cn":"多谢。” “不客气，先生。祝您愉快。”"}]},"signing":{"oxford":{"phon":"ˈsaɪnɪŋ","pos":"noun","senses":[{"en":"the act of writing your name at the end of an official document to show that you accept it","cn":"签署；签字","g":"[uncountable]","ex":{"en":"the signing of the Treaty of Rome","cn":"《罗马条约》的签署"}},{"en":"a person who has just signed a contract to join a particular sports team or record or film company","cn":"（运动队、唱片公司或电影公司的）签约受聘者，签约受雇者","g":"[countable]","lab":"British English","ex":{"en":"Tomorrow’s match will be the first for the team’s latest signings.","cn":"明天的比赛将是球队最新引援的第一场比赛。"}},{"en":"the act of making an official contract that arranges for somebody to join a sports team or a record or film company","cn":"签约聘用，签约雇用（安排某人加入运动队、唱片公司或电影公司）","g":"[uncountable]","ex":{"en":"the £50 million signing of the star player from Liverpool","cn":"5000万英镑签下利物浦明星球员"}},{"en":"the act of using sign language","cn":"手势语的使用","g":"[uncountable]","ex":{"en":"the use of signing in classrooms","cn":"手势语在课堂上的使用"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"签署;签字","en":"The signing of a document is the act of writing your name to indicate that you agree with what it says or to say that you have been present to witness other people writing their signature.","ex":{"en":"Spain's top priority is the signing of an EMU treaty.","cn":"西班牙的当务之急是签署《欧洲经济和货币联盟条约》。"}},{"pos":"N-COUNT 可数名词","cn":"(运动队或唱片公司的)签约受聘者，签约受雇者","en":"A signing is someone who has recently signed a contract agreeing to play for a sports team or work for a record company.","ex":{"en":"...the salary paid to the club's latest signing.","cn":"付给俱乐部最近签约运动员的工资"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(球员、歌手或乐队的)签约聘用，签约雇用","en":"The signing of a player by a sports team or a group by a record company is the act of drawing up a legal document setting out the length and terms of the association between them.","ex":{"en":"...Manchester United's signing of the Australian goalkeeper Mark Bosnich.","cn":"曼联队签下了澳大利亚的守门员马克·博斯尼克"}},{"pos":"N-UNCOUNT 不可数名词","cn":"手势语的使用","en":"Signing is the use of sign language to communicate with someone who is deaf.","ex":{"en":"The two deaf actors converse solely in signing.","cn":"两名聋哑演员独自用手语交谈。"}}]},"media":{"uk":"media/uk/signing__gb_1.mp3","us":"media/us/signing__us_1.mp3"},"examples":[{"en":"the use of signing in classrooms","cn":"手势语在课堂上的使用"},{"en":"the signing of the Treaty of Rome 《","cn":"罗马条约》的签署"}]},"sign":{"media":{"uk":"media/uk/sign__gb_1.mp3","us":"media/us/sign__us_1.mp3"},"oxford":{"phon":"saɪn","pos":"noun","senses":[{"en":"an event, an action, a fact, etc. that shows that something exists, is happening or may happen in the future","cn":"迹象；征兆；预兆","g":"[countable, uncountable]","sc":"showing something","ex":{"en":"Looking back, I should have seen the signs.","cn":"回想起来，我应该看到了迹象。"}},{"en":"a piece of paper, wood or metal that has writing or a picture on it that gives you information, instructions, a warning, etc.","cn":"招牌；标牌；指示牌；标志","g":"[countable]","sc":"for information/warning","ex":{"en":"to put up/post a sign","cn":"竖起指示牌"}},{"en":"a movement or sound that you make to tell somebody something","cn":"示意的动作（或声音）；手势","g":"[countable]","sc":"movement/sound","ex":{"en":"He gave a thumbs-up sign (= to show approval/agreement).","cn":"他竖起大拇指表示赞同。"}},{"en":"a mark used to represent something, especially in mathematics","cn":"符号；记号","g":"[countable]","sc":"symbol","ex":{"en":"a plus/minus sign (= +/−)","cn":"加号；减号"}},{"en":"a star sign (= one of the twelve signs of the zodiac)","cn":"星座","g":"[countable]","lab":"informal","sc":"star sign","ex":{"en":"What sign are you?","cn":"你是什么星座？"}},{"en":"to write your name on a document, letter, etc. to show that you have written it, that you agree with what it says, or that it is real","cn":"签（名）；署（名）；签字；签署","g":"[intransitive, transitive]","sc":"your name","ex":{"en":"Sign here, please.","cn":"请在这里签名。"},"pos":"verb"},{"en":"to arrange for somebody, for example a sports player or musician, to sign a contract agreeing to work for your company; to sign a contract agreeing to work for a company","cn":"和…签约（达成雇佣关系）","g":"[transitive, intransitive]","sc":"contract","ex":{"en":"United have just signed a new goalie.","cn":"联队最近和一名新守门员签约。"},"pos":"verb"},{"en":"to make a request or tell somebody to do something by using a sign, especially a hand movement","cn":"示意；打手势","g":"[intransitive, transitive]","sc":"make movement/sound","ex":{"en":"The hotel manager signed to the porter to pick up my case.","cn":"旅馆经理示意行李员替我拿箱子。"},"pos":"verb"},{"en":"to use sign language to communicate with somebody","cn":"打手语","g":"[intransitive, transitive]","sc":"for deaf person","ex":{"en":"She learnt to sign to help her deaf child.","cn":"为帮助她耳聋的孩子，她学会了手语。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"符号;记号","en":"A sign is a mark or shape that always has a particular meaning, for example in mathematics or music.","ex":{"en":"Equations are generally written with a two-bar equals sign.","cn":"等式通常用两道横的等号来表示。"}},{"pos":"N-COUNT 可数名词","cn":"(示意的)动作，姿势，手势","en":"A sign is a movement of your arms, hands, or head which is intended to have a particular meaning.","ex":{"en":"They gave Lavalle the thumbs-up sign","cn":"他们对拉瓦列竖起了大拇指。"}},{"pos":"VERB 动词","cn":"打手势语;为(节目或表演)配手语","en":"If you sign, you communicate with someone using sign language. If a programme or performance is signed, someone uses sign language so that deaf people can understand it.","ex":{"en":"All programmes will be either 'signed' or subtitled","cn":"所有节目要么要配手语要么要打字幕。"}},{"pos":"N-COUNT 可数名词","cn":"招牌;标牌;指示牌;告示牌;标志","en":"A sign is a piece of wood, metal, or plastic with words or pictures on it. Signs give you information about something, or give you a warning or an instruction.","ex":{"en":"...a sign saying that the highway was closed because of snow.","cn":"声明公路因大雪而关闭的告示牌"}},{"pos":"N-VAR 可变名词","cn":"迹象;征兆;表象;痕迹","en":"If there is a sign of something, there is something which shows that it exists or is happening.","ex":{"en":"They are prepared to hand back a hundred prisoners of war a day as a sign of good will","cn":"他们准备每日遣返100名战俘以示友好。"}},{"pos":"VERB 动词","cn":"在…上签名;在…上签字;签署","en":"When you sign a document, you write your name on it, usually at the end or in a special space. You do this to indicate that you have written the document, that you agree with what is written, or that you were present as a witness.","ex":{"en":"World leaders are expected to sign a treaty pledging to increase environmental protection","cn":"世界各国首脑预计会签署一份承诺加强环境保护的协定。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(和…)签约","en":"If an organization signs someone or if someone signs for an organization, they sign a contract agreeing to work for that organization for a specified period of time.","ex":{"en":"The Minnesota Vikings signed Herschel Walker from the Dallas Cowboys","cn":"明尼苏达维京人队签下了来自达拉斯牛仔队的赫舍尔·沃克。"}},{"pos":"N-COUNT 可数名词","cn":"(黄道十二宫的)宫，星座","en":"In astrology, a sign or a sign of the zodiac is one of the twelve areas into which the heavens are divided.","ex":{"en":"The New Moon takes place in your opposite sign of Libra on the 15th.","cn":"15 日新月会移至你对面的天秤宫。"}},{"pos":"PHRASE 短语","cn":"不见…的踪影","en":"If you say that there is no sign of someone, you mean that they have not yet arrived, although you are expecting them to come.","ex":{"en":"The London train was on time, but there was no sign of my Finnish friend.","cn":"伦敦的火车准点到达，却不见我那芬兰朋友的踪影。"}},{"pos":"PHRASE 短语","cn":"已签字盖章的;已成定局的","en":"If you say that an agreement is signed and sealed, or signed, sealed and delivered, you mean that it is absolutely definite because everyone involved has signed all the legal documents.","ex":{"en":"The Chancellor had been hoping to have an agreement signed and sealed by the end of this week","cn":"财政大臣一直期望这周末前能敲定一份协议。"}},{"pos":"","cn":"","en":"to sign one's own death warrant→see: ;"},{"pos":"","cn":"","en":"相关词组：sign away sign for sign in sign off sign on sign on for sign over sign up"}]},"examples":[{"en":"If I had noticed the warning signs , none of this would have happened.","cn":"要是我当时注意到了那些警告信号，这种事就一桩也不会发生。"},{"en":"How many countries have signed up to the Kyoto protocol on climate change?","cn":"有多少个国家签订了关于气候变化的《京都议定书》？"}]},"silicon":{"media":{"uk":"media/uk/silicon__gb_1.mp3","us":"media/us/silicon__us_1.mp3"},"oxford":{"phon":"ˈsɪlɪkən","pos":"noun","senses":[{"en":"a chemical element. Silicon exists as a grey solid or as a brown powder and is found in rocks and sand. It is used in making glass and transistors.","cn":"硅"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"硅","en":"Silicon is an element that is found in sand and in minerals such as quartz and granite. Silicon is used to make parts of computers and other electronic equipment.","ex":{"en":"...a thin layer of silicon oxide","cn":"一层薄薄的氧化硅"}}]}},"simply":{"media":{"uk":"media/uk/simply__gb_1.mp3","us":"media/us/simply__us_1.mp3"},"oxford":{"phon":"ˈsɪmpli","pos":"adverb","senses":[{"en":"used to emphasize how easy or basic something is","cn":"（强调简单）仅仅，只，不过","ex":{"en":"To order, simply click here.","cn":"如需订购，只需点击此处。"}},{"en":"in a way that is easy to understand","cn":"简单地","ex":{"en":"The book explains grammar simply and clearly.","cn":"这本书将语法解释得简明扼要。"}},{"en":"in a way that is natural and plain","cn":"简朴地；朴素地","ex":{"en":"The rooms are simply furnished.","cn":"房间都陈设简朴。"}},{"en":"used to emphasize a statement","cn":"（强调某说法）确实，简直","ex":{"en":"You simply must see the play.","cn":"那出戏你真得看看。"}},{"en":"used to introduce a summary or an explanation of something that you have just said or done","cn":"（引出概括或解释）不过，只是","ex":{"en":"I don't want to be rude, it's simply that we have to be careful who we give this information to.","cn":"恕我直言，这一信息给谁，我们必须很慎重。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"简单地;只不过;仅仅;纯粹","en":"You use simply to emphasize that something consists of only one thing, happens for only one reason, or is done in only one way.","ex":{"en":"The table is simply a chipboard circle on a base","cn":"这张桌子只不过是在底座上安了一块圆形刨花板。"}},{"pos":"ADV 副词","cn":"(用于强调)简直，根本","en":"You use simply to emphasize what you are saying.","ex":{"en":"This sort of increase simply cannot be justified","cn":"这种增长根本就不合理。"}}]},"examples":[{"en":"I don't want to be rude, it's simply that we have to be careful who we give this information to.","cn":"我不是有意无礼，只不过这份资料给谁我们必须很慎重。"},{"en":"Anyway, to put it simply, we still owe them £2 000.","cn":"反正简单地说，我们还欠他们 2 000 英镑。"}]},"sideways":{"oxford":{"phon":"ˈsaɪdweɪz","pos":"adverb","senses":[{"en":"to, towards or from the side","cn":"往（或向、从）一侧","lab":"figurative","ex":{"en":"He looked sideways at her.","cn":"他斜着眼看她。"}},{"en":"with one side facing forwards","cn":"侧着；侧面朝前","ex":{"en":"She sat sideways on the chair.","cn":"她侧坐在椅子上。"}},{"en":"to, towards or from the side","cn":"往（或向、从）一侧","ex":{"en":"She slid him a sideways glance.","cn":"她斜眼看了他一下。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"往(或从、向)一侧","en":"Sideways means from or towards the side of something or someone.","ex":{"en":"Piercey glanced sideways at her","cn":"皮尔西斜眼看了看她。"}},{"pos":"ADV 副词","cn":"(调动工作)平级地","en":"If you are moved sideways at work, you move to another job at the same level as your old job.","ex":{"en":"He would be moved sideways, rather than demoted.","cn":"他会被平级调动而不是降级。"}},{"pos":"PHRASE 短语","cn":"使大为吃惊;使极为困惑;使大为不快","en":"If you are knocked sideways by something, it makes you feel very surprised, confused, or upset.","ex":{"en":"He was knocked sideways by the result","cn":"结果让他大为吃惊。"}}]},"media":{"uk":"media/uk/sideways__gb_1.mp3","us":"media/us/sideways__us_1.mp3"},"examples":[{"en":"The truck skidded sideways across the road.","cn":"卡车横着滑到公路另一侧。"},{"en":"He has been moved sideways (= moved to another job at the same level as before, not higher or lower).","cn":"他平级调动工作了。"}]},"sight":{"media":{"uk":"media/uk/sight__gb_1.mp3","us":"media/us/sight__us_1.mp3"},"oxford":{"phon":"saɪt","pos":"noun","senses":[{"en":"the ability to see","cn":"视力；视觉","g":"[uncountable]","sc":"ability to see","ex":{"en":"to lose your sight (= to become blind)","cn":"失明"}},{"en":"the act of seeing somebody/something","cn":"看见","g":"[uncountable]","sc":"act of seeing","ex":{"en":"She kept sight of him in her mirror.","cn":"她一直在镜子里看着他。"}},{"en":"the area or distance within which somebody can see or something can be seen","cn":"视力范围；视野","g":"[uncountable]","sc":"how far you can see","ex":{"en":"There was no one in sight.","cn":"一个人也看不见。"}},{"en":"a thing that you see or can see","cn":"看见（或看得见）的事物；景象；情景","g":"[countable]","sc":"what you can see","ex":{"en":"Roadside stalls are a common sight in the city.","cn":"路边摊在这个城市很常见。"}},{"en":"the interesting places, especially in a town or city, that are often visited by tourists","cn":"名胜；风景","g":"[plural]","sc":"interesting places","ex":{"en":"We're going to Paris for the weekend to see the sights.","cn":"我们打算去巴黎过周末，参观那里的名胜。"}},{"en":"a person or thing that looks silly, untidy, unpleasant, etc.","cn":"可笑（或邋遢、脏乱、讨厌）的人（或物）","g":"[singular]","lab":"informal, especially British English，，","sc":"silly/untidy person","ex":{"en":"She looks a sight in that hat!","cn":"她戴着那顶帽子，样子够滑稽的！"}},{"en":"a device that you look through to aim a gun, etc. or to look at something through a telescope, etc.","cn":"瞄准器；观测器","g":"[countable, usually plural]","lab":"figurative","sc":"on gun/telescope","ex":{"en":"He had the deer in his sights now.","cn":"他现在瞄准了那头鹿。"}},{"en":"to suddenly see something, especially something you have been looking for","cn":"看到，发现（期待的事物）","ex":{"en":"After twelve days at sea, they sighted land.","cn":"在海上航行十二天后他们看到了陆地。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"视力;视觉","en":"Someone's sight is their ability to see.","ex":{"en":"My sight is failing, and I can't see to read any more","cn":"我的视力在下降，看不了书了。"}},{"pos":"N-SING 单数名词","cn":"看见;目睹","en":"The sight of something is the act of seeing it or an occasion on which you see it.","ex":{"en":"I faint at the sight of blood","cn":"我一见到血就晕。"}},{"pos":"N-COUNT 可数名词","cn":"看见的事物;景象;情景","en":"A sight is something that you see.","ex":{"en":"The practice of hanging clothes across the street is a common sight in many parts of the city","cn":"街边晾晒衣服在这座城市的许多地区随处可见。"}},{"pos":"VERB 动词","cn":"(突然或刹那间)看见，发现","en":"If you sight someone or something, you suddenly see them, often briefly.","ex":{"en":"The security forces sighted a group of young men that had crossed the border","cn":"安全部队突然看见一群越过边境的年轻人。"}},{"pos":"N-COUNT 可数名词","cn":"(武器等的)准星，瞄准器","en":"The sights of a weapon such as a rifle are the part which helps you aim it more accurately."},{"pos":"N-PLURAL 复数名词","cn":"风景;名胜","en":"The sights are the places that are interesting to see and that are often visited by tourists.","ex":{"en":"We'd toured the sights of Paris","cn":"我们游览了巴黎的风景名胜。"}},{"pos":"ADV 副词","cn":"很;非常","en":"You can use a sight to mean a lot. For example, if you say that something is a sight worse than it was before, you are emphasizing that it is much worse than it was.","ex":{"en":"She's been no more difficult than most daughters and a sight better than some I could mention","cn":"与大多数女儿相比，她并不算太难管，而且比我知道的一些要乖巧得多。"}},{"pos":"PHRASE 短语","cn":"(突然或刹那间)看见，发现","en":"If you catch sight of someone, you suddenly see them, often briefly.","ex":{"en":"Then he caught sight of her small black velvet hat in the crowd","cn":"然后他突然在人群中看见了她那顶小巧的黑色天鹅绒帽子。"}},{"pos":"PHRASE 短语","cn":"乍一看;一见之下;初看时","en":"If you say that something seems to have certain characteristics at first sight, you mean that it appears to have the features you describe when you first see it but later it is found to be different.","ex":{"en":"It promised to be a more difficult undertaking than might appear at first sight","cn":"那项任务可能比乍看之下还要困难。"}},{"pos":"PHRASE 短语","cn":"看得见/看不见","en":"If something is in sight or within sight, you can see it. If it is out of sight, you cannot see it.","ex":{"en":"The sandy beach was in sight","cn":"沙滩映入眼帘。"}},{"pos":"PHRASE 短语","cn":"在望;在即;临近;即将产生","en":"If a result or a decision is in sight or within sight, it is likely to happen within a short time.","ex":{"en":"An agreement on many aspects of trade policy was in sight","cn":"一项涉及到贸易政策诸多方面的协议即将达成。"}},{"pos":"PHRASE 短语","cn":"忽略;忽视;遗忘","en":"If you lose sight of an important aspect of something, you no longer pay attention to it because you are worrying about less important things.","ex":{"en":"In some cases, US industry has lost sight of customer needs in designing products","cn":"某些情况下，美国工业在产品设计上忽略了客户的需求。"}},{"pos":"PHRASE 短语","cn":"与…只是面熟(并不熟识)","en":"If you know someone by sight, you can recognize them when you see them, although you have never met them and talked to them.","ex":{"en":"I knew him by sight but had never spoken with him.","cn":"我和他有过几面之缘，但从未说过话。"}},{"pos":"PHRASE短语","cn":"眼不见，心不烦","en":"If you say 'out of sight, out of mind', you mean that people quickly forget someone if he or she goes away.","ex":{"en":"The problems of the poor are largely invisible—out of sight, out of mind.","cn":"穷人的问题人们大多看不见——正所谓“眼不见，心不烦”。"}},{"pos":"PHRASE 短语","cn":"一见…马上就","en":"If someone is ordered to do something on sight, they have to do it without delay, as soon as a person or thing is seen.","ex":{"en":"Troops shot anyone suspicious on sight","cn":"部队士兵一见到任何可疑的人马上就开枪。"}},{"pos":"PHRASE 短语","cn":"不好看;不雅观;有碍观瞻","en":"If you say that someone or something is not a pretty sight, you mean that it is not pleasant to look at.","ex":{"en":"The bathroom is not a pretty sight. The wallpaper's peeling, the tiles are crumbling.","cn":"浴室破旧不堪。墙纸剥落了，瓷砖也裂了。"}},{"pos":"PHRASE 短语","cn":"以…为奋斗目标;志在必得;决心做到","en":"If you set your sights on something, you decide that you want it and try hard to get it.","ex":{"en":"They have set their sights on the world record","cn":"他们的目标是冲击世界纪录。"}},{"pos":"PHRASE 短语","cn":"在未见实物的情况下;事先未经检查","en":"If you agree to buy something sight unseen, you agree to buy it, even though you have not seen it and do not know what condition it is in.","ex":{"en":"Although people sometimes buy property sight unseen, it's a remarkably bad idea.","cn":"尽管人们有时没看房就买了房，但这真是一个很糟糕的主意。"}},{"pos":"","cn":"","en":"love at first sight→see: ;"}]},"examples":[{"en":"At first sight, it may look like a generous offer, but always read the small print.","cn":"乍一看，对方给出的条件好像很优厚，但任何时候都不要小看那些小号字印刷的附加条款。"},{"en":"Leave any valuables in your car out of sight.","cn":"把贵重物品留在车里，要放在看不见的地方。"}]},"silly":{"oxford":{"phon":"ˈsɪli","pos":"adjective","senses":[{"en":"showing a lack of thought, understanding, or judgement","cn":"愚蠢的；不明事理的；没头脑的；傻的","ex":{"en":"a silly idea/question/name","cn":"愚蠢的想法／问题／名字"}},{"en":"stupid or embarrassing, especially in a way that is more typical of a child than an adult","cn":"（尤指像小孩一样）可笑的，荒唐的，冒傻气的","ex":{"en":"a silly sense of humour","cn":"可笑的幽默感"}},{"en":"not practical or serious","cn":"不实用的；闹着玩的","ex":{"en":"We had to wear these silly little hats.","cn":"我们不得不戴这些傻里傻气的小帽子。"}},{"en":"often used when speaking to children to say that they are not behaving in a sensible way","cn":"（常用于向孩子指出其愚蠢行为）傻孩子，淘气鬼","ex":{"en":"No, silly, those aren't your shoes!","cn":"不对，傻孩子，那不是你的鞋！"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愚蠢的;幼稚的;荒唐的","en":"If you say that someone or something is silly, you mean that they are foolish, childish, or ridiculous.","ex":{"en":"My best friend tells me that I am silly to be upset about this","cn":"我最好的朋友说我要是为这事而沮丧难过就真够傻的。"}},{"pos":"ADJ 形容词","cn":"(喝得)昏头昏脑的;(笑得)傻里傻气的","en":"If you do something such as laugh or drink yourself silly, you do it so much that you are unable to think or behave sensibly.","ex":{"en":"Right now the poor old devil's drinking himself silly","cn":"这会儿那可怜的老家伙又喝得糊里糊涂的了。"}}]},"media":{"uk":"media/uk/silly__gb_1.mp3","us":"media/us/silly__us_1.mp3"},"examples":[{"en":"‘I can walk home.’ ‘Don't be silly — it's much too far!’ “","cn":"我可以走回家去。” “别犯傻了，远得很哪！”"},{"en":"We had to wear these silly little hats.","cn":"我们不得不戴这些傻里傻气的小帽子。"}]},"situation":{"media":{"uk":"media/uk/situation__gb_1.mp3","us":"media/us/situation__us_1.mp3"},"oxford":{"phon":"ˌsɪtʃuˈeɪʃn","pos":"noun","senses":[{"en":"all the circumstances and things that are happening at a particular time and in a particular place","cn":"情况；状况；形势；局面","lab":"especially North American English, informal，，","ex":{"en":"the present economic/financial/political situation","cn":"目前的经济／财政／政治形势"}},{"en":"the kind of location that a building or town has","cn":"（建筑物或城镇的）地理位置，环境特点","lab":"formal","ex":{"en":"The town is in a delightful situation in a wide green valley.","cn":"小城坐落在一个宽阔而草木苍翠的河谷中，环境宜人。"}},{"en":"a job","cn":"职位；职务","lab":"old-fashioned or formal","ex":{"en":"Situations Vacant (= the title of the section in a newspaper where jobs are advertised)","cn":"招聘（报章中的招聘广告栏）"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"形势;情况;局面","en":"You use situation to refer generally to what is happening in a particular place at a particular time, or to refer to what is happening to you.","ex":{"en":"Army officers said the situation was under control","cn":"陆军军官称局面已经得到了控制。"}},{"pos":"N-COUNT 可数名词","cn":"(建筑物、城镇的)位置,环境","en":"The situation of a building or town is the kind of surroundings that it has.","ex":{"en":"The garden is in a beautiful situation on top of a fold in the rolling Hampshire landscape.","cn":"这座花园位于地势连绵起伏的汉普郡的一处山岗上，环境十分优美。"}},{"pos":"PHRASE 短语","cn":"(报纸上的招聘广告栏或招聘页标题)招聘","en":"Situations Vacant is the title of a column or page in a newspaper where jobs are advertised."}]},"examples":[{"en":"The town is in a delightful situation in a wide green valley.","cn":"小城坐落在一个宽阔而草木苍翠的河谷中，环境宜人。"},{"en":"You could get into a situation where you have to decide immediately.","cn":"你可能遇上一种情况，使你不得不立刻作出决定。"}]},"singers":{"oxford":{"phon":"ˈsɪŋə(r)","pos":"noun","senses":[{"en":"a person who sings, or whose job is singing, especially in public","cn":"唱歌的人；歌唱家；歌手"}]},"media":{"uk":"media/uk/singer__gb_1.mp3","us":"media/us/singer__us_1.mp3"}},"singer":{"media":{"uk":"media/uk/singer__gb_1.mp3","us":"media/us/singer__us_1.mp3"},"oxford":{"phon":"ˈsɪŋə(r)","pos":"noun","senses":[{"en":"a person who sings, or whose job is singing, especially in public","cn":"唱歌的人；歌唱家；歌手","ex":{"en":"She's a wonderful singer.","cn":"她唱歌唱得非常好。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"唱歌的人;(尤指)歌手，歌唱家","en":"A singer is a person who sings, especially as a job.","ex":{"en":"My mother was a singer in a dance band.","cn":"我妈妈是一个舞蹈乐队的歌手。"}}]},"examples":[{"en":"She's a wonderful singer.","cn":"她唱歌唱得非常好。"},{"en":"an opera singer","cn":"歌剧演员"}]},"sides":{"oxford":{"phon":"saɪd","pos":"noun","senses":[{"en":"either of the two halves of a surface, an object or an area that is divided by an imaginary central line （","cn":"由想像的中线分出的）一边，一侧"},{"en":"a position or an area to the left or right of sth （","cn":"事物左方或右方的）一旁，一边，一侧"}]}},"similarities":{"oxford":{"phon":"ˌsɪməˈlærəti","pos":"noun","senses":[{"en":"the state of being like sb/sth but not exactly the same","cn":"相像性；相仿性；类似性"},{"en":"a feature that things or people have that makes them like each other","cn":"相像处；相似点；类似的地方"}]}},"simulations":{"oxford":{"phon":"ˌsɪmjuˈleɪʃn","pos":"noun","senses":[{"en":"a situation in which a particular set of conditions is created artificially in order to study or experience sth that could exist in reality","cn":"模拟；仿真"},{"en":"the act of pretending that sth is real when it is not","cn":"假装；冒充"}]}},"signed":{"oxford":{"phon":"saɪn","pos":"noun","senses":[{"en":"an event, an action, a fact, etc. that shows that sth exists, is happening or may happen in the future","cn":"迹象；征兆；预兆"},{"en":"a piece of paper, wood or metal that has writing or a picture on it that gives you information, instructions, a warning, etc.","cn":"招牌；标牌；指示牌；标志"}]}},"sizable":{"oxford":{"phon":"ˈsaɪzəbl","pos":"adj.","senses":[{"en":"fairly large","cn":"相当大的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/sizable0205.mp3","us":"media/ldoce/hwd/ame/f/laadsizable.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"sinking":{"oxford":{"phon":"sɪŋk","pos":"verb","senses":[{"en":"to go down below the surface or towards the bottom of a liquid or soft substance","cn":"下沉；下陷；沉没"},{"en":"to damage a boat or ship so that it goes below the surface of the sea, etc.","cn":"使下沉；使沉没"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(情绪突然)颓丧的，抑郁的，沮丧的","en":"If you have a sinking feeling, you suddenly become depressed or lose hope.","ex":{"en":"I began to have a sinking feeling that I was not going to get rid of her.","cn":"我开始有一种永远也摆脱不了她的沮丧情绪。"}}]}},"situations":{"oxford":{"phon":"ˌsɪtʃuˈeɪʃn","pos":"noun","senses":[{"en":"all the circumstances and things that are happening at a particular time and in a particular place","cn":"情况；状况；形势；局面"},{"en":"( formal ) the kind of area or surroundings that a building or town has （","cn":"建筑物或城镇的）地理位置，环境特点"}]}},"simplest":{"oxford":{"phon":"ˈsɪmpl","pos":"adj.","senses":[{"en":"not complicated; easy to understand or do","cn":"易于理解的；易做的；简单的"},{"en":"basic or plain without anything extra or unnecessary","cn":"朴素的；简朴的；不加装饰的"}]}},"sits":{"oxford":{"phon":"sɪt","pos":"verb","senses":[{"en":"to rest your weight on your bottom with your back vertical, for example on/in a chair","cn":"坐"},{"en":"to put sb in a sitting position","cn":"使坐；使就座"}]}},"sized":{"oxford":{"phon":"saɪz","pos":"noun","senses":[{"en":"how large or small a person or thing is","cn":"大小"},{"en":"the large amount or extent of sth","cn":"大量；大规模"}]}},"sidewalks":{"oxford":{"phon":"ˈsaɪdwɔːk","pos":"noun","senses":[{"en":"a flat part at the side of a road for people to walk on （","cn":"马路边的）人行道"}]}},"signs":{"oxford":{"phon":"saɪn","pos":"noun","senses":[{"en":"an event, an action, a fact, etc. that shows that sth exists, is happening or may happen in the future","cn":"迹象；征兆；预兆"},{"en":"a piece of paper, wood or metal that has writing or a picture on it that gives you information, instructions, a warning, etc.","cn":"招牌；标牌；指示牌；标志"}]}},"signals":{"oxford":{"phon":"ˈsɪɡnəl","pos":"noun","senses":[{"en":"a movement or sound that you make to give sb information, instructions, a warning, etc.","cn":"信号；暗号"},{"en":"an event, an action, a fact, etc. that shows that sth exists or is likely to happen","cn":"标志；预示；信号"}]}},"simplified":{"oxford":{"phon":"ˈsɪmplɪfaɪ","pos":"verb","senses":[{"en":"to make sth easier to do or understand","cn":"使简化；使简易"}]}},"sites":{"oxford":{"phon":"saɪt","pos":"noun","senses":[{"en":"a place where a building, town, etc. was, is or will be located （","cn":"建筑物、城镇等的）地点，位置，建筑工地"},{"en":"a place where sth has happened or that is used for sth","cn":"现场；发生地；场所"}]}},"signaled":{"oxford":{"phon":"ˈsɪɡnəl","pos":"noun","senses":[{"en":"a movement or sound that you make to give sb information, instructions, a warning, etc.","cn":"信号；暗号"},{"en":"an event, an action, a fact, etc. that shows that sth exists or is likely to happen","cn":"标志；预示；信号"}]}},"silencer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(枪支的)消音器","en":"A silencer is a device that is fitted onto a gun to make it very quiet when it is fired.","ex":{"en":"...a pistol that was equipped with a silencer.","cn":"装了消音器的手枪"}},{"pos":"N-COUNT 可数名词","cn":"(汽车排气管上的)消音器","en":"A silencer is a device on a car exhaust that makes it quieter."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment that is connected to the exhaust of a vehicle to make its engine quieter 〔","cn":"与车辆排气管装置相连的〕消声器"},{"en":"a thing that is put on the end of a gun so that it makes less noise when it is fired 〔","cn":"枪末端的〕消音器﹐消声器"}]},"media":{"uk":"media/ldoce/hwd/bre/5/silencer0205.mp3","us":"media/ldoce/hwd/ame/9/silencer.mp3"},"oxford":{"phon":"ˈsaɪlənsə(r)","pos":"noun","senses":[{"en":"a device that is fixed to the exhaust of a vehicle in order to reduce the amount of noise that the engine makes","cn":"（发动机的）消声器","lab":"British English"},{"en":"a device that is fixed to the end of a gun in order to reduce the amount of noise that it makes when it is fired","cn":"（枪支的）消音器"}]}},"singaporean":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"新加坡的;新加坡人的;新加坡文化的","en":"Singaporean means belonging or relating to Singapore, or to its people or culture.","ex":{"en":"...the Singaporean economy.","cn":"新加坡经济"}},{"pos":"N-COUNT 可数名词","cn":"新加坡人;新加坡裔人","en":"A Singaporean is a citizen of Singapore or a person of Singaporean origin.","ex":{"en":"All Singaporeans have to pass exams in the official language of their ethnic group as well as English.","cn":"所有新加坡人都必须通过他们自己民族的官方语言及英语的考试。"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a small country on an island in southeast Asia, between Malaysia and Indonesia. Population: 5,460,302 (2014). Capital: Singapore. Singapore is an important business, industrial, and financial centre, and it is known for its rapid and successful economic develo","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/p028-000011209.mp3","us":"media/ldoce/hwd/ame/8/p028-000011209.mp3"},"oxford":{"phon":"ˌsɪŋəˈpɔːriən","pos":"noun, adjective","senses":[{"en":"(a person) from Singapore","cn":"新加坡人；新加坡的；新加坡人的"}]}},"silhouetted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"现出轮廓的","en":"If someone or something is silhouetted against a background, you can see their silhouette.","ex":{"en":"Silhouetted against the sun stood the figure of a man.","cn":"阳光映衬出一名男子的轮廓。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the shape that something is, for example a square, a circle etc","cn":""},{"en":"the shape of something - use this especially to talk about art or when the shape is not very clear","cn":""},{"en":"the shape of a person","cn":""}]},"collocations":{"phrases":["VERBS be, stand A dark shape stood silhouetted against the bright morning sky.","ADV. clearly, sharply, starkly He woke to see their two heads clearly silhouetted against his window.","PREP. against"]},"media":{"img":["media/ldoce/img/ldoce_302.png"],"uk":"media/ldoce/hwd/bre/d/silhouette0205.mp3","us":"media/ldoce/hwd/ame/9/silhouette1.mp3"},"examples":[{"en":"a dark silhouette of domes and minarets","cn":""},{"en":"Soon the bombers would return, black silhouettes against a pale sky.","cn":""}]},"signalman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(铁路上的)信号员，信号工","en":"A signalman is a person whose job is to control the signals on a particular section of a railway."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to control railway signals 〔","cn":"铁路的〕信号员﹐信号工"},{"en":"a member of the army or navy who is trained to send and receive signals 〔","cn":"陆军或海军的〕信号手﹐信号兵"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41signalman.mp3","us":"media/ldoce/hwd/ame/7/signalman.mp3"},"oxford":{"phon":"ˈsɪɡnəlmən","pos":"noun","senses":[{"en":"a person whose job is operating signals on a railway","cn":"（铁路上的）信号员，信号工"},{"en":"a person trained to give and receive signals in the army or navy","cn":"（军队的）信号兵，通信兵"}]}},"silicate":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"硅酸盐","en":"A silicate is a compound of silica which does not dissolve. There are many different kinds of silicate.","ex":{"en":"...large amounts of aluminum silicate.","cn":"大量的硅酸铝"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of a group of common solid mineral substances that exist naturally in the earth","cn":"硅酸盐"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41silicate.mp3","us":"media/ldoce/hwd/ame/a/silicate.mp3"},"examples":[{"en":"aluminium silicate","cn":"硅酸铝"}],"oxford":{"phon":"ˈsɪlɪkeɪt","pos":"noun","senses":[{"en":"any compound containing silicon and oxygen","cn":"硅酸盐","lab":"chemistry","ex":{"en":"aluminium silicate","cn":"硅酸铝"}},{"en":"a mineral that contains silica. There are many different silicates and they form a large part of the earth’s crust.","cn":"硅酸盐矿物"}]}},"single-minded":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"一心一意的;专心致志的","en":"Someone who is single-minded has only one aim or purpose and is determined to achieve it.","ex":{"en":"They were effective politicians, ruthless and single-minded in their pursuit of political power.","cn":"他们都是些非常现实的政治家，一心追逐政治权力，为达目的毫不留情。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you are determined to do something, you have decided that you are definitely going to do it, and you will not let anything stop you. Determined is also used about someone’s character, when they usually behave in this way","cn":""},{"en":"determined not to change what you are doing, especially when other people think you are behaving in an unreasonable way. Stubborn is often used when you disapprove of someone. It is also sometimes used when you admire them","cn":""},{"en":"someone who is single-minded works very hard in order to achieve one particular thing, and thinks that everything else is much less important","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/single_minded0205.mp3","us":"media/ldoce/hwd/ame/3/single-minded.mp3"},"examples":[{"en":"She is very single-minded about her career.","cn":"她一心专注于自己的事业。"},{"en":"the single-minded pursuit of power","cn":"一心追逐权力"}],"oxford":{"phon":"ˌsɪŋɡl ˈmaɪndɪd","pos":"adjective","senses":[{"en":"only thinking about one particular aim or goal because you are determined to achieve something","cn":"一心一意的；专心致志的","ex":{"en":"the single-minded pursuit of power","cn":"一心追逐权力"}}]}},"sidearm":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"随身佩带的武器(通常指小手枪)","en":"Sidearms are weapons, usually small guns, that you can wear on a belt.","ex":{"en":"Two guards with sidearms patrolled the wall.","cn":"两名配枪警卫在城墙上巡逻。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a weapon carried or worn at someone’s side, for example a gun or sword 〔","cn":"佩带在腰间的〕随身武器"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41sidearm.mp3","us":"media/ldoce/hwd/ame/5/sidearm.mp3"}},"siberian":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a very large area in Russia, between the Ural Mountains and the Pacific Ocean where there are many minerals but very few people. It is known for being extremely cold, and for being the place where Russian criminals were sent, and during the communist years whe","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/p028-000011157.mp3","us":"media/ldoce/hwd/ame/2/p028-000011157.mp3"}},"sikh":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"锡克教教徒","en":"A Sikh is a person who follows the Indian religion of Sikhism.","ex":{"en":"The rise of racism concerns Sikhs because they are such a visible minority.","cn":"种族主义的抬头让锡克教徒很担忧，因为他们是力量非常薄弱的少数群体。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a member of an Indian religious group that developed from Hinduism in the 16th century","cn":"锡克教教徒〔16世纪从印度教发展出来的一个宗教团体的信徒〕"}]},"media":{"uk":"media/ldoce/hwd/bre/b/seek0205.mp3","us":"media/ldoce/hwd/ame/5/seek.mp3"},"oxford":{"phon":"siːk","pos":"noun","senses":[{"en":"a member of a people whose religion is Sikhism; a person who believes in and practises Sikhism","cn":"锡克教教徒（锡克教在 15 世纪晚期产生于旁遮普地区，相信一神论）"},{"en":"connected with Sikhs or Sikhism; believing in and practising Sikhism","cn":"锡克教的；锡克教教徒的；信奉锡克教的","ex":{"en":"the Sikh community","cn":"锡克教社区"},"pos":"adjective"}]}},"singsong":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(声音)高低起伏的","en":"A sing-song voice repeatedly rises and falls in pitch.","ex":{"en":"He started to speak in a nasal sing-song voice.","cn":"他开始用一种带有鼻音的、抑扬顿挫的声调说话。"}},{"pos":"N-COUNT 可数名词","cn":"(众人自娱自乐的)合唱，歌唱会","en":"A sing-song is an occasion on which a group of people sing songs together for pleasure."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of speaking in which your voice keeps rising and falling","cn":"抑扬顿挫的说话腔调"},{"en":"an informal occasion when people sing songs together 〔","cn":"众人一起的〕自娱歌唱会"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41singsong.mp3","us":"media/ldoce/hwd/ame/8/singsong.mp3"},"examples":[{"en":"I recognized her soft singsong immediately.","cn":"我立刻就听出了她那柔和婉转的声音。"},{"en":"We had a bit of a singsong later.","cn":"我们后来一起唱了一会儿歌。"}]},"sightseer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"观光客;游客","en":"A sightseer is someone who is travelling around visiting the interesting places that tourists usually visit.","ex":{"en":"...coachloads of sightseers.","cn":"几车厢的观光旅客"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is visiting a place for pleasure on holiday","cn":""},{"en":"someone who travels somewhere","cn":""},{"en":"someone who comes to visit a particular country, area, museum etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A sightseer is a person who goes on vacation and visits historic or otherwise notable places. Sightseers often take photos of monuments, buildings, bridges, and parks."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41sightseer.mp3","us":"media/ldoce/hwd/ame/1/sightseer.mp3"},"examples":[{"en":"Oxford attracts large numbers of sightseers.","cn":"牛津吸引着大量观光客。"}],"oxford":{"phon":"ˈsaɪtsɪə(r)","pos":"noun","senses":[{"en":"a person who is visiting interesting buildings and places as a tourist","cn":"观光者；游客","ex":{"en":"Oxford attracts large numbers of sightseers.","cn":"牛津吸引着大量观光客。"}}]}},"signboard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"招牌;告示牌;广告牌","en":"A signboard is a piece of wood which has been painted with pictures or words and which gives some information about a particular place, product, or event.","ex":{"en":"The signboard outside the factory read 'baby milk plant'.","cn":"工厂外的招牌上写着“婴儿乳品厂”。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flat piece of wood, cardboard etc in a public place, with writing on it that gives people information","cn":"招牌﹐告示牌"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41signboard.mp3","us":"media/ldoce/hwd/ame/5/signboard.mp3"},"oxford":{"phon":"ˈsaɪnbɔːd","pos":"noun","senses":[{"en":"a piece of wood that has some information on it, such as a name, and is displayed outside a shop, hotel, etc.","cn":"（商店、旅馆等的）招牌，告示牌，广告牌"}]}},"sift":{"collins":{"senses":[{"pos":"VERB 动词","cn":"筛(面粉、沙子等)","en":"If you sift a powder such as flour or sand, you put it through a sieve in order to remove large pieces or lumps.","ex":{"en":"Sift the flour and baking powder into a medium-sized mixing bowl.","cn":"将面粉和发酵粉筛入中等大小的搅拌碗中。"}},{"pos":"VERB 动词","cn":"细查;详审","en":"If you sift through something such as evidence, you examine it thoroughly.","ex":{"en":"Police officers have continued to sift through the wreckage following yesterday's bomb attack","cn":"警察继续仔细检查昨天炸弹袭击后留下的残骸。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put flour, sugar etc through a sieve or similar container in order to remove large pieces","cn":"筛〔面粉﹑白糖等〕"},{"en":"to examine information, documents etc carefully in order to find something out or decide what is important and what is not","cn":"细查﹐详查﹐严密检查〔信息﹑文件等〕"},{"en":"to separate something from other things","cn":"挑选﹐筛选；区分"}]},"vocab":{"pos":"v","senses":[{"en":"To bake a cake, you sift the flour to get out the lumps. When you sift, you separate out one thing from another."}]},"collocations":{"phrases":["ADV. finely Sift the flour finely before adding it to the mixture. | in, together Beat the mixture until smooth, then sift in the remaining ","ADV. carefully, methodically","PREP. through They spent days carefully sifting through the evidence."]},"media":{"uk":"media/ldoce/hwd/bre/9/sift0205.mp3","us":"media/ldoce/hwd/ame/b/sift.mp3"},"examples":[{"en":"She looked quickly through the papers, sifting out from the pile anything that looked interesting.","cn":"她很快地翻了一下那摞文件，把所有看着有趣的东西都拣了出来。"},{"en":"Crash investigators have been sifting through the wreckage of the aircraft.","cn":"调查坠机事件的专家一直在仔细检查飞机残骸。"}],"oxford":{"phon":"sɪft","pos":"verb","senses":[{"en":"to put flour or some other fine substance through a sieve / sifter","cn":"筛（面粉或颗粒较细的物质）","g":"[transitive]","ex":{"en":"Sift the flour into a bowl.","cn":"把面粉筛到碗里。"}},{"en":"to examine something very carefully in order to decide what is important or useful or to find something important","cn":"细查；详审","g":"[transitive, intransitive]","ex":{"en":"We will sift every scrap of evidence.","cn":"我们将细查每一点证据。"}},{"en":"to separate something from a group of things","cn":"区分；挑选；精选","g":"[transitive]","ex":{"en":"He sifted the relevant data from the rest.","cn":"他从其余的资料中筛选出相关的资料。"}}]}},"silkworm":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蚕","en":"A silkworm is the young form of a Chinese moth and it produces silk."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of caterpillar which produces silk thread","cn":"蚕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/silkworm0205.mp3","us":"media/ldoce/hwd/ame/c/silkworm.mp3"},"oxford":{"phon":"ˈsɪlkwɜːm","pos":"noun","senses":[{"en":"a caterpillar (= a small creature like a worm with legs) that produces silk thread","cn":"蚕"}]}},"sibling":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兄弟姐妹","en":"Your siblings are your brothers and sisters.","ex":{"en":"His siblings are mostly in their early twenties","cn":"他的兄弟姐妹大多二十出头。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a brother or sister","cn":"兄弟﹔姊妹"},{"en":"competition between brothers and sisters for their parents’ attention or love","cn":"手足相争〔指兄弟姐妹为得到父母的关注或宠爱的竞争〕"}]},"vocab":{"pos":"n","senses":[{"en":"A sibling is your brother or sister. It's that simple."}]},"collocations":{"phrases":["ADJ. elder/older, younger The younger children were badly treated by older siblings.","SIBLING + NOUN rivalry","PREP. among/between ~s poor relationships between siblings"]},"media":{"uk":"media/ldoce/hwd/bre/c/sibling0205.mp3","us":"media/ldoce/hwd/ame/8/sibling.mp3"},"examples":[{"en":"sibling rivalry (= competition between brothers and sisters)","cn":"兄弟姐妹间的竞争"},{"en":"squabbles between siblings","cn":"兄弟姐妹间的口角"}],"oxford":{"phon":"ˈsɪblɪŋ","pos":"noun","senses":[{"en":"a brother or sister","cn":"兄；弟；姐；妹","ex":{"en":"squabbles between siblings","cn":"兄弟姐妹间的口角"}}]}},"sill":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"窗台;窗沿","en":"A sill is a shelf along the bottom edge of a window, either inside or outside a building.","ex":{"en":"Whitlock was perched on the sill of the room's only window.","cn":"惠特洛克坐在房间里仅有的那扇窗户的边沿上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the narrow shelf at the base of a window frame","cn":"窗台"},{"en":"the part of a car frame at the bottom of the doors","cn":"底梁〔指汽车框架在车门以下的部分〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/sill0205.mp3","us":"media/ldoce/hwd/ame/c/sill.mp3"},"oxford":{"phon":"sɪl","pos":"noun","senses":[{"en":"a narrow shelf below a window, either inside or outside","cn":"窗沿；窗台"},{"en":"a piece of metal that forms part of the frame of a vehicle below the doors","cn":"（车体的）门槛"}]}},"sickbed":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"病榻;病床","en":"Your sickbed is the bed that you are lying in while you are ill.","ex":{"en":"Michael left his sickbed to entertain his house guests.","cn":"迈克尔走下病床去招待客人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the bed where a sick person is lying","cn":"病床"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41sickbed.mp3","us":"media/ldoce/hwd/ame/8/sickbed.mp3"},"examples":[{"en":"The President left his sickbed to attend the ceremony.","cn":"总统带病去出席那个仪式。"},{"en":"The president carried on working from his sickbed.","cn":"总裁卧病在床还继续工作。"}],"oxford":{"phon":"ˈsɪkbed","pos":"noun","senses":[{"en":"the bed on which a person who is ill is lying","cn":"病床","ex":{"en":"The president left his sickbed to attend the ceremony.","cn":"总统带病去出席那个仪式。"}}]}},"sighting":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指对不寻常或意外事物的)所见，目睹","en":"A sighting of something, especially something unusual or unexpected is an occasion on which it is seen.","ex":{"en":"...the sighting of a rare sea bird at Lundy island","cn":"在兰迪岛上看到一种珍稀海鸟"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion on which something is seen, especially something rare or something that people are hoping to see","cn":"看见﹐发现〔尤指见到罕见的或希望见到的事物〕"}]},"collocations":{"phrases":["ADJ. confirmed, reliable | unconfirmed | reported | rare | UFO","VERB + SIGHTING have We now have three confirmed sightings of an enemy plane. | report | follow up, investigate The police are now following","PREP. ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdesighting.mp3","us":"media/ldoce/hwd/ame/e/sighting.mp3"},"examples":[{"en":"a reported sighting of the Loch Ness monster","cn":"据报道有人看见尼斯湖水怪"},{"en":"There were two unconfirmed sightings of UFOs in the area.","cn":"这个地区有两起未经证实的目击不明飞行物的事件。"}],"oxford":{"phon":"ˈsaɪtɪŋ","pos":"noun","senses":[{"en":"an occasion when somebody sees somebody/something, especially something unusual or something that lasts for only a short time","cn":"看见，目睹（不寻常或短暂出现的事物）","ex":{"en":"a reported sighting of the Loch Ness monster","cn":"据报道有人看见尼斯湖水怪"}}]}},"sinuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"摇曳生姿的;动作柔软的","en":"Something that is sinuous moves with smooth twists and turns.","ex":{"en":"...the silent, sinuous approach of a snake through the long grass","cn":"一条蛇灵活地扭动身躯，穿过高高的草丛悄悄地靠近"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"蜿蜒的;弯弯曲曲的","en":"Something that is sinuous has many smooth turns and curves.","ex":{"en":"I drove along sinuous mountain roads.","cn":"我行驶在蜿蜒的山路上。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"moving with smooth twists and turns, like a snake","cn":"动作柔软的"},{"en":"with many smooth twists and turns","cn":"蜿蜒的﹐弯弯曲曲的"}]},"vocab":{"pos":"adj","senses":[{"en":"Sinuous means winding or curvy. If you get lost on a sinuous mountain path, you'll need a compass or a GPS to figure out which direction leads back to camp."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41sinuous.mp3","us":"media/ldoce/hwd/ame/1/sinuous.mp3"},"examples":[{"en":"the sinuous course of the river","cn":"弯弯曲曲的河道"},{"en":"the sinuous grace of a cat","cn":"猫的灵活优美"}],"oxford":{"phon":"ˈsɪnjuəs","pos":"adjective","senses":[{"en":"turning while moving, in an attractive way; having many curves","cn":"弯曲有致的；蜿蜒的","ex":{"en":"a sinuous movement","cn":"婀娜多姿的动作"}}]}},"sinewy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肌肉发达的;精壮的;强健的","en":"Someone who is sinewy has a lean body with strong muscles.","ex":{"en":"A short, sinewy young man","cn":"一名个子不高、肌肉发达的年轻男子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a sinewy person has a thin body and strong muscles","cn":"肌肉发达的﹐矫健的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something muscular, with a tight and stretched toughness, is sinewy. Tennis players' lean arms have a sinewy beauty, all the muscles showing as they hit their smoking serves."}]},"media":{"uk":"media/ldoce/hwd/bre/6/sinewy0205.mp3","us":"media/ldoce/hwd/ame/f/sinewy.mp3"},"examples":[{"en":"a big man with long, sinewy arms","cn":"胳膊又长又壮的大个子"}],"oxford":{"phon":"ˈsɪnjuːi","pos":"adjective","senses":[{"en":"having a thin body and strong muscles","cn":"肌肉发达的；矫健的；强健的","ex":{"en":"The runner was tall and sinewy.","cn":"跑步者身材高大，肌肉发达。"}}]}},"signify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"表示;意味着;意思是","en":"If an event, a sign, or a symbol signifies something, it is a sign of that thing or represents that thing.","ex":{"en":"The contrasting approaches to Europe signified a sharp difference between the major parties","cn":"对欧洲截然不同的态度表明两大政党间存在巨大差异。"}},{"pos":"VERB 动词","cn":"(用记号或手势)表明，表达，表示","en":"If you signify something, you make a sign or gesture in order to communicate a particular meaning.","ex":{"en":"Two jurors signified their dissent","cn":"两名陪审团成员表示了异议。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to represent, mean, or be a sign of something","cn":"代表﹔表示﹔象征﹔意味着"},{"en":"if you signify a feeling, opinion etc, you do something that acts as a sign so that other people know your feeling or opinion 〔","cn":"用动作〕表示〔感觉﹑意见等〕"},{"en":"to be important enough to have an effect on something","cn":"要紧﹐有关系﹐有重要性"}]},"vocab":{"pos":"v","senses":[{"en":"To signify means to \"mean.\" When Paul Revere looked for the lanterns in the church tower, he knew that one would signify that the British were coming by land and two would indicate that they were coming by sea."}]},"media":{"uk":"media/ldoce/hwd/bre/a/signify0205.mp3","us":"media/ldoce/hwd/ame/3/signify.mp3"},"examples":[{"en":"This decision signified a radical change in their policies.","cn":"这个决定表明了他们的政策发生了根本的变化。"},{"en":"This mark signifies that the products conform to an approved standard.","cn":"这个标志说明这些产品符合指定的标准。"}],"oxford":{"phon":"ˈsɪɡnɪfaɪ","pos":"verb","senses":[{"en":"to be a sign of something","cn":"表示；说明；预示","g":"[transitive]","ex":{"en":"This decision signified a radical change in their policies.","cn":"这个决定表明了他们的政策发生了根本的变化。"}},{"en":"to do something to make your feelings, intentions, etc. known","cn":"表达，表示，显示（感情、意愿等）","g":"[transitive]","ex":{"en":"She signified her approval with a smile.","cn":"她笑了笑表示赞同。"}},{"en":"to be important or to matter","cn":"具有重要性；要紧","g":"[intransitive]","ex":{"en":"His presence no longer signified.","cn":"他在不在场已不重要。"}}]}},"sister-in-law":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大(或小)姑子;大(或小)姨子;嫂子;弟媳;妯娌","en":"Someone's sister-in-law is the sister of their husband or wife, or the woman who is married to their brother."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the sister of your husband or wife","cn":"丈夫[妻子]的姊妹﹔姑子﹔姨子"},{"en":"your brother’s wife","cn":"兄长[弟弟]的妻子﹔嫂子﹔弟媳"},{"en":"the wife of the brother of your husband or wife","cn":"配偶的兄弟之妻﹔妯娌﹔舅嫂"}]},"media":{"uk":"media/ldoce/hwd/bre/9/sister_in_law0205.mp3","us":"media/ldoce/hwd/ame/7/sister-in-law.mp3"},"oxford":{"phon":"ˈsɪstər ɪn lɔː","pos":"noun","senses":[{"en":"the sister of your husband or wife; your brother’s or sister's wife; the wife of your husband's or wife’s brother or sister","cn":"配偶的姐姐（或妹妹）；兄弟（或姐妹）的配偶；姻姐；姻妹"}]}},"sixtieth":{"collins":{"senses":[{"pos":"ORD 序数词","cn":"第六十","en":"The sixtieth item in a series is the one that you count as number sixty.","ex":{"en":"He is to retire on his sixtieth birthday.","cn":"他准备在 60 岁生日那天退休。"}},{"pos":"FRACTION 分数词","cn":"六十分之一","en":"A sixtieth is one of sixty equal parts of something."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the number 60","cn":""},{"en":"the years from 1960 to 1969","cn":""},{"en":"to be aged between 60 and 69","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41sixty.mp3","us":"media/ldoce/hwd/ame/9/sixty.mp3"},"examples":[{"en":"The book was written in the sixties.","cn":""},{"en":"the student riots in Paris in the late sixties","cn":""}],"oxford":{"phon":"ˈsɪkstiəθ","pos":"ordinal number","senses":[{"en":"60th","cn":"第六"},{"en":"each of 60 equal parts of something","cn":"六分之一","pos":"noun"}]}},"sideline":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兼职;副业","en":"A sideline is something that you do in addition to your main job in order to earn extra money.","ex":{"en":"It was quite a lucrative sideline","cn":"这份兼职很赚钱。"}},{"pos":"N-PLURAL 复数名词","cn":"(球场等的)边线","en":"The sidelines are the lines marking the long sides of the playing area, for example on a football field or tennis court."},{"pos":"N-PLURAL 复数名词","cn":"(某一情况的)外围，局外","en":"If you are on the sidelines in a situation, you do not influence events at all, either because you have chosen not to be involved, or because other people have not involved you.","ex":{"en":"France no longer wants to be left on the sidelines when critical decisions are taken","cn":"在作出关键决定时，法国不想再被撇在一边了。"}},{"pos":"VERB 动词","cn":"把…排除在外;使靠边;不重视","en":"If someone or something is sidelined, they are made to seem unimportant and not included in what people are doing.","ex":{"en":"He was under pressure to resign and was about to be sidelined","cn":"他承受着被迫辞职的压力，很快就要被排挤出去了。"}},{"pos":"VERB 动词","cn":"使(运动员)下场;使退出比赛","en":"In sports, if a player is sidelined, he or she is prevented from playing for a period of time, for example because of an injury.","ex":{"en":"Mercer will have his jaw wired up tomorrow and will be sidelined for six to eight weeks.","cn":"默瑟明天要进行下颌骨固定手术，将离开赛场 6至8 个星期。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a job that you do in addition to your main job, especially because it is something that you enjoy or are interested in","cn":""},{"en":"if you do a job on the side , you do it secretly or unofficially, in addition to your main job","cn":""},{"en":"to do another job, usually in the evenings or at night, in addition to your main job","cn":""}]},"collocations":{"phrases":["ADJ. lucrative, nice (little), profitable, useful He decided to turn his hobby into a lucrative sideline.","VERB + SIDELINE have | develop","PREP. ~ for Cider making was a sideline for many farmers. | ~ in She is developing a nice little sideline in childminding for friends. | ~ t"]},"media":{"uk":"media/ldoce/hwd/bre/9/sideline_n0205.mp3","us":"media/ldoce/hwd/ame/4/sideline1.mp3"},"examples":[{"en":"He was content to watch from the sidelines as his wife built up a successful business empire.","cn":"他满足于站在一旁，看妻子一步步地建立起一个成功的商业帝国。"},{"en":"The vice-president is increasingly being sidelined.","cn":"副总统被日益排挤到权力中心之外。"}],"oxford":{"phon":"ˈsaɪdlaɪn","pos":"noun","senses":[{"en":"an activity that you do as well as your main job in order to earn extra money","cn":"兼职；副业；兼营业务","g":"[countable]","ex":{"en":"His hobby of winemaking was fast becoming a profitable sideline.","cn":"他的酿酒爱好很快成为一项有利可图的副业。"}},{"en":"the lines along the two long sides of a sports field, tennis court, etc. that mark the outer edges; the area just outside these","cn":"（球场等的）边线，两侧场外区域","g":"[plural]","ex":{"en":"The coach stood on the sidelines yelling instructions to the players.","cn":"教练站在场外，大声指挥运动员。"}},{"en":"to prevent somebody from playing in a team, especially because of an injury","cn":"使退出比赛，使下场（尤指由于受伤）","ex":{"en":"The player has been sidelined by a knee injury.","cn":"这名队员因膝部受伤而下场。"},"pos":"verb"},{"en":"to prevent somebody from having an important part in something that other people are doing","cn":"把…排除在核心之外；使靠边","ex":{"en":"The vice-president is increasingly being sidelined.","cn":"副总统被日益排挤到权力中心之外。"},"pos":"verb"}]}},"sinus":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鼻窦","en":"Your sinuses are the spaces in the bone behind your nose.","ex":{"en":"I still suffer from catarrh and sinus problems.","cn":"我仍然患有黏膜炎和鼻窦炎。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"your sinuses are the spaces in the bones of your head that are connected to the inside of your nose","cn":"窦﹐窦道〔颅骨中与鼻孔相通的空穴〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/sinus0205.mp3","us":"media/ldoce/hwd/ame/4/sinus.mp3"},"examples":[{"en":"blocked sinuses","cn":"窦性传导阻滞"},{"en":"a sinus infection","cn":"窦感染"}],"oxford":{"phon":"ˈsaɪnəs","pos":"noun","senses":[{"en":"any of the hollow spaces in the bones of the head that are connected to the inside of the nose","cn":"窦；窦道","ex":{"en":"blocked sinuses","cn":"窦性传导阻滞"}}]}},"sitcom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"情景喜剧","en":"A sitcom is an amusing television drama series about a set of characters. Sitcom is an abbreviation for (缩略=) 'situation comedy'.","ex":{"en":"...the classic '70s TV sitcom 'Rising Damp'.","cn":"70 年代的经典情景喜剧《旧楼记》"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you watch on television, or listen to on the radio","cn":""},{"en":"a programme on television or the radio, especially an informal one in which people talk together, take part in a game etc","cn":""},{"en":"a programme that gives you facts and information about a serious subject, such as history, science, or social problems","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Sitcom is short for “situation comedy.” It’s a funny TV show with a realistic setting, like an apartment full of wacky roommates or a restaurant where a regular cast of characters cracks jokes from week to week."}]},"media":{"uk":"media/ldoce/hwd/bre/6/sitcom0205.mp3","us":"media/ldoce/hwd/ame/9/sitcom.mp3"},"oxford":{"phon":"ˈsɪtkɒm","pos":"noun","senses":[{"en":"a regular comedy programme on television that shows the same characters in different funny situations","cn":"情景喜剧","ex":{"en":"It’s America’s most popular sitcom.","cn":"这是美国最受欢迎的情景喜剧。"}}]}},"simper":{"collins":{"senses":[{"pos":"VERB 动词","cn":"傻笑;痴笑","en":"When someone simpers, they smile in a rather silly way.","ex":{"en":"The maid lowered her chin and simpered.","cn":"侍女低头痴笑着。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to smile in a silly annoying way","cn":"矫揉造作地笑﹔傻笑"}]},"vocab":{"pos":"v n","senses":[{"en":"To simper means to smile in an artificial, coy or self-conscious way. If you hope to please someone by simpering , you may wind up annoying him or her."}]},"media":{"uk":"media/ldoce/hwd/bre/d/simper0205.mp3","us":"media/ldoce/hwd/ame/0/simper.mp3"},"examples":[{"en":"‘You're such a darling,’ she simpered. “","cn":"你可真讨人喜欢。”她卖弄风情地笑着说。"},{"en":"‘You're such a darling,’ she simpered.","cn":""}],"oxford":{"phon":"ˈsɪmpə(r)","pos":"noun","senses":[{"en":"a silly and annoying smile","cn":"矫揉造作地笑；扭捏作态地笑"},{"en":"to smile in a silly and annoying way","cn":"矫揉造作地笑；扭捏作态地笑","ex":{"en":"a silly simpering girl","cn":"扭捏作态、嘻嘻傻笑的女孩子"},"pos":"verb"}]}},"simulator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"模拟装置","en":"A simulator is a device which artificially creates the effect of being in conditions of some kind. Simulators are used in training people such as pilots or astronauts.","ex":{"en":"...pilots practising a difficult landing in a flight simulator.","cn":"在飞行模拟装置中练习高难度着陆的飞行员"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a machine that is used for training people by letting them feel what real conditions are like, for example in a plane 〔","cn":"用于人员训练的〕模拟装置﹐模拟器"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41simulator.mp3","us":"media/ldoce/hwd/ame/b/simulator.mp3"},"examples":[{"en":"a flight simulator","cn":"飞行模拟器"}],"oxford":{"phon":"ˈsɪmjuleɪtə(r)","pos":"noun","senses":[{"en":"a piece of equipment that artificially creates a particular set of conditions in order to train somebody to deal with a situation that they may experience in reality","cn":"模拟装置","ex":{"en":"Researchers tested 50 motorists using a driving simulator.","cn":"研究人员使用驾驶模拟器对 50 名驾车者进行了测试。"}}]}},"sickle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"镰刀","en":"A sickle is a tool that is used for cutting grass and grain crops. It has a short handle and a long curved blade."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tool with a blade in the shape of a hook, used for cutting wheat or long grass","cn":"镰刀"}]},"media":{"img":["media/ldoce/img/sickle.jpg"],"uk":"media/ldoce/hwd/bre/6/sickle0205.mp3","us":"media/ldoce/hwd/ame/b/sickle.mp3"},"oxford":{"phon":"ˈsɪkl","pos":"noun","senses":[{"en":"a tool with a curved blade (= cutting edge) and a short handle, used for cutting grass, etc.","cn":"镰刀"}]}},"sidestep":{"collins":{"senses":[{"pos":"VERB 动词","cn":"回避，规避(问题等)","en":"If you sidestep a problem, you avoid discussing it or dealing with it.","ex":{"en":"Rarely, if ever, does he sidestep a question","cn":"他极少逃避问题。"}},{"pos":"VERB 动词","cn":"横跨一步躲过;侧移一步闪开","en":"If you sidestep, you step sideways in order to avoid something or someone that is coming towards you or going to hit you.","ex":{"en":"As I sidestepped, the bottle hit me on the left hip","cn":"我侧一步要躲闪的时候，瓶子打中了我的左髋部。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not talk about a subject or not answer a question, because you do not want to cause embarrassment or problems for yourself","cn":""},{"en":"to avoid a particular subject or a question because you are trying to hide something","cn":""},{"en":"someone who is evasive tries to avoid answering questions or explaining their plans, because they want to hide something","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/sidestep0205.mp3","us":"media/ldoce/hwd/ame/5/sidestep.mp3"},"examples":[{"en":"Did you notice how she neatly sidestepped the question?","cn":"你有没有注意到她多么巧妙地回避了那个问题？"},{"en":"He cleverly sidestepped the tackle.","cn":"他巧妙地一晃，绕过阻截队员。"}],"oxford":{"phon":"ˈsaɪdstep","pos":"verb","senses":[{"en":"to avoid answering a question or dealing with a problem","cn":"回避，规避（问题等）","g":"[transitive]","ex":{"en":"Did you notice how she neatly sidestepped the question?","cn":"你有没有注意到她多么巧妙地回避了那个问题？"}},{"en":"to avoid something, for example being hit, by stepping to one side","cn":"横跨一步躲过；侧移一步闪过","g":"[transitive, intransitive]","ex":{"en":"He cleverly sidestepped the tackle.","cn":"他巧妙地一晃，绕过阻截队员。"}}]}},"signer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手语使用者;手语译员","en":"A signer is someone who communicates to deaf people using sign language.","ex":{"en":"I'm keen on providing signers for deaf people and readers for the blind.","cn":"我热心于为聋哑人提供手语员，为盲人提供朗读员。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use a pen or pencil to make words, letters etc","cn":""},{"en":"to write something on paper, in order to remember it or make a record","cn":""},{"en":"to write something in a particular place, or to write particular words","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdesign.mp3","us":"media/ldoce/hwd/ame/7/sign1.mp3"},"examples":[{"en":"The artist had signed his name in the corner of the painting.","cn":""},{"en":"You forgot to sign the cheque .","cn":""}],"oxford":{"phon":"ˈsaɪnə(r)","pos":"noun","senses":[{"en":"a person who signs a document, letter, etc.","cn":"签名者；签字者","ex":{"en":"the signers of the petition","cn":"在请愿书上签名的人"}},{"en":"a person who uses sign language","cn":"使用手语的人；手语者","ex":{"en":"signers communicating information to deaf people","cn":"向聋人传递信息的手语译员"}}]}},"sit-in":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"静坐示威","en":"A sit-in is a protest in which people go to a public place and stay there for a long time.","ex":{"en":"The campaigners held a sit-in outside the Supreme Court.","cn":"运动参与者在最高法院门外举行了静坐示威。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a large number of people come together to protest about something, by having an outdoor meeting or marching through the streets","cn":""},{"en":"when a large group of people walk in an organized way from one place to another in order to protest about something","cn":""},{"en":"when people protest against the actions of a country or company, for example by not buying its products, not attending its events etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/sit_in0205.mp3","us":"media/ldoce/hwd/ame/2/sit-in.mp3"},"examples":[{"en":"to hold/stage a sit-in","cn":"举行静坐示威"}],"oxford":{"phon":"ˈsɪt ɪn","pos":"noun","senses":[{"en":"a protest in which a group of workers, students, etc. refuse to leave their factory, college, etc. until people listen to their demands","cn":"（建筑物内的）静坐罢工，静坐示威","ex":{"en":"to hold/stage a sit-in","cn":"举行静坐示威"}}]}},"simplistic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(观点、阐述)过分简单化的","en":"A simplistic view or interpretation of something makes it seem much simpler than it really is.","ex":{"en":"He has a simplistic view of the treatment of eczema","cn":"他对湿疹治疗的看法过于简单化。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an opinion or way of thinking about something that is simplistic treats difficult things in too simple a way","cn":""},{"en":"to say that something is true of all the people in a group simply because it is true of some of them","cn":""},{"en":"if someone sees things in black and white , they tend to judge people in a very simple way as being either completely bad or completely good, completely right or completely wrong etc","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"It would be simplistic to say that people who get good grades study more. This answer doesn't account for the complexities of how we learn and are tested. When something is simplistic , it is overly simple."}]},"collocations":{"phrases":["VERBS appear, be, look, seem, sound","ADV. extremely, grossly, highly, overly, very a highly simplistic generalization | a bit, fairly, a little, rather, somewhat The graphics ar"]},"media":{"uk":"media/ldoce/hwd/bre/0/simplistic0205.mp3","us":"media/ldoce/hwd/ame/1/simplistic.mp3"},"examples":[{"en":"This is a very simplistic approach to the problem.","cn":"这是对该问题过分简单化的处理办法。"}],"oxford":{"phon":"sɪmˈplɪstɪk","pos":"adjective","senses":[{"en":"making a problem, situation, etc. seem less difficult or complicated than it really is","cn":"（把问题、局面等）过分简单化的","ex":{"en":"a simplistic approach/view/solution","cn":"简单化的方法/观点/解决方案"}}]}},"sightless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"看不见的;失明的;盲的","en":"Someone who is sightless is blind.","ex":{"en":"He wiped a tear from his sightless eyes.","cn":"他从瞎了的眼睛里擦去了一滴泪水。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"blind","cn":"看不见的﹐失明的﹐盲的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/sightless0205.mp3","us":"media/ldoce/hwd/ame/7/sightless.mp3"},"examples":[{"en":"The statue stared down at them with sightless eyes.","cn":"雕像用一双盲眼俯视着他们。"}],"oxford":{"phon":"ˈsaɪtləs","pos":"adjective","senses":[{"en":"unable to see","cn":"看不见的；盲的","ex":{"en":"The statue stared down at them with sightless eyes.","cn":"雕像用一双盲眼俯视着他们。"}}]}},"silversmith":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"银匠","en":"A silversmith is a person who makes things out of silver."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who makes jewellery and other things out of silver","cn":"银（器）匠"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41silversmith.mp3","us":"media/ldoce/hwd/ame/2/silversmith.mp3"},"oxford":{"phon":"ˈsɪlvəsmɪθ","pos":"noun","senses":[{"en":"a person who makes, repairs or sells articles made of silver","cn":"银匠；银器商"}]}},"silica":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"硅石;二氧化硅","en":"Silica is silicon dioxide, a compound of silicon which is found in sand, quartz, and flint, and which is used to make glass."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical compound that exists naturally as sand, quartz , and flint , used in making glass","cn":"二氧化硅"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41silica.mp3","us":"media/ldoce/hwd/ame/e/silica.mp3"},"oxford":{"phon":"ˈsɪlɪkə","pos":"noun","senses":[{"en":"a chemical containing silicon found in sand and in rocks such as quartz, used in making glass and cement","cn":"二氧化硅"}]}},"sidelight":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(车辆前面的)位置灯，边灯","en":"The sidelights on a vehicle are the small lights at the front that help other drivers to notice the vehicle and to judge its width."},{"pos":"N-COUNT 可数名词","cn":"(车辆两侧的)侧灯","en":"The sidelights on a vehicle are lights on its sides."},{"pos":"N-COUNT 可数名词","cn":"(有关某情况的)侧面消息，趣闻，附带信息","en":"A sidelight on a particular situation is a piece of information about that situation which is interesting but which is not particularly important.","ex":{"en":"The book is full of amusing sidelights on his family background.","cn":"书中有很多关于他家庭背景的趣闻。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two large lights at the front of a vehicle","cn":""},{"en":"one of the two small lights next to the main lights, at the front and back of a car","cn":""},{"en":"one of the two red lights at the back of a vehicle","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41sidelight.mp3","us":"media/ldoce/hwd/ame/2/ld41sidelight.mp3"},"oxford":{"phon":"ˈsaɪdlaɪt","pos":"noun","senses":[{"en":"a piece of information, usually given by accident or in connection with another subject, that helps you to understand somebody/something","cn":"意外线索；侧面了解的情况；间接消息","ex":{"en":"The article gives us a few interesting sidelights on life in Japan in general.","cn":"这篇文章向我们介绍了日本生活的一些有趣的侧面。"}},{"en":"either of a pair of small lights at the front of a vehicle","cn":"（车辆前面的）侧灯","lab":"British English"}]}},"sinew":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"肌腱;筋","en":"A sinew is a cord in your body that connects a muscle to a bone.","ex":{"en":"...the sinews of the neck.","cn":"脖子上的肌腱"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a part of your body that connects a muscle to a bone","cn":"腱﹐肌腱〔连接骨与肌肉的组织〕"},{"en":"something that gives strength or support to a government, country, or system 〔","cn":"政府、国家或体制的〕力量源泉[支柱﹐关键]"}]},"vocab":{"pos":"n","senses":[{"en":"The tendon that connects muscles to bone is also called sinew . The noun is also used to suggest strength and resilience, and is sometimes used as a literary term for muscle, literal or metaphorical, as in “a nation’s sinew .”"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41sinew.mp3","us":"media/ldoce/hwd/ame/d/sinew.mp3"},"examples":[{"en":"The sinews on his neck stood out like knotted string.","cn":"他颈部的肌腱像打结的绳般凸出。"},{"en":"They have begun building the sinews of an independent nation.","cn":"他们已开始建设一个独立国家的命脉。"}],"oxford":{"phon":"ˈsɪnjuː","pos":"noun","senses":[{"en":"a strong band of tissue in the body that joins a muscle to a bone","cn":"肌腱","g":"[countable, uncountable]"},{"en":"a source of strength or power","cn":"力量的来源；关键环节；要害之处","g":"[usually plural]","lab":"literary","ex":{"en":"the sinews of economic life","cn":"经济生活的动力"}}]}},"six-pack":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"六瓶装;六罐装","en":"A six-pack is a pack containing six bottles or cans sold together.","ex":{"en":"He picked up a six-pack of beer.","cn":"他拿起一箱 6 瓶装的啤酒。"}},{"pos":"N-COUNT 可数名词","cn":"发达的腹肌","en":"If a man has a six-pack, his stomach muscles are very well developed.","ex":{"en":"He has a six-pack stomach and is extremely well-proportioned.","cn":"他腹肌发达，体型完美。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"six cans or bottles of a drink, especially beer, sold together as a set 〔","cn":"尤指啤酒等饮料的〕六罐[瓶]装﹐半打装"},{"en":"well-developed muscles that you can see on a man’s stomach – used humorously","cn":"六块腹肌，发达的腹肌〔幽默用法〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41six-pack.mp3","us":"media/ldoce/hwd/ame/e/six-pack.mp3"},"examples":[{"en":"There’s a six-pack in the fridge.","cn":"冰箱里还有一盒半打装的。"},{"en":"a six-pack of beer","cn":"六罐装的啤酒"}],"oxford":{"phon":"ˈsɪks pæk","pos":"noun","senses":[{"en":"a set of six bottles or cans sold together, especially of beer","cn":"（尤指啤酒）六瓶装，六罐装"},{"en":"stomach muscles that are very strong and that you can see clearly across somebody’s stomach","cn":"块块隆起的腹肌","lab":"informal"}]}},"sinusitis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"鼻窦炎","en":"If you have sinusitis, the layer of flesh inside your sinuses is swollen and painful, which can cause headaches and a blocked nose.","ex":{"en":"I have had antibiotics for my sinusitis but it doesn't seem to be clearing up.","cn":"我服用了抗生素来治疗鼻窦炎，但似乎未能根治。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a condition in which your sinuses swell up and become painful （","cn":"鼻）窦炎"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41sinusitis.mp3","us":"media/ldoce/hwd/ame/3/laadsinusitis.mp3"},"oxford":{"phon":"ˌsaɪnəˈsaɪtɪs","pos":"noun","senses":[{"en":"the painful swelling of the sinuses","cn":"鼻窦炎"}]}},"silkscreen":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"丝网印刷的;用绢网印制的","en":"Silk-screen printing is a method of printing patterns onto cloth by forcing paint or dyes through silk or similar material.","ex":{"en":"...silk-screen prints.","cn":"丝网印刷品"}}]}},"sickly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"常生病的;虚弱的;健康欠佳的","en":"A sickly person or animal is weak, unhealthy, and often ill.","ex":{"en":"He had been a sickly child.","cn":"他曾是个体弱多病的孩子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(通常指因为太甜而)让人恶心的，令人作呕的","en":"A sickly smell or taste is unpleasant and makes you feel slightly sick, often because it is extremely sweet.","ex":{"en":"...the sickly smell of rum.","cn":"朗姆酒甜得发腻的气味"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(颜色、灯光等)暗淡的，苍白的，微弱的","en":"A sickly colour or light is unpleasantly pale or weak.","ex":{"en":"Wallpapers for children too often come only in sickly pastel shades.","cn":"给孩子们用的墙纸往往颜色苍白暗淡。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unhealthy and often ill","cn":""},{"en":"weak and likely to become ill easily","cn":""},{"en":"a sickly child is often ill","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/sickly0205.mp3","us":"media/ldoce/hwd/ame/e/sickly.mp3"},"examples":[{"en":"She looked pale and sickly.","cn":"她面色苍白，病恹恹的。"},{"en":"He was a sickly child.","cn":"他是个爱闹病的孩子。"}],"oxford":{"phon":"ˈsɪkli","pos":"adjective","senses":[{"en":"often ill","cn":"常生病的；多病的；爱闹病的","ex":{"en":"He was a sickly child.","cn":"他是个爱闹病的孩子。"}},{"en":"not looking healthy and strong","cn":"不健壮的；体弱的；有病容的","ex":{"en":"She looked pale and sickly.","cn":"她面色苍白，病恹恹的。"}},{"en":"that makes you feel sick, especially because it is too sweet or full of false emotion","cn":"（尤指太甜或充斥着虚情假意）令人生厌的，让人恶心的","ex":{"en":"a sickly sweet smell","cn":"香得发腻的气味"}},{"en":"unpleasant to look at","cn":"难看的；看着不舒服的","ex":{"en":"a sickly green colour","cn":"一种难看的绿色"}}]}},"simpleton":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"傻瓜;呆子;容易受骗的人","en":"If you call someone a simpleton, you think they are easily deceived or not very intelligent.","ex":{"en":"'But Ian's such a simpleton', she laughed","cn":"“可是伊恩太傻了，”她笑着说道。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has a very low level of intelligence","cn":"智力低下的人﹐傻子﹐蠢人"}]},"vocab":{"pos":"n","senses":[{"en":"A simpleton is an idiot — a person without much common sense or intelligence."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41simpleton.mp3","us":"media/ldoce/hwd/ame/b/simpleton.mp3"},"oxford":{"phon":"ˈsɪmpltən","pos":"noun","senses":[{"en":"a person who you think is silly or stupid and can be easily tricked","cn":"傻瓜；易上当受骗的人"}]}},"sincerely":{"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"真诚地;诚实地","en":"If you say or feel something sincerely, you really mean or feel it, and are not pretending.","ex":{"en":"'Congratulations,' he said sincerely","cn":"“祝贺你，”他真诚地说。"}},{"pos":"CONVENTION 惯用语","cn":"谨上，此致(正式信件中写在姓名前的客套用语)","en":"In Britain, people write 'Yours sincerely' before their signature at the end of a formal letter when they have addressed it to someone by name. In the United States, people usually write 'Sincerely yours' or 'Sincerely' instead.","ex":{"en":"Yours sincerely, James Brown.","cn":"谨上，詹姆斯·布朗"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"use this at the end of formal letters, which began with 'Dear Sir', 'Dear Madam' etc","cn":""},{"en":"use this at the end of formal letters which begin with 'Dear Mr ...', 'Dear Ms ...' etc","cn":""},{"en":"use this at the end of formal letters","cn":""}]},"vocab":{"pos":"adv","senses":[{"en":"Sincerely is one way of signing off on a letter you’ve written, and it’s also an adverb you’d use when you want to emphasize how much you really mean it. I sincerely hope you understand what I’m talking about."}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdesincerely.mp3","us":"media/ldoce/hwd/ame/f/sincerely.mp3"},"examples":[{"en":"‘I won't let you down.’ ‘I sincerely hope not.’ “","cn":"我不会让你失望的。” “但愿如此。”"},{"en":"I sincerely believe that this is the right decision.","cn":"我真心实意地相信这个决定是正确的。"}],"oxford":{"phon":"sɪnˈsɪəli","pos":"adverb","senses":[{"en":"in a way that shows what you really feel or think about somebody/something","cn":"真诚地；诚实地","ex":{"en":"I sincerely believe that this is the right decision.","cn":"我由衷地认为这个决定是正确的。"}}]}},"six-shooter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"六响枪;六发左轮手枪","en":"A six-shooter is a small gun that holds six bullets."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small gun that holds six bullets","cn":"六发式左轮手枪"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41six-shooter.mp3","us":"media/ldoce/hwd/ame/f/six-shooter.mp3"},"oxford":{"phon":"ˈsɪks ʃuːtə(r)","pos":"noun","senses":[{"en":"a small gun that holds six bullets","cn":"六发左轮手枪"}]}},"sitter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 babysitter","en":"A sitter is the same as a babysitter ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a babysitter 〔","cn":"代人照看小孩的〕临时保姆"},{"en":"someone who sits or stands while someone else paints them or takes photographs of them 〔","cn":"坐着或站着供人画像或拍照的〕模特"}]},"media":{"uk":"media/ldoce/hwd/bre/5/sitter0205.mp3","us":"media/ldoce/hwd/ame/0/sitter.mp3"},"oxford":{"phon":"ˈsɪtə(r)","pos":"noun","senses":[{"en":"a person who sits or stands somewhere so that somebody can paint a picture of them or photograph them","cn":"摆姿势让人画像（或拍照）的人","ex":{"en":"A special relationship exists between the sitter and the artist.","cn":"画中人与艺术家之间存在着一种特殊的关系。"}},{"en":"a person who takes care of babies or children while their parents are away from home and is usually paid to do this","cn":"临时保姆；代人临时照看小孩的人","lab":"especially North American English"},{"en":"an easy chance to score a goal","cn":"得分良机","lab":"British English, informal，，","ex":{"en":"He missed an early sitter, then equalized with a goal set up by Alli.","cn":"他错过了早先的一记进球，然后由阿里进球扳平比分。"}}]}},"simulation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"模仿;模拟;仿真品","en":"Simulation is the process of simulating something or the result of simulating it.","ex":{"en":"Training includes realistic simulation of casualty procedures.","cn":"培训包括对急救过程的真实模拟。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the activity of producing conditions which are similar to real ones, especially in order to test something, or the conditions that are produced","cn":"模拟﹐仿真〔尤用于试验〕﹔模拟的环境"}]},"vocab":{"pos":"n","senses":[{"en":"A simulation is a representation of something, not the real thing, like the simulation of life in New York City, seen in movies that were shot on Hollywood sound stages and on the streets of Toronto."}]},"collocations":{"phrases":["ADJ. computer, electronic, laboratory, real-time, virtual reality | accident, flight","VERB + SIMULATION carry out, run To test the model under different conditions, it is necessary to run simulations on a computer.","SIMULATION + VERB indicate sth, show sth","SIMULATION + NOUN model using simulation models to predict earthquake patterns | program | techniques | exercise, experiment | game","PREP. in a/the ~ the basic steps in the simulation | through The pilot's skills are tested through simulation. | ~ of a virtual reality simu"]},"media":{"uk":"media/ldoce/hwd/bre/a/simulation0205.mp3","us":"media/ldoce/hwd/ame/7/simulation.mp3"},"examples":[{"en":"a computer simulation of how the planet functions","cn":"行星活动方式的计算机模拟图像"},{"en":"the simulation of genuine concern","cn":"假装真诚关心"}],"oxford":{"phon":"ˌsɪmjuˈleɪʃn","pos":"noun","senses":[{"en":"a situation in which a particular set of conditions is created artificially in order to study or experience something that could exist in reality","cn":"模拟；仿真","g":"[countable, uncountable]","ex":{"en":"a computer simulation of how the planet functions","cn":"行星活动方式的计算机模拟图像"}},{"en":"the act of pretending that something is real when it is not","cn":"假装；冒充","g":"[uncountable]","ex":{"en":"the simulation of concern","cn":"假装关心"}}]}},"sicilian":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"西西里的;西西里人的;西西里文化的","en":"Sicilian means belonging or relating to Sicily, or to its people or culture.","ex":{"en":"...the Sicilian village of Corleone.","cn":"西西里岛科莱奥内镇的村庄"}},{"pos":"N-COUNT 可数名词","cn":"西西里人;西西里岛人的后裔","en":"A Sicilian is a Sicilian citizen, or a person of Sicilian origin."}]}},"sizzle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(热油、脂肪等)发出咝咝声","en":"If something such as hot oil or fat sizzles, it makes hissing sounds.","ex":{"en":"The sausages and burgers sizzled on the barbecue.","cn":"香肠和牛肉饼在烤架上咝咝作响。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a fire or something burning in a fire crackles , it makes a repeated sharp sound","cn":""},{"en":"to produce the continuous sound that is made, for example by food being cooked in very hot oil","cn":""},{"en":"to make a sound like water falling on hot metal","cn":"咝咝作响"}]},"media":{"uk":"media/ldoce/hwd/bre/c/sizzle0205.mp3","us":"media/ldoce/hwd/ame/5/sizzle.mp3"},"examples":[{"en":"sizzling sausages","cn":"煎得咝咝作响的香肠"},{"en":"The bacon began to sizzle in the pan.","cn":"熏猪肉在平底锅里开始咝咝作响。"}],"oxford":{"phon":"ˈsɪzl","pos":"noun","senses":[{"en":"the sound of food frying in hot oil","cn":"发出（油煎食物的）咝咝声","g":"[singular]","ex":{"en":"the sizzle of sausages","cn":"香肠的滋滋声"}},{"en":"an exciting quality","cn":"撩拨人心；性感火辣","g":"[uncountable]","ex":{"en":"The show is utterly lacking in sizzle and spark.","cn":"这部剧完全缺乏激情和火花。"}},{"en":"to make the sound of food frying in hot oil","cn":"发出（油煎食物的）咝咝声","g":"[intransitive]","ex":{"en":"sizzling sausages","cn":"煎得咝咝作响的香肠"},"pos":"verb"},{"en":"to be very exciting, especially in a sexual way","cn":"撩拨人心；性感火辣","g":"[intransitive]","ex":{"en":"The screen sizzles whenever she appears on it.","cn":"她每次现身荧屏都性感撩人。"},"pos":"verb"}]}},"sighted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有视力的;看得见的;不盲的","en":"Sighted people have the ability to see. This word is usually used to contrast people who can see with people who are blind.","ex":{"en":"Blind children tend to be more passive in this area of motor development than sighted children.","cn":"失明的孩子在动作发展的这一方面往往比不失明的孩子更加被动。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is sighted can see, and is not blind 〔","cn":"人〕看得见的﹐有视力的﹐不盲的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdesighted.mp3","us":"media/ldoce/hwd/ame/d/sighted.mp3"},"examples":[{"en":"the blind parents of sighted children","cn":"有正常视力的孩子的盲人父母"},{"en":"partially sighted","cn":"有部分视力的"}],"oxford":{"phon":"ˈsaɪtɪd","pos":"adjective","senses":[{"en":"able to see; not blind","cn":"看得见的；有视力的","ex":{"en":"the blind parents of sighted children","cn":"有正常视力的孩子的盲人父母"}},{"en":"able to see in the way mentioned","cn":"有…视力的；视力…的","ex":{"en":"partially sighted","cn":"弱视的"}}]}},"situate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指为了更好地理解某事)把…放在(特殊的环境中)，把…跟(具体情境)联系","en":"If you situate something such as an idea or fact in a particular context, you relate it to that context, especially in order to understand it better.","ex":{"en":"How do we situate Christianity in the context of modern physics and psychology?","cn":"我们怎样把基督教放在现代物理学和心理学的背景下来考虑呢？"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to describe or consider something as being part of something else or related to something else","cn":"将…置于﹔把…〔和另一事物〕联系起来"}]},"vocab":{"pos":"v","senses":[{"en":"When you situate something, you figure out where it should go or exactly where it is. You might, for example, use a compass to situate the hunting camp you're building on your grandfather's land."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41situate.mp3","us":"media/ldoce/hwd/ame/0/situate.mp3"},"examples":[{"en":"Let me try and situate the events in their historical context.","cn":"我尽量把这些事件与其历史背景联系起来。"},{"en":"The women have the opportunity to situate their own struggles in a wider historical context.","cn":"这些女性有机会把她们的斗争和更宽广的历史背景联系起来。"}],"oxford":{"phon":"ˈsɪtʃueɪt","pos":"verb","senses":[{"en":"to build or place something in a particular position","cn":"使位于；使坐落于"},{"en":"to consider how an idea, event, etc. is related to other things that influence your view of it","cn":"将…置于；使联系","ex":{"en":"Let me try and situate the events in their historical context.","cn":"我尽量把这些事件与其历史背景联系起来。"}}]}},"silhouette":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(浅色或强光背景下衬托出的)暗色轮廓，影像,剪影","en":"A silhouette is the solid dark shape that you see when someone or something has a bright light or pale background behind them.","ex":{"en":"The dark silhouette of the castle ruins stood out boldly against the fading light.","cn":"城堡遗迹的黑色轮廓在暮色映衬下清晰可见。"}},{"pos":"N-COUNT 可数名词","cn":"形状;外形;轮廓","en":"The silhouette of something is the outline that it has, which often helps you to recognize it.","ex":{"en":"...the distinctive silhouette of his ears","cn":"他耳朵的奇特形状"}},{"pos":"PHRASE 短语","cn":"呈侧面影像;呈黑色轮廓像","en":"If you see something in silhouette, you see it as a dark shape with no detail except for the outline.","ex":{"en":"Even from behind in silhouette, Billy recognized the figure.","cn":"即便看到的只是背影的轮廓，比利还是认出了那个人影。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the shape that something is, for example a square, a circle etc","cn":""},{"en":"the shape of something - use this especially to talk about art or when the shape is not very clear","cn":""},{"en":"the shape of a person","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A silhouette is dark shadow, like a silhouette of a person standing under a street lamp, or a drawing that shows only the shape of an object."}]},"collocations":{"phrases":["ADJ. black, dark, stark","VERB + SILHOUETTE see","PREP. in ~ He drew the city in silhouette. | ~ against I could see its black silhouette against the evening sky."]},"media":{"img":["media/ldoce/img/ldoce_302.png"],"uk":"media/ldoce/hwd/bre/d/silhouette0205.mp3","us":"media/ldoce/hwd/ame/9/silhouette1.mp3"},"examples":[{"en":"A figure stood in the doorway, silhouetted against the light.","cn":"门口站着一个人，屋里的亮光映衬出他的轮廓。"},{"en":"The dress is fitted to give you a flattering silhouette.","cn":"穿这件连衣裙，你显得更有身段了。"}],"oxford":{"phon":"ˌsɪluˈet","pos":"noun","senses":[{"en":"the dark outline or shape of a person or an object that you see against a light background","cn":"（浅色背景衬托出的）暗色轮廓","g":"[countable, uncountable]","ex":{"en":"the silhouette of chimneys and towers","cn":"烟囱和塔楼的轮廓"}},{"en":"the shape of a person’s body or of an object","cn":"（人的）体形；（事物的）形状","g":"[countable]","ex":{"en":"The dress is fitted to give you a flattering silhouette.","cn":"穿这件连衣裙，你显得更有身段了。"}},{"en":"a picture that shows somebody/something as a black shape against a light background, especially one that shows the side view of a person’s face","cn":"剪影；（尤指人脸的）侧影","g":"[countable]"},{"en":"to make something appear as a silhouette","cn":"使呈现暗色轮廓","ex":{"en":"A figure stood in the doorway, silhouetted against the light.","cn":"门口站着一个人，屋里的亮光映衬出他的轮廓。"},"pos":"verb"}]}},"singlet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(运动员或拳击选手穿的)背心，无袖汗衫，运动背心","en":"A singlet is a sleeveless sports shirt worn by athletes and boxers.","ex":{"en":"...a grubby running singlet.","cn":"一件脏兮兮的跑步背心"}},{"pos":"N-COUNT 可数名词","cn":"(贴身穿的)背心","en":"A singlet is a plain sleeveless piece of underwear which is worn on the upper half of the body.","ex":{"en":"He was wearing a blue silk singlet and boxer shorts.","cn":"他穿着一件蓝色丝绸背心和平脚短裤。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of clothing that you wear for sport which covers the top part of your body but not your arms","cn":"无袖汗衫﹐运动背心"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41singlet.mp3","us":"media/ldoce/hwd/ame/5/ld41singlet.mp3"},"oxford":{"phon":"ˈsɪŋɡlət","pos":"noun","senses":[{"en":"a piece of clothing without arms, worn under or instead of a shirt; a similar piece of clothing worn by runners, etc.","cn":"背心；无袖汗衫；运动背心"}]}},"sidekick":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"助手;副手","en":"Someone's sidekick is a person who accompanies them and helps them, and who you consider to be less intelligent or less important than the other person.","ex":{"en":"His sons, brother and nephews were his armed sidekicks.","cn":"他的儿子、兄弟和侄子都是他的左膀右臂，都配备了武器。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who takes part in a sport or game, or a business or social activity with you","cn":""},{"en":"someone who is travelling, working, studying etc with you","cn":""},{"en":"someone that you spend a lot of time with, especially someone that provides friendship or conversation while you are doing something, for example travelling","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/sidekick0205.mp3","us":"media/ldoce/hwd/ame/9/sidekick.mp3"},"examples":[{"en":"Batman and his young sidekick Robin","cn":"蝙蝠侠和他的年轻助手罗宾"}],"oxford":{"phon":"ˈsaɪdkɪk","pos":"noun","senses":[{"en":"a person who helps another more important or more intelligent person","cn":"助手；副手","ex":{"en":"Batman and his young sidekick Robin","cn":"蝙蝠侠和他的年轻助手罗宾"}}]}},"sicken":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使厌恶;使作呕","en":"If something sickens you, it makes you feel disgusted.","ex":{"en":"The notion that art should be controlled by intellectuals sickened him","cn":"他讨厌艺术应由知识分子所掌控的观点。"}},{"pos":"VERB 动词","cn":"患病;得病;生病","en":"If you sicken, you become ill.","ex":{"en":"Many of them sickened and died.","cn":"他们中的很多人都患病身亡。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a group of people are up in arms , they are protesting angrily about something that has been done or decided, especially by the government or some other official group","cn":""},{"en":"to feel very angry and disappointed because you think that someone's actions are very wrong, dishonest, or immoral","cn":""},{"en":"extremely angry about something wrong, immoral, or unfair, especially something violent","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Things that sicken you make you feel upset or ill. It might sicken you to realize that you've hit a squirrel with your car."}]},"media":{"uk":"media/ldoce/hwd/bre/7/sicken0205.mp3","us":"media/ldoce/hwd/ame/3/sicken.mp3"},"examples":[{"en":"( BrE ) Faye hasn't eaten all day — she must be sickening for something.","cn":"费伊一天没吃饭了。她一定是哪儿不舒服了。"},{"en":"( old-fashioned ) The baby sickened and died before his first birthday.","cn":"婴儿没过周岁就病死了。"}],"oxford":{"phon":"ˈsɪkən","pos":"verb","senses":[{"en":"to make somebody feel very shocked and angry","cn":"使大为震惊；使愤怒","g":"[transitive]","ex":{"en":"Reading the report of the attack sickened him.","cn":"阅读有关袭击的报告使他感到恶心。"}},{"en":"to become ill","cn":"患病；生病","g":"[intransitive]","lab":"old-fashioned","ex":{"en":"The baby sickened and died before his first birthday.","cn":"婴儿没过周岁就病死了。"}}]}},"simple-minded":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"头脑简单的;天真的;愚蠢的","en":"If you describe someone as simple-minded, you believe that they interpret things in a way that is too simple and do not understand how complicated things are.","ex":{"en":"Sylvie was a simple-minded romantic","cn":"西尔维是个天真的爱幻想的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not very intelligent, and unable to understand complicated things","cn":"头脑简单的﹐愚钝的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41simple-minded.mp3","us":"media/ldoce/hwd/ame/7/ld41simple-minded.mp3"},"examples":[{"en":"a simple-minded person","cn":"头脑简单的人"},{"en":"a simple-minded approach","cn":"笨方法"}],"oxford":{"phon":"ˌsɪmpl ˈmaɪndɪd","pos":"adjective","senses":[{"en":"not intelligent; not understanding how complicated things are","cn":"智力低下的；愚蠢的；头脑简单的","ex":{"en":"a simple-minded approach","cn":"笨方法"}}]}},"sire":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指种马)生殖，繁殖","en":"When a male animal, especially a horse, sires a young animal, he makes a female pregnant so that she gives birth to it.","ex":{"en":"Comet also sired the champion foal out of Spinway Harvest.","cn":"“彗星”还跟“斯平威·哈维斯特”生下了这匹出类拔萃的小马驹。"}},{"pos":"VERB 动词","cn":"做…的父亲","en":"If a man sires a child, he makes a woman pregnant and she gives birth to a child.","ex":{"en":"Hunt married three women and sired 15 children.","cn":"亨特娶过 3 个女人，生了 15 个孩子。"}},{"pos":"N-COUNT 可数名词","cn":"父亲","en":"Your sire is your father."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"used when speaking to a king","cn":"陛下〔对国王的尊称〕"},{"en":"the father of a four-legged animal, especially a horse 〔","cn":"四足动物的〕雄性种畜﹔〔尤指〕种马"},{"en":"to be the father of an animal, especially a horse or dog 〔","cn":"尤指雄性的马或狗〕生殖﹐繁殖"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41sire.mp3","us":"media/ldoce/hwd/ame/1/sire1.mp3"},"examples":[{"en":"The people await you, sire.","cn":"臣民在恭候您﹐陛下。"},{"en":"a stallion that has sired several race winners","cn":"繁殖了好几匹赛马冠军的种马"}],"oxford":{"phon":"ˈsaɪə(r)","pos":"noun","senses":[{"en":"the male parent of an animal, especially a horse","cn":"雄性种畜；（尤指）种公马","lab":"specialist"},{"en":"a word that people used when they addressed a king","cn":"（旧时对国王的称呼）陛下","lab":"old use"},{"en":"to be the male parent of an animal, especially a horse","cn":"（种马等雄性动物）生殖，繁殖","pos":"verb"},{"en":"to become the father of a child","cn":"成为父亲","lab":"old-fashioned or humorous","pos":"verb"}]}},"sisterly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"姐妹般的","en":"A woman's sisterly feelings are the feelings of love and loyalty which you expect a sister to show.","ex":{"en":"We just had a sisterly relationship","cn":"我们只是姐妹般的关系。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"typical of a loving sister","cn":"姐妹的﹐亲如姊妹的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41sisterly.mp3","us":"media/ldoce/hwd/ame/f/sisterly.mp3"},"examples":[{"en":"She gave him a sisterly kiss.","cn":"她像姐姐一样亲了他一下。"},{"en":"She gave Lee a sisterly kiss.","cn":"她像姐姐一样亲了李一下。"}],"oxford":{"phon":"ˈsɪstəli","pos":"adjective","senses":[{"en":"typical of or like a sister","cn":"姐妹的；姐妹般的","ex":{"en":"She gave him a sisterly kiss.","cn":"她像姐姐一样亲了他一下。"}}]}},"sibilant":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"发咝咝音的","en":"Sibilant sounds are soft 's' sounds.","ex":{"en":"A sibilant murmuring briefly pervaded the room.","cn":"一时间房间里充满了窃窃私语声。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making an ‘s’ or ‘sh’ sound","cn":"发咝咝声的﹔发咝咝音的"},{"en":"a sibilant sound such as ‘s’ or ‘sh’ in English","cn":"咝音〔例如英语中的s或sh〕"}]},"vocab":{"pos":"adj n","senses":[{"en":"Something that’s sibilant has a hissing sound, like when the librarian says, “Shhhhhhhh!”"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41sibilant.mp3","us":"media/ldoce/hwd/ame/7/sibilant1.mp3"},"examples":[{"en":"the sibilant sound of whispering","cn":"窃窃私语声"},{"en":"a sibilant whisper","cn":"窃窃私语"}],"oxford":{"phon":"ˈsɪbɪlənt","pos":"adjective","senses":[{"en":"making a ‘s’ or ‘sh’ sound","cn":"发咝咝声的","ex":{"en":"the sibilant sound of whispering","cn":"窃窃私语声"}},{"en":"a sibilant sound made in speech, such as /s/ and /z/ in the English words sip and zip","cn":"咝音；咝擦音","pos":"noun"}]}},"silage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"青贮饲料","en":"Silage is food for cattle that is made by cutting a crop such as grass or corn when it is green and then keeping it covered."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"grass or other plants cut and stored so that they can be used as winter food for cattle","cn":"青贮饲料"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41silage.mp3","us":"media/ldoce/hwd/ame/8/silage.mp3"},"oxford":{"phon":"ˈsaɪlɪdʒ","pos":"noun","senses":[{"en":"grass or other green crops that are stored without being dried and are used to feed farm animals in winter","cn":"青贮饲料"}]}},"siding":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(铁路线的)侧线，岔道","en":"A siding is a short railway track beside the main tracks, where engines and carriages are left when they are not being used."},{"pos":"N-UNCOUNT 不可数名词","cn":"(建筑外墙的)墙板，壁板","en":"Siding is a wooden or metal covering on the outside walls of a building."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short railway track connected to a main track, where trains are kept when they are not being used 〔","cn":"铁路的〕侧轨﹐旁轨"},{"en":"long narrow pieces of wood, metal, or plastic, used for covering the outside walls of houses 〔","cn":"房屋外墙的〕壁板﹐墙板"}]},"media":{"uk":"media/ldoce/hwd/bre/6/siding0205.mp3","us":"media/ldoce/hwd/ame/a/siding.mp3"},"oxford":{"phon":"ˈsaɪdɪŋ","pos":"noun","senses":[{"en":"a short track next to a main railway line, where trains can stand when they are not being used","cn":"（火车停靠的）站线","g":"[countable]"},{"en":"material used to cover and protect the outside walls of buildings","cn":"壁板；墙板；挡板","g":"[uncountable]","lab":"North American English","ex":{"en":"aluminium siding","cn":"铝壁板"}}]}},"signage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(总称)标志，标牌(尤指路标、广告牌)","en":"Signage is signs, especially road signs and advertising signs, considered collectively.","ex":{"en":"They don't allow signage around the stadium.","cn":"他们不允许在体育场周围设广告牌。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the signs in or on a building, or in a public place 〔","cn":"建筑物或公共场所的〕标识"}]},"vocab":{"pos":"n","senses":[{"en":"Signage is a word for a bunch of signs, just like gaggle is a word for a bunch of geese."}]},"media":{"uk":"media/ldoce/hwd/bre/4/lpd_signage.mp3","us":"media/ldoce/hwd/ame/6/laadsignage.mp3"},"examples":[{"en":"The signage at the hospital is being made clearer.","cn":"医院标识正在修改﹐以便更加清楚。"}],"oxford":{"phon":"ˈsaɪnɪdʒ","pos":"noun","senses":[{"en":"signs, especially ones that give instructions or directions to the public","cn":"（统称）标志，标识，标记"}]}},"siesta":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指气候炎热国家的)午睡，午休","en":"A siesta is a short sleep or rest which you have in the early afternoon, especially in hot countries.","ex":{"en":"They have a siesta during the hottest part of the day.","cn":"他们会在一天中最炎热的时刻小睡一会儿。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short sleep in the afternoon, especially in warm countries 〔","cn":"尤指炎热国家的〕午休﹐午睡"},{"en":"take/have a siesta The stores all close after lunch when everyone takes a siesta.","cn":"午饭后所有商店都关门﹐大家都睡午觉。"}]},"collocations":{"phrases":["ADJ. short | afternoon","VERB + SIESTA have, take Lots of people were taking a short siesta in the shade.","SIESTA + NOUN time","PREP. for a ~ I went upstairs for my afternoon siesta."]},"media":{"uk":"media/ldoce/hwd/bre/b/siesta0205.mp3","us":"media/ldoce/hwd/ame/a/siesta.mp3"},"examples":[{"en":"to have/take a siesta","cn":"睡午觉"}],"oxford":{"phon":"siˈestə","pos":"noun","senses":[{"en":"a rest or sleep taken in the early afternoon, especially in hot countries","cn":"（尤指在气候炎热的国家的）午睡，午休","ex":{"en":"to have/take a siesta","cn":"睡午觉"}}]}},"single-breasted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(上衣、夹克、套装等)单排扣的","en":"A single-breasted coat, jacket, or suit fastens in the centre of the chest and has only one row of buttons."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a single-breasted jacket or suit has only one set of buttons down the front 〔","cn":"上衣〕单排（纽）扣的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41single-breaste.mp3","us":"media/ldoce/hwd/ame/a/single-breasted.mp3"},"oxford":{"phon":"ˌsɪŋɡl ˈbrestɪd","pos":"adjective","senses":[{"en":"having only one row of buttons that fasten in the middle","cn":"单排扣的"}]}},"sirloin":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"牛的上腰肉;牛里脊肉","en":"A sirloin is a piece of beef which is cut from the bottom and side parts of a cow's back.","ex":{"en":"...sirloin steaks.","cn":"里脊牛排"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a good-quality piece of beef which is cut from the lower part of a cow’s back 〔","cn":"一块上好的〕牛上腰肉﹐牛里脊肉"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41sirloin.mp3","us":"media/ldoce/hwd/ame/b/sirloin.mp3"},"oxford":{"phon":"ˈsɜːlɔɪn","pos":"noun","senses":[{"en":"good quality beef that is cut from a cow’s back","cn":"牛里脊肉；牛上腰肉"}]}},"sideswipe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"借机抨击;借题发挥的批评;顺带的贬损","en":"If you take a sideswipe at someone, you make an unexpected critical remark about them while you are talking about something else.","ex":{"en":"Despite the increasingly hostile sideswipes at him, the Chancellor is secure in his post.","cn":"尽管有越来越多的人借机恶意抨击财政大臣，他的职位仍很稳固。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you take a sideswipe at someone or something, you criticize them while you are talking about something different","cn":"指桑骂槐；借题发挥的批评"},{"en":"to hit the side of a car with another car so that the two sides touch quickly 〔","cn":"驾车时〕剐蹭〔另一辆车〕"}]},"media":{"uk":"media/ldoce/hwd/bre/0/sideswipe_n0205.mp3","us":"media/ldoce/hwd/ame/a/ld41sideswipe.mp3"},"examples":[{"en":"It was a good speech, but he couldn't resist taking a sideswipe at his opponent.","cn":"他的讲话不错，可他还是忍不住藉机把对手抨击了一番。"},{"en":"( NAmE ) The bus sideswiped two parked cars.","cn":"公共汽车擦边撞上了两辆停在那儿的汽车。"}],"oxford":{"phon":"ˈsaɪdswaɪp","pos":"noun","senses":[{"en":"a hit from the side","cn":"擦边撞击；侧撞；擦撞","lab":"North American English","ex":{"en":"a sideswipe by a truck","cn":"卡车的擦撞"}},{"en":"a critical comment made about somebody/something while you are talking about somebody/something completely different","cn":"借机抨击；借题发挥的批评","lab":"informal","ex":{"en":"It was a good speech, but he couldn't resist taking a sideswipe at his opponent.","cn":"他的讲话不错，可他还是忍不住借机把对手抨击了一番。"}},{"en":"to hit something from the side","cn":"擦边撞击；侧撞；擦撞","ex":{"en":"The bus sideswiped two parked cars.","cn":"公共汽车擦边撞上了两辆停着的车。"},"pos":"verb"}]}},"sidecar":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(附于摩托车旁可载人的)边车，跨斗，侧车","en":"A sidecar is a kind of box with wheels which you can attach to the side of a motorcycle so that you can carry a passenger in it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small vehicle attached to the side of a motorcycle , in which a passenger can ride 〔","cn":"附于摩托车旁的〕边车﹐跨斗"}]},"media":{"uk":"media/ldoce/hwd/bre/b/sidecar0205.mp3","us":"media/ldoce/hwd/ame/6/sidecar.mp3"},"oxford":{"phon":"ˈsaɪdkɑː(r)","pos":"noun","senses":[{"en":"a small vehicle attached to the side of a motorcycle in which a passenger can ride","cn":"（摩托车的）跨斗，边车"}]}},"silo":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(农场储存草料、谷物等的)筒仓","en":"A silo is a tall round metal tower on a farm, in which grass, grain, or some other substance is stored.","ex":{"en":"Before silos were invented, cows gave less milk during winter because they had no green grass to eat.","cn":"筒仓发明前，因为没有青草可以吃，奶牛在冬天产奶量减少。"}},{"pos":"N-COUNT 可数名词","cn":"(核导弹等的)发射井","en":"A silo is a specially built place underground where a nuclear missile is kept.","ex":{"en":"...underground nuclear missile silos.","cn":"地下核导弹发射井"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tall structure like a tower that is used for storing grain, winter food for farm animals etc 〔","cn":"贮藏谷物﹑牲畜冬季用饲料等的〕筒仓﹐青贮塔"},{"en":"a large structure under the ground from which a large missile can be fired","cn":"导弹地下发射井"}]},"vocab":{"pos":"n","senses":[{"en":"A silo is a cylindrical tower used for bulk storage, like grain silos that stand tall near farms. Another kind of silo is harder to see — military silos are underground."}]},"media":{"uk":"media/ldoce/hwd/bre/3/silo0205.mp3","us":"media/ldoce/hwd/ame/e/silo.mp3"},"oxford":{"phon":"ˈsaɪləʊ","pos":"noun","senses":[{"en":"a tall tower on a farm used for storing grain, etc.","cn":"筒仓","ex":{"en":"In modern mills, grain is stored in silos which are often separate from the mill.","cn":"在现代磨坊中，谷物储存在通常与磨坊分开的筒仓中。"}},{"en":"an underground place where nuclear weapons or dangerous substances are kept","cn":"（核武器的）发射井；（危险物品的）地下贮藏库","ex":{"en":"It is believed there are missile silos located in the desert.","cn":"据信沙漠中有导弹发射井。"}},{"en":"an underground place where silage is made and stored","cn":"青贮窖"},{"en":"a system, process, department, etc. that operates separately or is thought of as separate from others","cn":"独立运行的系统（或流程、部门等）","ex":{"en":"Some departments have become silos and no longer communicate regularly with one another.","cn":"一些部门已各自为政，不再定期相互沟通。"}}]}},"sixteenth":{"collins":{"senses":[{"pos":"ORD 序数词","cn":"第十六","en":"The sixteenth item in a series is the one that you count as number sixteen.","ex":{"en":"...the sixteenth century AD.","cn":"公元 16 世纪"}},{"pos":"FRACTION 分数词","cn":"十六分之一","en":"A sixteenth is one of sixteen equal parts of something.","ex":{"en":"...a sixteenth of a second.","cn":"1/16秒"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the number 16","cn":""},{"en":"one of 16 equal parts of something","cn":"十六分之一"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41sixteen.mp3","us":"media/ldoce/hwd/ame/4/sixteen.mp3"},"examples":[{"en":"He moved to London when he was sixteen (= 16 years old ) .","cn":""}],"oxford":{"phon":"ˌsɪksˈtiːnθ","pos":"ordinal number","senses":[{"en":"16th","cn":"十六"},{"en":"each of 16 equal parts of something","cn":"六分之一","pos":"noun"}]}},"siphon":{"collins":{"senses":[{"pos":"VERB 动词","cn":"通过虹吸管吸(或输送、抽干)","en":"If you siphon liquid from a container, you make it come out through a tube and down into a lower container by enabling the pressure of the air on it to push it out.","ex":{"en":"She puts a piece of plastic tubing in her mouth and starts siphoning gas from a huge metal drum","cn":"她把一根塑料管放进嘴里，开始从一个巨大的金属桶里吸气。"}},{"pos":"N-COUNT 可数名词","cn":"虹吸管","en":"A siphon is a tube that you use for siphoning liquid."},{"pos":"VERB 动词","cn":"抽取，抽出，挪用(金钱或资源)","en":"If you siphon money or resources from something, you cause them to be used for a purpose for which they were not intended.","ex":{"en":"He had siphoned thousands of pounds a week from the failing business","cn":"他一周之内从这家濒临破产的企业里抽走了数千英镑的资金。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bent tube used for getting liquid out of a container, used by holding one end of the tube at a lower level than the end in the container","cn":"虹吸管"},{"en":"a type of bottle for holding soda water , which is forced out of the bottle using gas pressure 〔","cn":"压杆式〕苏打水瓶"},{"en":"to remove liquid from a container by using a siphon","cn":"用虹吸管吸出"}]},"vocab":{"pos":"n v","senses":[{"en":"A siphon is a device used to move liquid from one container to the other. If you're giving your goldfish a magnificent new bowl, you can use a siphon to move the water from the old one to the new."}]},"media":{"uk":"media/ldoce/hwd/bre/3/siphon_v0205.mp3","us":"media/ldoce/hwd/ame/e/siphon1.mp3"},"examples":[{"en":"She has been accused of siphoning off thousands of pounds from the company into her own bank account.","cn":"她被指控把公司的几千英镑转移到了自己的账户里。"},{"en":"I siphoned the gasoline out of the car into a can.","cn":"我用虹吸管把汽车里的汽油抽到桶里。"}],"oxford":{"phon":"ˈsaɪfn","pos":"noun","senses":[{"en":"a tube that is used to move liquid from one container down into another, lower container","cn":"虹吸管"},{"en":"to move a liquid from one container to another, using a siphon","cn":"用虹吸管吸（或抽）","ex":{"en":"I siphoned the gasoline out of the car into a can.","cn":"我用虹吸管把汽车里的汽油抽到桶里。"},"pos":"verb"},{"en":"to remove money from one place and move it to another, especially dishonestly or illegally","cn":"（尤指私自或非法）抽走，转移（钱）","lab":"informal","ex":{"en":"She has been accused of siphoning off thousands of pounds from the company into her own bank account.","cn":"她被指控把公司的几千英镑转移到了自己的账户里。"},"pos":"verb"}]}},"sinister":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"邪恶的;有害的;不祥的","en":"Something that is sinister seems evil or harmful.","ex":{"en":"There was something sinister about him that she found disturbing.","cn":"他身上有种邪恶的东西让她很不安。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this about behaviour that is morally wrong, or about people who do things that are morally wrong","cn":""},{"en":"use this about actions that you believe are morally wrong and unacceptable, even if they are not illegal","cn":""},{"en":"deliberately very bad and very cruel to other people","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"People who are left-handed might feel unlucky having to use a desk designed for right-handers, but there probably wasn't any sinister , or evil, intent behind the design. Or was there?"}]},"collocations":{"phrases":["VERBS be, look, seem, sound | find sth","ADV. downright, extremely, really, very | almost | faintly, rather, slightly, somewhat, vaguely I found his silence rather sinister. | someh"]},"media":{"uk":"media/ldoce/hwd/bre/8/sinister0205.mp3","us":"media/ldoce/hwd/ame/7/sinister.mp3"},"examples":[{"en":"There was something cold and sinister about him.","cn":"他给人一种冷酷阴险的感觉。"},{"en":"There is another, more sinister, possibility.","cn":"还有另一种更糟糕的可能。"}],"oxford":{"phon":"ˈsɪnɪstə(r)","pos":"adjective","senses":[{"en":"seeming evil or dangerous; making you think something bad will happen","cn":"邪恶的；险恶的；不祥的；有凶兆的","ex":{"en":"There was something cold and sinister about him.","cn":"他给人一种冷酷阴险的感觉。"}}]}},"sisterhood":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(拥有共同之处的女性之间的)姐妹情谊","en":"Sisterhood is the affection and loyalty that women feel for other women who they have something in common with.","ex":{"en":"There was a degree of solidarity and sisterhood among the women.","cn":"这些女人之间存在着一定程度的团结精神和姐妹情谊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special loyal relationship among women who share the same ideas and aims, especially among feminist s 〔","cn":"尤指女权主义者之间的〕姐妹情谊"},{"en":"a group of women who live a religious life together","cn":"妇女（宗教）团体﹐女修道会"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41sisterhood.mp3","us":"media/ldoce/hwd/ame/8/sisterhood.mp3"},"examples":[{"en":"the special bond of sisterhood that joins women together","cn":"把妇女联合起来的那种特殊的姐妹情"},{"en":"the Christian sisterhood","cn":"基督教修女会"}],"oxford":{"phon":"ˈsɪstəhʊd","pos":"noun","senses":[{"en":"the close relationship of trust between women who share ideas and aims","cn":"（志同道合者之间的）姐妹情谊","g":"[uncountable]"},{"en":"a group of women who live in a community together, especially a religious one","cn":"妇女团体；修女会","g":"[countable + singular or plural verb]"}]}},"sinecure":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(拿薪水却很少工作或担负责任的)闲职，挂名职位","en":"A sinecure is a job for which you receive payment but which does not involve much work or responsibility.","ex":{"en":"She found him an exalted sinecure as a Fellow of the Library of Congress.","cn":"她给他找了一个级别很高的闲职：国会图书馆研究员。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a job which you get paid for even though you do not have to do very much work 〔","cn":"有薪酬而工作不多的〕闲职﹐挂名职务﹐领干薪的职位"}]},"vocab":{"pos":"n","senses":[{"en":"If you have a cushy job — one that pays, but involves minimal work — then you have a sinecure . \"Because he was the brother of the CEO, he was offered a sinecure in the company: he showed up each day and collected a pay check, but others actually did his work.\""}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41sinecure.mp3","us":"media/ldoce/hwd/ame/0/sinecure.mp3"},"oxford":{"phon":"ˈsɪnɪkjʊə(r)","pos":"noun","senses":[{"en":"a job that you are paid for even though it involves little or no work","cn":"闲职；挂名职位"}]}},"singe":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)烧焦;(使)烫糊","en":"If you singe something or if it singes, it burns very slightly and changes colour but does not catch fire.","ex":{"en":"The electric fire had begun to singe the bottoms of his trousers","cn":"电暖炉的火刚开始烧着他的裤腿。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to damage or destroy something with fire or heat","cn":""},{"en":"to make something start burning so that it gets damaged","cn":""},{"en":"to damage the surface of something by burning it so that a dark mark is left on it","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To burn something just a little bit is to singe it. If you get too close to your backyard fire pit, you might singe your shirt sleeve."}]},"media":{"uk":"media/ldoce/hwd/bre/b/singe_v0205.mp3","us":"media/ldoce/hwd/ame/4/singe1.mp3"},"examples":[{"en":"He singed his hair as he tried to light his cigarette.","cn":"他点烟时把头发给燎了。"},{"en":"the smell of singeing fur","cn":"毛皮烧焦的气味"}],"oxford":{"phon":"sɪndʒ","pos":"verb","senses":[{"en":"to burn the surface of something slightly, usually by mistake; to be burnt in this way","cn":"（尤指不小心）烤焦，烫煳","ex":{"en":"He singed his hair as he tried to light his cigarette.","cn":"他点烟时把头发给燎了。"}}]}},"siren":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"汽笛;警报器","en":"A siren is a warning device which makes a long, loud noise. Most fire engines, ambulances, and police cars have sirens.","ex":{"en":"It sounds like an air raid siren.","cn":"那听起来像是空袭警报。"}},{"pos":"N-COUNT 可数名词","cn":"妖艳而危险的女人;妖妇","en":"Some people refer to a woman as a siren when they think that she is attractive to men but dangerous in some way.","ex":{"en":"He depicts her as a siren who has drawn him to his ruin.","cn":"他把她描述成是红颜祸水——就是她毁掉了自己。"}},{"pos":"PHRASE 短语","cn":"诱人的东西;诱惑","en":"A siren call or siren song is the appeal that something has although it is harmful or dangerous.","ex":{"en":"Unable to resist the siren call of the cards, he withdrew their savings and headed for Las Vegas","cn":"他无法抵挡赌牌的诱惑，便提取了他们的存款前往拉斯韦加斯。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment that makes very loud warning sounds, used on police cars, fire engines etc 〔","cn":"警车﹑消防车等的〕汽笛﹐警报器"},{"en":"encouragement to do something that seems very good, especially when this could have bad results","cn":"诱人的花言巧语〔尤指可能有不良后果〕"},{"en":"a woman who is very attractive but also dangerous to men – used especially in newspapers","cn":"妖艳而危险的女人﹐妖妇〔尤用于报纸〕"}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"You know that loud wailing sound coming up the highway behind you? That's the siren on the police car racing along, lights flashing, chasing a speeder (not you, of course)."}]},"collocations":{"phrases":["ADJ. approaching The cars had stopped at the sound of the approaching siren. | air-raid, ambulance, factory, police, warning","VERB + SIREN put on, sound, switch on The ships all sounded their sirens. | hear","SIREN + VERB go (off), sound, start | blare, howl, scream, wail The ambulance sped off with its siren wailing. | die away The police siren d"]},"media":{"uk":"media/ldoce/hwd/bre/f/siren0205.mp3","us":"media/ldoce/hwd/ame/0/siren.mp3"},"examples":[{"en":"The government must resist the siren voices calling for tax cuts.","cn":"政府万万不可听信那些鼓吹减税的动听言辞。"},{"en":"A police car raced past with its siren wailing.","cn":"一辆警车鸣着警报器飞驰而过。"}],"oxford":{"phon":"ˈsaɪrən","pos":"noun","senses":[{"en":"a device that makes a long loud sound as a signal or warning","cn":"汽笛；警报器；警笛","ex":{"en":"an air-raid siren","cn":"空袭警报器"}},{"en":"(in ancient Greek stories) any of a group of sea creatures that were part woman and part bird, or part woman and part fish, whose beautiful singing made sailors sail towards them into rocks or dangerous waters","cn":"塞壬（古希腊神话中半人半鸟或半人半鱼的女海妖，以美妙歌声诱使水手驶向礁石或进入危险水域）"},{"en":"a woman who is thought to be very attractive or beautiful but also dangerous","cn":"妖冶而危险的女人；性感妖女"},{"en":"a temptation to do something that seems very attractive but that will have bad results","cn":"危险的诱惑","lab":"literary","ex":{"en":"The government must resist the siren voices calling for tax cuts.","cn":"政府万万不可听信那些鼓吹减税的动听言辞。"}}]}},"sickroom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"病房;病室","en":"A sickroom is a room in which a sick person is lying in bed.","ex":{"en":"Close friends were allowed into the sickroom.","cn":"密友可以进入病房。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a room where someone who is ill can go to lie down","cn":"病房﹐病室"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41sickroom.mp3","us":"media/ldoce/hwd/ame/a/sickroom.mp3"},"oxford":{"phon":"ˈsɪkruːm","pos":"noun","senses":[{"en":"a room in which a person who is ill is lying in bed","cn":"病房；病室"}]}},"silicone":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"硅酮;硅树脂","en":"Silicone is a tough artificial substance made from silicon, which is used to make polishes, and also used in cosmetic surgery and plastic surgery.","ex":{"en":"...silicone lubricants.","cn":"硅脂润滑油"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical that is not changed by heat or cold, does not let water through, and is used in making artificial body parts, paint, and rubber","cn":"硅酮"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41silicone.mp3","us":"media/ldoce/hwd/ame/0/ld44silicone.mp3"},"examples":[{"en":"a silicone breast implant","cn":"硅酮隆胸植入物"}],"oxford":{"phon":"ˈsɪlɪkəʊn","pos":"noun","senses":[{"en":"a chemical containing silicon. There are several different types of silicone, used to make paint, artificial rubber, varnish, etc.","cn":"硅酮；聚硅氧烷","ex":{"en":"a silicone breast implant","cn":"硅酮乳房假体"}}]}},"sic":{"collins":{"senses":[{"pos":"","cn":"(置于括号中，注于某看似古怪或拼写有误的单词或词组后)原文如此，故意如此","en":"You write sic in brackets after a word or expression when you want to indicate to the reader that although the word looks odd or wrong, you intended to write it like that or the original writer wrote it like that.","ex":{"en":"The latest school jobs page advertises a 'wide rnage (sic) of 6th form courses.'","cn":"最新的学校兼职工作版面上有广告登着“各种六年级课程”(range 误拼为 rnage，原文如此)。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"used after a word that you have copied in order to show that you know it was not spelled or used correctly","cn":"原文如此〔置于所引用文字之后﹐表示知道该词的拼写或用法不正确〕"},{"en":"to tell a dog to attack someone","cn":"嗾使〔狗〕去攻击"},{"en":"used to tell a dog to attack someone","cn":"咬他！追他！〔嗾使狗攻击某人〕"}]},"vocab":{"pos":"1 adv 2 v","senses":[{"en":"When urging your dog to chase a thief, you might say, \" Sic 'em, Fluffy!\" When writing something that might look wrong, you add \"[ sic ]\" to indicate you know it's wrong."}]},"media":{"uk":"media/ldoce/hwd/bre/c/sic_adv0205.mp3","us":"media/ldoce/hwd/ame/8/sic1.mp3"},"examples":[{"en":"In the letter to parents it said: ‘The school is proud of it's [sic] record of excellence’.","cn":"在致家长的信中写道：“ The school is proud of it's（原文如此）record of excellence ”。"},{"en":"Sic him, Duke! (= said to a dog)","cn":"杜克，咬他！（对狗说）"}],"oxford":{"phon":"sɪk","pos":"adverb","senses":[{"en":"written after a word that you have copied from somewhere, to show that you know that the word is wrongly spelled or wrong in some other way","cn":"（注于引文后，表示原文存在拼写等错误）原文如此","ex":{"en":"In the letter to parents it said: ‘The school is proud of it’s [sic] record of excellence’.","cn":"在致家长的信中写道：“The school is proud of it’s（原文如此）record of excellence”。"}},{"en":"to attack somebody","cn":"攻击","ex":{"en":"Sic him, Duke! (= said to a dog)","cn":"杜克，咬他！（对狗说）"},"pos":"verb"}]}},"sitar":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"锡塔尔琴(一种印度的弦乐器)","en":"A sitar is an Indian musical instrument with two layers of strings, a long neck, and a round body."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very long musical instrument from India, similar to a guitar , with two sets of strings and a round body","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41sitar.mp3","us":"media/ldoce/hwd/ame/3/sitar.mp3","img":["media/thumb/sitar.jpg"]},"oxford":{"phon":"sɪˈtɑː(r)","pos":"noun","senses":[{"en":"a musical instrument from South Asia like a guitar, with a long neck and two sets of metal strings","cn":"西塔尔（南亚弦乐器，形似吉他）"}]}},"sit-up":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"仰卧起坐","en":"Sit-ups are exercises that you do to strengthen your stomach muscles. They involve sitting up from a lying position while keeping your legs straight on the floor."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an exercise to make your stomach muscles strong, in which you sit up from a lying position, while keeping your feet on the floor","cn":"仰卧起坐"}]},"media":{"uk":"media/ldoce/hwd/bre/7/sit_up0205.mp3","us":"media/ldoce/hwd/ame/f/sit-up.mp3"},"examples":[{"en":"Jerry says he does two hundred sit-ups a day.","cn":"杰里说他每天做两百个仰卧起坐。"}],"oxford":{"phon":"ˈsɪt ʌp","pos":"noun","senses":[{"en":"an exercise for making your stomach muscles strong, in which you lie on your back on the floor and raise the top part of your body to a sitting position","cn":"仰卧起坐","ex":{"en":"He does 20 sit-ups every morning.","cn":"他每天早上做20个仰卧起坐。"}}]}},"sight-read":{"collins":{"senses":[{"pos":"VERB 动词","cn":"视唱，视奏(事先没有练习，直接看着乐谱演奏或演唱)","en":"Someone who can sight-read can play or sing music from a printed sheet the first time they see it, without practising it beforehand.","ex":{"en":"Symphony musicians cannot necessarily sight-read.","cn":"交响乐乐师未必就能视奏。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to play or sing written music when you look at it for the first time, without practising it first","cn":"视奏﹐视唱〔未经练习﹐直接看乐谱演奏或演唱〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41sight-read.mp3","us":"media/ldoce/hwd/ame/6/sight-read.mp3"},"oxford":{"phon":"ˈsaɪt riːd","pos":"verb","senses":[{"en":"to play or sing written music when you see it for the first time, without practising it first","cn":"视奏，视唱（事先没有练习，直接看着乐谱演奏或演唱）"}]}},"silky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"丝绸一样的;柔软光洁的","en":"If something has a silky texture, it is smooth, soft, and shiny, like silk.","ex":{"en":"...dresses in seductively silky fabrics","cn":"迷人的丝绸长裙"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音)轻柔的，柔和的，温和的","en":"If you describe someone's voice as silky, you mean that it sounds confident but gentle and you find it attractive.","ex":{"en":"...a well-spoken man with a silky voice.","cn":"说话温和而且彬彬有礼的男子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行动)平稳的，流畅的","en":"If you describe the way someone or something moves as silky, you mean that they move very smoothly.","ex":{"en":"Some people moved in silky, liquid movements, others were jerky, probably drunk","cn":"一些人动作平稳流畅，其他人则跌跌撞撞，大概是喝醉了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"looking bright and smooth, and reflecting light","cn":""},{"en":"used about hair or fur that looks shiny and healthy. Glossy magazines and books use expensive shiny paper","cn":""},{"en":"shiny and smooth in a way that looks very attractive – used especially about hair, fur, a car or machine, or about someone’s body","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Silky is an adjective describing something gleaming or shimmery, like long, smooth hair on a person or a little Terrier."}]},"media":{"uk":"media/ldoce/hwd/bre/a/silky0205.mp3","us":"media/ldoce/hwd/ame/2/silky.mp3"},"examples":[{"en":"‘How have I changed?’ he asked silkily. “","cn":"我变得怎么样了？”他柔声问道。"},{"en":"The leaves are grey and silky smooth.","cn":"叶子呈灰色，平整光洁。"}],"oxford":{"phon":"ˈsɪlki","pos":"adverb","senses":[{"en":"very smooth or soft","cn":"柔和的；温和的；轻柔的","ex":{"en":"The leaves are grey and silky smooth.","cn":"叶子呈灰色，平整光洁。"}},{"en":"soft, smooth and shiny like silk","cn":"丝绸一样的；柔软光洁的","ex":{"en":"silky fur","cn":"像丝绸一样的毛皮"},"pos":"adjective"},{"en":"smooth and gentle","cn":"柔和的；温和的；轻柔的","g":"[usually before noun]","ex":{"en":"He spoke in a silky tone.","cn":"他说话柔声细语的。"},"pos":"adjective"},{"en":"made of silk or cloth that looks like silk","cn":"丝（或像丝的织物）制的；丝绸（或像丝绸的织物）的","ex":{"en":"a silky dress","cn":"丝质连衣裙"},"pos":"adjective"}]}},"signature":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"签名;署名;签字","en":"Your signature is your name, written in your own characteristic way, often at the end of a document to indicate that you wrote the document or that you agree with what it says.","ex":{"en":"I was writing my signature at the bottom of the page.","cn":"我正往那页纸的底部签名。"}},{"pos":"ADJ 形容词","cn":"为(某人)所特有的;体现个体特征的","en":"A signature item is typical of or associated with a particular person.","ex":{"en":"Rabbit stew is one of chef Giancarlo Moeri's signature dishes","cn":"炖野兔是厨师詹卡洛·莫里的招牌菜之一。"}},{"pos":"PHRASE 短语","cn":"在…上签字;签署","en":"If you put your signature to a document, you sign it as a way of officially showing that you agree with what is written.","ex":{"en":"The two sides met to put their signatures to a formal agreement.","cn":"双方聚首签署一份正式协议。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to write your name at the end of a letter, document etc, in order to prove who you are or show that you wrote it","cn":""},{"en":"to write the first letter of each of your names on something such as a document to show that you agree to it, have read it etc","cn":""},{"en":"to write your signature on an official document, especially one that has already been signed by someone else, in order to approve it","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you sign your name in your own handwriting, that is your signature . Things you can put your signature on include checks, permission slips, letters, stays of execution, and declarations of independence."}]},"collocations":{"phrases":["ADJ. illegible","VERB + SIGNATURE add, append, put, scrawl, write We both refused to put our signatures to the agreement. | witness Your signature must be wi"]},"media":{"uk":"media/ldoce/hwd/bre/d/signature0205.mp3","us":"media/ldoce/hwd/ame/7/signature.mp3"},"examples":[{"en":"They collected 10 000 signatures for their petition.","cn":"他们在请愿书上征集了 1 万人的签名。"},{"en":"He was attacked for having put his signature to the deal.","cn":"他因在协议上签了字而受到攻击。"}],"oxford":{"phon":"ˈsɪɡnətʃə(r)","pos":"noun","senses":[{"en":"your name as you usually write it, for example at the end of a letter","cn":"签名；署名","g":"[countable]","ex":{"en":"Someone had forged her signature on the cheque.","cn":"有人在支票上伪造了她的签名。"}},{"en":"the act of signing something","cn":"签名；署名；签字；签署","g":"[uncountable]","lab":"formal","ex":{"en":"Two copies of the contract will be sent to you for signature.","cn":"合同一式两份，将送交您签署。"}},{"en":"a particular quality that makes something different from other similar things and makes it easy to recognize","cn":"明显特征；鲜明特色；识别标志","g":"[countable, usually singular]","ex":{"en":"Bright colours are his signature.","cn":"他总爱用亮丽的色彩。"}}]}},"sizeable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"相当大的;颇大的","en":"Sizeable means fairly large.","ex":{"en":"Harry inherited the house and a sizeable chunk of land.","cn":"哈里继承了这座房子以及相当大的一片土地。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this about rates, levels, measurements etc that are bigger than is usual or than is acceptable","cn":""},{"en":"fairly large","cn":"相当大的"},{"en":"large enough to be useful or to have an important effect","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdesizeable.mp3","us":"media/ldoce/hwd/ame/c/laadsizeable.mp3"},"examples":[{"en":"The town has a sizeable Sikh population.","cn":"城里有为数众多的锡克教教徒。"}],"oxford":{"phon":"ˈsaɪzəbl","pos":"adjective","senses":[{"en":"fairly large","cn":"相当大的","ex":{"en":"The town has a sizeable Sikh population.","cn":"城里有为数众多的锡克教教徒。"}}]}},"silken":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"光洁柔软的;丝绸般的","en":"Silken is used to describe things that are very pleasantly smooth and soft.","ex":{"en":"...her long silken hair.","cn":"她那丝滑的长发"}},{"pos":"ADJ 形容词","cn":"丝质的;丝绸(般)的","en":"A silken garment, fabric, or rope is made of silk or a material that looks like silk.","ex":{"en":"...a silken nightshirt.","cn":"丝绸睡衣"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"soft, smooth, and shiny like silk","cn":"丝一般柔亮光滑的"},{"en":"made of silk","cn":"丝制的﹐丝绸的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/silken0205.mp3","us":"media/ldoce/hwd/ame/e/silken.mp3"},"examples":[{"en":"silken hair","cn":"柔软光滑的头发"},{"en":"her silken voice","cn":"她那柔和的嗓音"}],"oxford":{"phon":"ˈsɪlkən","pos":"adjective","senses":[{"en":"soft, smooth and shiny like silk","cn":"丝绸一样的；柔软光洁的","g":"[usually before noun]","ex":{"en":"silken hair","cn":"柔软光滑的头发"}},{"en":"smooth and gentle","cn":"柔和的；温和的；轻柔的","g":"[usually before noun]","ex":{"en":"her silken voice","cn":"她那柔和的嗓音"}},{"en":"made of silk","cn":"丝制的；丝质的；丝绸的","g":"[only before noun]","ex":{"en":"silken ribbons","cn":"丝带"}}]}},"sicily":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"an island in the Mediterranean Sea, which is part of Italy and is close to the country's southwest coast. It is known especially as the home of the mafia . Capital: Palermo.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/p028-000011158.mp3","us":"media/ldoce/hwd/ame/6/p028-000011158.mp3"}},"sisal":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"波罗麻，剑麻(用生长于西印度群岛、南美和非洲的一种植物的叶子制成的纤维)","en":"Sisal is the fibre from the leaves of a plant that is grown in the West Indies, South America, and Africa. Sisal is used to make rope, cord, and mats."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a Central American plant whose leaves produce strong fibre s , also called sisal, which are used in making rope","cn":"剑麻﹐菠萝麻﹐西沙尔麻〔一种中美洲植物﹐可用于制绳〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41sisal.mp3","us":"media/ldoce/hwd/ame/9/sisal.mp3"},"oxford":{"phon":"ˈsaɪsl","pos":"noun","senses":[{"en":"strong fibres made from the leaves of a tropical plant also called sisal, used for making rope, floor coverings, etc.","cn":"西沙尔麻，剑麻（用同名热带植物制成的纤维，用于制绳、织地毯等）"}]}},"sideshow":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"次要活动;附带事件;附属活动","en":"A sideshow is a less important or less significant event or situation related to a larger, more important one that is happening at the same time.","ex":{"en":"In the end, the meeting was a sideshow to a political storm that broke Thursday","cn":"最终，那次会议成了星期四爆发的政治风暴的一个附属事件。"}},{"pos":"N-COUNT 可数名词","cn":"(马戏或游园会中穿插的)小节目，助兴表演,杂耍","en":"At a circus or fair, a sideshow is a performance that you watch or a game of skill that you play, that is provided in addition to the main entertainment.","ex":{"en":"Sideshows at the championship include highland dancing and a play by The Wanlockhead Players.","cn":"锦标赛上的助兴节目包括高地舞蹈和万洛克黑德剧社上演的一部剧。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a separate small part of a fair or circus , where you pay to play games or watch a performance 〔","cn":"游乐场或马戏团的〕穿插表演﹐助兴节目"},{"en":"an event that is much less important or serious than another one","cn":"次要事件﹐附带活动"}]},"media":{"uk":"media/ldoce/hwd/bre/5/sideshow0205.mp3","us":"media/ldoce/hwd/ame/f/sideshow.mp3"},"examples":[{"en":"The initial conflict was a mere sideshow compared with the World War that followed.","cn":"最初的冲突同随后发生的世界大战相比﹐只是次要事件。"}],"oxford":{"phon":"ˈsaɪdʃəʊ","pos":"noun","senses":[{"en":"a separate small show or attraction at a fair or circus where you pay to see a performance or take part in a game","cn":"（游园会或马戏中穿插的）小节目，杂耍"},{"en":"an activity or event that is much less important than the main activity or event","cn":"次要活动；附带事件","ex":{"en":"Defeat in the local elections was a sideshow compared to what happened in the general election.","cn":"与大选相比，地方选举的失败只是一场小插曲。"}}]}},"signatory":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(正式文件的)签署人，签署方，签约国","en":"The signatories of an official document are the people, organizations, or countries that have signed it.","ex":{"en":"Both countries are signatories to the Nuclear Non-Proliferation Treaty.","cn":"两个国家都是《核不扩散条约》的签约国。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the people, organizations, or countries that signs an official agreement 〔","cn":"正式协议的〕签署者，签署方，签署国"}]},"vocab":{"pos":"n","senses":[{"en":"A signatory is someone who signs a document and is subject to it. The co-signer for a loan is one type of signatory ."}]},"collocations":{"phrases":["ADJ. authorized The document must be signed by an authorized signatory of the company. | first, original","SIGNATORY + VERB agree sth Signatories agreed to support the nuclear test ban.","PREP. ~ of/to the signatories to the treaty"]},"media":{"uk":"media/ldoce/hwd/bre/a/signatory0205.mp3","us":"media/ldoce/hwd/ame/f/signatory.mp3"},"examples":[{"en":"Many countries are signatories to/of the Berne Convention.","cn":"很多国家都是《伯尔尼公约》的签署国。"},{"en":"a signatory of the Declaration of Independence 《","cn":"独立宣言》的签署者"}],"oxford":{"phon":"ˈsɪɡnətri","pos":"noun","senses":[{"en":"a person, a country or an organization that has signed an official agreement","cn":"（协议的）签署者，签署方，签署国","ex":{"en":"a signatory of the Declaration of Independence","cn":"《独立宣言》的签署者"}}]}},"sinker":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"完全地;毫无保留地","en":"You can use hook, line, and sinker to emphasize that someone is tricked or forced into a situation completely.","ex":{"en":"We fell for it hook, line, and sinker","cn":"我们对它完全是一见倾心。"}}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41sinker.mp3","us":"media/ldoce/hwd/ame/4/ld41sinker.mp3"},"oxford":{"phon":"ˈsɪŋkə(r)","pos":"noun","senses":[{"en":"a weight that is attached to a fishing line or net to keep it under the water","cn":"（钓丝或渔网上的）沉子，铅锤，坠子"}]}},"sikhism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"锡克教(印度的一种宗教，于 16 世纪从印度教分离出来，信奉一神论)","en":"Sikhism is an Indian religion which separated from Hinduism in the sixteenth century and which teaches that there is only one God."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the religion of the Sikhs","cn":"锡克教"}]},"media":{"uk":"media/ldoce/hwd/bre/c/sikhism0205.mp3","us":"media/ldoce/hwd/ame/a/ld41sikhism.mp3"},"oxford":{"phon":"ˈsiːkɪzəm","pos":"noun","senses":[{"en":"a religion that developed in Punjab in the late 15th century and is based on a belief that there is only one God","cn":"锡克教（15世纪由古鲁那纳克在旁遮普建立的一神教）"}]}},"sit-down":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"坐下休息;小憩","en":"If you have a sit-down, you sit down and rest for a short time.","ex":{"en":"All he wanted was a cup of tea and a sit-down.","cn":"他只求一杯清茶、片刻小憩。"}},{"pos":"ADJ 形容词","cn":"(餐饭)由侍者送上餐桌的，坐在桌前吃的","en":"A sit-down meal is served to people sitting at tables.","ex":{"en":"A sit-down dinner was followed by a disco.","cn":"晚宴之后播放了一曲迪斯科舞曲。"}},{"pos":"ADJ 形容词","cn":"(抗议)静坐的","en":"In a sit-down protest, people refuse to leave a place until they get what they want.","ex":{"en":"Teachers staged a sit-down protest in front of the president's office.","cn":"老师们在校长办公室门前举行了一场静坐抗议。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone is sedentary or they have a sedentary job, they spend most of their time sitting down","cn":""},{"en":"a meal etc in which everyone in a group, usually a large group, sits at tables","cn":""},{"en":"a sit-down meal or restaurant is one in which you sit at a table and eat a formal meal","cn":"坐在桌前吃的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41sit-down.mp3","us":"media/ldoce/hwd/ame/6/sit-down1.mp3"},"examples":[{"en":"a sit-down meal for 50 wedding guests (= served to people sitting at tables)","cn":"为 50 位参加婚礼的客人摆坐式的宴席"},{"en":"I need a cup of tea and a sit-down.","cn":"我需要坐下来，喝杯茶，休息一下。"}],"oxford":{"phon":"ˈsɪt daʊn","pos":"adjective","senses":[{"en":"involving people sitting down","cn":"坐下休息","ex":{"en":"a sit-down protest (= in which people sit down to block a road or the entrance to a building until people listen to their demands)","cn":"静坐抗议"}},{"en":"a rest while sitting in a chair","cn":"坐下休息","ex":{"en":"I need a cup of tea and a sit-down.","cn":"我需要坐下来，喝杯茶，休息一下。"},"pos":"noun"}]}},"sieve":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"滤勺;笊篱;筛子","en":"A sieve is a tool used for separating solids from liquids or larger pieces of something from smaller pieces. It consists of a metal or plastic ring with a wire or plastic net underneath, which the liquid or smaller pieces pass through.","ex":{"en":"Press the raspberries through a fine sieve to form a puree.","cn":"用一个细筛子将山莓压碎过滤，以制成山莓泥。"}},{"pos":"VERB 动词","cn":"筛;过滤","en":"When you sieve a substance, you put it through a sieve.","ex":{"en":"Cream the margarine in a small bowl, then sieve the icing sugar into it.","cn":"将人造黄油在小碗里搅成糊状，再将糖粉筛进去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to cut cheese, carrot etc into small pieces by rubbing it against a special tool","cn":""},{"en":"to make butter, chocolate etc become liquid","cn":""},{"en":"to put flour or other powders through a sieve (= tool like a net made of wire, which you use for removing larger grains or pieces )","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A sieve is a mesh strainer used to separate lumps and clumps from the fine material. Sieves are handy for everything from sifting flour to prospecting for gold — anything where you need to separate the big from the small."}]},"collocations":{"phrases":["ADJ. fine","VERB + SIEVE pass/press/strain sth through","PREP. in a/the ~ Wash the rice in a sieve under cold running water. | through a/the ~ Strain the cream through a fine sieve into the egg mix"]},"media":{"img":["media/ldoce/img/sieve.jpg","media/thumb/sieve.jpg"],"uk":"media/ldoce/hwd/bre/4/sieve_v0205.mp3","us":"media/ldoce/hwd/ame/6/sieve1.mp3"},"examples":[{"en":"Sieve the flour and cocoa powder into a bowl.","cn":"把面粉和可可粉筛进碗里。"}],"oxford":{"phon":"sɪv","pos":"noun","senses":[{"en":"a tool for separating solids from liquids or larger solids from smaller solids, made of a wire or plastic net attached to a ring. The liquid or small pieces pass through the net but the larger pieces do not.","cn":"滤器；筛子；笊篱；漏勺","ex":{"en":"Press the apricot jam through a sieve and stir in one tablespoon of cold water.","cn":"将杏酱压过筛子，加入一汤匙冷水搅拌。"}},{"en":"to put something through a sieve","cn":"筛；过筛；滤","ex":{"en":"Liquidize or sieve half the soup and return it to the pot.","cn":"把一半的汤打成浓汁或者滤一下，再倒回锅里。"},"pos":"verb"}]}},"signpost":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"路标;道路指示牌","en":"A signpost is a sign where roads meet that tells you which direction to go in to reach a particular place or different places.","ex":{"en":"The lights of the car lit up a signpost","cn":"车灯照亮了路标。"}},{"pos":"N-COUNT 可数名词","cn":"线索;征兆","en":"A signpost is something that helps you to know how a situation or a course of action will develop.","ex":{"en":"The outcome of tomorrow's elections will be studied carefully as a signpost of voter intentions on the really big day this year","cn":"明天的选举结果会被作为今年大选的选民意愿风向标来仔细研究。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sign at the side of a road showing directions and distances","cn":"路标"},{"en":"something that helps you understand how something is organized, where to go, or what will follow – used especially in news reports","cn":"线索﹐迹象﹐征兆〔尤用于新闻报道〕"},{"en":"to be clearly or unclearly shown by signposts","cn":"路标指示清楚/不清楚"}]},"media":{"uk":"media/ldoce/hwd/bre/a/signpost_n0205.mp3","us":"media/ldoce/hwd/ame/5/signpost1.mp3"},"examples":[{"en":"You need to signpost for the reader the various points you are going to make.","cn":"你需要向读者介绍你将阐述的各个论点。"},{"en":"( figurative ) The chapter headings are useful signposts to the content of the book.","cn":"看章节标题有助于了解书的内容。"}],"oxford":{"phon":"ˈsaɪnpəʊst","pos":"noun","senses":[{"en":"a sign at the side of a road giving information about the direction and distance of places","cn":"路标","lab":"figurative","ex":{"en":"Follow the signposts to the superstore.","cn":"跟着路标走就能到超市。"}},{"en":"to mark a road, place, etc. with signposts","cn":"设置路标","g":"[usually passive]","ex":{"en":"The route is well signposted.","cn":"这条路线路标设置完善。"},"pos":"verb"},{"en":"to show clearly the way that an argument, a speech, etc. will develop","cn":"介绍（论证、讲话等的）要点","ex":{"en":"You need to signpost for the reader the various points you are going to make.","cn":"你需要向读者介绍你将阐述的各个论点。"},"pos":"verb"}]}},"sincerity":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you say or do things in a way that shows clearly that you honestly mean them","cn":""},{"en":"when you are honest, friendly and happy to tell people the truth about yourself, especially about things that other people might be embarrassed to talk about","cn":""},{"en":"when you are honest about your opinions and feelings, even if other people disapprove of them","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Sincerity is a mix of seriousness and honesty. If you do things with sincerity , people will trust you."}]},"collocations":{"phrases":["ADJ. complete, deep, great, total | genuine, passionate | apparent &lsquo;It's wonderful,&rsquo; he said with apparent sincerity.","VERB + SINCERITY doubt, mistake, question There seems no reason to doubt the sincerity of his beliefs. There was no mistaking his sincerity.","PREP. with ~"]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41sincerity.mp3","us":"media/ldoce/hwd/ame/b/sincerity.mp3"},"examples":[{"en":"I can say in all sincerity that I knew nothing of these plans.","cn":"我可以十分坦诚地说，这些计划我一无所知。"},{"en":"She spoke with total sincerity.","cn":"她讲的是由衷之言。"}],"oxford":{"phon":"sɪnˈserəti","pos":"noun","senses":[{"en":"the quality of showing or saying what you really think or feel","cn":"真诚的；诚挚的；诚恳的","ex":{"en":"The sincerity of his beliefs is unquestionable.","cn":"他对信仰的忠诚无可置疑。"}}]}},"singalong":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(众人自娱自乐的)合唱，歌唱会","en":"A singalong is an occasion when a group of people sing songs together for pleasure.","ex":{"en":"How about a nice sing-along around the piano?","cn":"围在钢琴边来个合唱怎么样？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an informal occasion when people sing songs together 〔","cn":"众人一起的〕自娱歌唱会"}]},"media":{"uk":"media/ldoce/hwd/bre/8/singalong0205.mp3","us":"media/ldoce/hwd/ame/0/laadsingalong.mp3"},"oxford":{"phon":"ˈsɪŋəlɒŋ","pos":"noun","senses":[{"en":"an informal occasion at which people sing songs together","cn":"众人自娱歌唱会","ex":{"en":"a singalong in the local bar","cn":"当地酒吧的歌唱会"}}]}},"simulate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"假装;冒充;装作","en":"If you simulate an action or a feeling, you pretend that you are doing it or feeling it.","ex":{"en":"They rolled about on the Gilligan Road, simulating a bloodthirsty fight","cn":"他们在吉利根路上翻滚，模拟一场暴力厮杀。"}},{"pos":"VERB 动词","cn":"模仿;模拟;仿造","en":"If you simulate an object, a substance, or a noise, you produce something that looks or sounds like it.","ex":{"en":"The wood had been painted to simulate stone","cn":"木头上刷了漆以看起来像块石头。"}},{"pos":"VERB 动词","cn":"仿真;模拟","en":"If you simulate a set of conditions, you create them artificially, for example in order to conduct an experiment.","ex":{"en":"The scientist developed one model to simulate a full year of the globe's climate","cn":"这名科学家研制了一个模型来模拟地球全年的气候。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make or produce something that is not real but has the appearance or feeling of being real","cn":"模拟﹐模仿"},{"en":"to pretend to have a feeling","cn":"假装﹐伪装〔某种感情〕"}]},"vocab":{"pos":"v","senses":[{"en":"When you simulate something you imitate it. Hollywood makeup artists can use pencils and gray wigs to simulate old age in a young actor. It can also mean to model––a computer can simulate disaster scenarios in cities."}]},"collocations":{"phrases":["ADV. closely The device simulates conditions in space quite closely.","VERB + SIMULATE be designed to, be used to Models are used to simulate the workings of a real-life system. | try to"]},"media":{"uk":"media/ldoce/hwd/bre/c/simulate0205.mp3","us":"media/ldoce/hwd/ame/a/simulate.mp3"},"examples":[{"en":"I tried to simulate surprise at the news.","cn":"听到这个消息后，我竭力装出一副吃惊的样子。"},{"en":"Computer software can be used to simulate conditions on the seabed.","cn":"计算机软件可用于模拟海底状况。"}],"oxford":{"phon":"ˈsɪmjuleɪt","pos":"verb","senses":[{"en":"to create particular conditions that exist in real life using computers, models, etc., usually for study or training purposes","cn":"（用计算机或模型等）模拟","ex":{"en":"Computer software can be used to simulate conditions on the seabed.","cn":"计算机软件可用于模拟海底状况。"}},{"en":"to be made to look like something else","cn":"模仿；冒充","ex":{"en":"a gas heater that simulates a coal fire","cn":"模仿煤炉的煤气暖炉"}},{"en":"to pretend that you have a particular feeling","cn":"假装；冒充；装作","ex":{"en":"I tried to simulate surprise at the news.","cn":"听到这个消息后，我竭力装出一副吃惊的样子。"}}]}},"sixpence":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(1971 年前英国旧币制的)六便士","en":"A sixpence is a small silver coin which was used in Britain before the decimal money system was introduced in 1971. It was the equivalent of 2.5 pence."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small silver-coloured coin worth six old pennies , used in Britain in the past 〔","cn":"英国旧时的〕六便士（硬币）"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41sixpence.mp3","us":"media/ldoce/hwd/ame/f/ld41sixpence.mp3"},"oxford":{"phon":"ˈsɪkspəns","pos":"noun","senses":[{"en":"a British coin in use until 1971, worth six old pence","cn":"六便士硬币（英国 1971 年以前使用）"}]}},"simulcast":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(广播和电视上或多个电视频道的)联播节目","en":"A simulcast is a programme which is broadcast at the same time on radio and television, or on more than one channel.","ex":{"en":"...tonight's simulcast of Verdi's Aida.","cn":"今晚威尔第创作的歌剧《阿依达》将在多个电视台联播"}},{"pos":"VERB 动词","cn":"(在广播和电视上或多个电视频道)联播，同步播出","en":"To simulcast a programme means to broadcast it at the same time on radio and television, or on more than one channel.","ex":{"en":"The show will be simulcast on NBC, Fox and a number of cable networks.","cn":"这场演出会在美国国家广播电台、福克斯广播电台和一些有线电视网上同步播出。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to broadcast something at the same time on two or more media such as television, radio, or Internet, or at the same time as it is happening 〔","cn":"在电视、广播或因特网等两个或两个以上的媒体上〕同步播出﹐联播"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41simulcast.mp3","us":"media/ldoce/hwd/ame/a/simulcast.mp3"},"examples":[{"en":"Her keynote speech at the conference is going to be simulcast on the Web.","cn":"她的大会主旨发言将在网络上同步播出。"}],"oxford":{"phon":"ˈsɪmlkɑːst","pos":"verb","senses":[{"en":"to broadcast something as a simulcast","cn":"联播：以联播形式广播内容","ex":{"en":"The show will be simulcast on television and the internet.","cn":"演出将在电视和互联网同步直播。"}},{"en":"a programme, often recording a live event, that is broadcast on two or more television channels, radio channels, internet sites, etc., or using two or more of these types of medium at the same time","cn":"（电视、广播频道、网站等）同步播送节目，同步直播；多媒体同步直播","ex":{"en":"You can either watch live coverage of the event on television or listen to the radio simulcast.","cn":"可在电视上收看这一活动的现场直播，或收听电台的同播。"},"pos":"noun"}]}},"simian":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"像猿猴的;长得像猿猴似的","en":"If someone has a simian face, they look rather like a monkey.","ex":{"en":"Ada had a wrinkled, simian face.","cn":"埃达有一张布满皱纹、长得像猿猴的脸。"}},{"pos":"ADJ 形容词","cn":"猴的;类人猿的","en":"Simian is used to describe things relating to monkeys or apes.","ex":{"en":"...a simian virus.","cn":"一种猴病毒"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"similar to a monkey","cn":"像猴子的"},{"en":"relating to monkeys","cn":"猴子的"}]},"vocab":{"pos":"adj n","senses":[{"en":"As a noun, a simian is a monkey or ape. Something monkey- or ape-like can be described using the adjective simian . So: something can be simian without being a simian . Got it?"}]},"media":{"uk":"media/ldoce/hwd/bre/1/simian0205.mp3","us":"media/ldoce/hwd/ame/7/simian.mp3"},"examples":[{"en":"his dark hair and simian features","cn":"他黑色的头发和猴子似的五官"},{"en":"simian diseases","cn":"猴类疾病"}],"oxford":{"phon":"ˈsɪmiən","pos":"adjective","senses":[{"en":"like a monkey or an ape; connected with monkeys or apes","cn":"像猴（或猿）的；猴（或猿）的","ex":{"en":"simian arms","cn":"猿臂"}}]}},"sidle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"悄悄地走;小心翼翼地走","en":"If you sidle somewhere, you walk there in a quiet or cautious way, as if you do not want anyone to notice you.","ex":{"en":"A young man sidled up to me and said, 'May I help you?'","cn":"一个年轻人悄悄走向我说道，“我可以帮你吗？”"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to walk towards someone and stop next to them, especially because you want to say something","cn":""},{"en":"to walk towards someone you do not know, especially so that you can ask them something","cn":""},{"en":"to move quietly towards someone, trying not to be noticed, so that they do not realize you are there until you are next to them","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To sidle is to walk, but in a way that's casual, quiet, and a little sneaky. If you want to surprise someone, sidle up to them and say, \"Boo!\""}]},"media":{"uk":"media/ldoce/hwd/bre/2/sidle0205.mp3","us":"media/ldoce/hwd/ame/e/sidle.mp3"},"examples":[{"en":"She sidled up to me and whispered something in my ear.","cn":"她悄悄走上前来，对我耳语了几句。"},{"en":"A woman sidled up to us and asked if we wanted to buy a watch.","cn":"一个女人鬼鬼祟祟地走近我们﹐问我们要不要买手表。"}],"oxford":{"phon":"ˈsaɪdl","pos":"verb","senses":[{"en":"to walk somewhere in a shy or uncertain way, as if you do not want to be noticed","cn":"犹犹豫豫地走；羞怯地走；悄悄地走","ex":{"en":"She sidled up to me and whispered something in my ear.","cn":"她悄悄走上前来，对我耳语了几句。"}}]}},"sip":{"collins":{"senses":[{"pos":"VERB 动词","cn":"小口地喝;抿","en":"If you sip a drink or sip at it, you drink by taking just a small amount at a time.","ex":{"en":"Jessica sipped her drink thoughtfully","cn":"杰茜卡小口地喝着饮料，若有所思。"}},{"pos":"N-COUNT 可数名词","cn":"(饮料)一小口;一啜的量","en":"A sip is a small amount of drink that you take into your mouth.","ex":{"en":"Harry took a sip of bourbon","cn":"哈里抿了一口波旁威士忌。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to drink something very slowly","cn":""},{"en":"to drink something in a noisy way","cn":""},{"en":"to drink all of something very quickly","cn":""}]},"collocations":{"phrases":["ADJ. careful, cautious, little, nervous, small | long | noisy","VERB + SIP have, take I took a little sip of my drink.","PREP. in ~s He drank the whisky in sips."]},"media":{"uk":"media/ldoce/hwd/bre/6/sip_las3_br.mp3","us":"media/ldoce/hwd/ame/6/sip1.mp3"},"examples":[{"en":"She sat there, sipping at her tea.","cn":"她坐在那儿抿着茶。"},{"en":"He slowly sipped his wine.","cn":"他慢酌浅饮。"}],"oxford":{"phon":"sɪp","pos":"verb","senses":[{"en":"to drink something, taking a very small amount each time","cn":"小口喝；抿","ex":{"en":"She sat there, sipping at her tea.","cn":"她坐在那儿抿着茶。"}},{"en":"a very small amount of a drink that you take into your mouth","cn":"一小口（饮料）","ex":{"en":"to have/take a sip of water","cn":"喝一小口水"},"pos":"noun"}]}},"sissy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女孩子气的男孩;胆小怯懦的男孩","en":"Some people, especially men, describe a boy as a sissy when they disapprove of him because he does not like rough, physical activities or is afraid to do things which might be dangerous.","ex":{"en":"They were rough kids, and thought we were sissies","cn":"他们那帮孩子野蛮得很，还认为我们太女孩子气。"}},{"pos":"ADJ 形容词","cn":"女孩子气的;娘娘腔的","en":"If you describe an action or activity as sissy, you disapprove of it because you think it is only appropriate for girls or women.","ex":{"en":"Far from being sissy, it takes a real man to accept that he is not perfect.","cn":"只有真正的男人才会接受自己并非完美无缺的事实，这绝不是什么女孩子气。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a boy that other boys dislike because he prefers doing things that girls enjoy","cn":"女孩子气的男孩"}]},"media":{"uk":"media/ldoce/hwd/bre/2/sissy0205.mp3","us":"media/ldoce/hwd/ame/5/sissy1.mp3"},"examples":[{"en":"He wanted to go to dance classes, but he was afraid the other boys would call him a sissy.","cn":"他想去上舞蹈班﹐但又怕其他男孩会说他女里女气的。"}],"oxford":{"phon":"ˈsɪsi","pos":"adjective","senses":[{"en":"an offensive word to describe a boy or man who is considered to be weak, easily frightened, or interested in things considered only suitable for girls or women","cn":"娘娘腔的;胆小的"},{"en":"an offensive word for a boy or man who is considered to be weak, easily frightened, or interested in things considered only suitable for girls or women","cn":"女人气的男子;胆小鬼;懦弱的人","pos":"noun"}]}},"simultaneous":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"同时发生的;同时出现的;同步的","en":"Things which are simultaneous happen or exist at the same time.","ex":{"en":"...the simultaneous release of the book and the album","cn":"书和唱片专辑的同步发行"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if two or more people or things do the same thing together , they do it at the same time and usually in the same place","cn":""},{"en":"if two or more things happen at once , they happen at the same time and this is annoying or causes problems","cn":""},{"en":"if someone does two or more things at one time , they do them at the same time, especially if this is difficult or impressive","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective simultaneous describes something that is done at the same time. \"The teachers all assigned simultaneous projects to the students that week. The kids were grumbling and sleep deprived due to the grind.\""}]},"media":{"uk":"media/ldoce/hwd/bre/5/simultaneous0205.mp3","us":"media/ldoce/hwd/ame/c/simultaneous.mp3"},"examples":[{"en":"The game will be broadcast simultaneously on TV and radio.","cn":"比赛将同时在电视和电台转播。"},{"en":"There were several simultaneous attacks by the rebels.","cn":"反叛者同时发动了几起攻击。"}],"oxford":{"phon":"ˌsɪmlˈteɪniəs","pos":"adjective","senses":[{"en":"happening or done at the same time as something else","cn":"同时发生（或进行）的；同步的","ex":{"en":"There were several simultaneous attacks by the rebels.","cn":"反叛者同时发动了几起攻击。"}}]}},"silvery":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"似银的;银色的","en":"Silvery things look like silver or are the colour of silver.","ex":{"en":"...a small, intense man with silvery hair","cn":"满头银发、个子矮小的热情男子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"metallic paint shines like metal","cn":""},{"en":"shiny with a colour like silver","cn":""},{"en":"shiny and silver in colour","cn":"光亮如银的﹐有银色光泽的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/silvery0205.mp3","us":"media/ldoce/hwd/ame/b/silvery.mp3"},"examples":[{"en":"a silvery grey colour","cn":"银灰色"},{"en":"silvery light","cn":"银光"}],"oxford":{"phon":"ˈsɪlvəri","pos":"adjective","senses":[{"en":"shiny like silver; having the colour of silver","cn":"闪着银光的；银色的","ex":{"en":"silvery light","cn":"银光"}},{"en":"having a pleasant musical sound","cn":"银铃般的；悦耳的","lab":"literary","ex":{"en":"She gave a silvery laugh.","cn":"她发出银白色的笑声。"}}]}},"sidetrack":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使分散思路;使转变话题;使转移目标","en":"If you are sidetracked by something, it makes you forget what you intended to do or say, and start instead doing or talking about a different thing.","ex":{"en":"He'd managed to avoid being sidetracked by Schneider's problems","cn":"他最终总算没有因施奈德的问题而分心。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move away from the main subject that you have been talking or writing about, especially for a short time during a speech or story","cn":""},{"en":"if you are talking about something and are sidetracked or get sidetracked , you allow yourself to start talking or thinking about something else, especially something less important","cn":""},{"en":"if you stray from the subject you are talking about, you start talking about other things instead, for example, because you cannot keep your attention on the main subject","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/sidetrack0205.mp3","us":"media/ldoce/hwd/ame/a/sidetrack1.mp3"},"examples":[{"en":"I was supposed to be writing a letter but I'm afraid I got sidetracked.","cn":"我本来应该在写信，但后来恐怕是分心干别的去了。"},{"en":"Don’t get sidetracked by the audience’s questions.","cn":"不要因为观众的提问而离题。"}],"oxford":{"phon":"ˈsaɪdtræk","pos":"verb","senses":[{"en":"to make somebody start to talk about or do something that is different from the main thing that they are supposed to be talking about or doing","cn":"使转变话题；使转移目标","ex":{"en":"I was supposed to be writing a letter but I'm afraid I got sidetracked.","cn":"我本来应该在写信，但后来恐怕是分心干别的去了。"}}]}},"silver-tongued":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"伶牙俐齿的;能说会道的;有辩才的","en":"A silver-tongued person is very skilful at persuading people to believe what they say or to do what they want them to do.","ex":{"en":"...a silver-tongued lawyer.","cn":"一名巧舌如簧的律师"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"good at talking to people and making them like you, or persuading them to do what you want","cn":"讲话有说服力的﹐有辩才的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41silver-tongued.mp3","us":"media/ldoce/hwd/ame/4/silver-tongued.mp3"},"oxford":{"phon":"ˌsɪlvə ˈtʌŋd","pos":"adjective","senses":[{"en":"showing skill at persuading people to do or to believe what you say","cn":"口才；辩才"}]}},"simmer":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"用文火炖;煨","en":"When you simmer food or when it simmers, you cook it by keeping it at boiling point or just below boiling point.","ex":{"en":"Make an infusion by boiling and simmering the rhubarb and camomile together","cn":"将大黄和甘菊一起煮沸再用文火炖,熬成汤药。"}},{"pos":"VERB 动词","cn":"(冲突、争吵等)酝酿，即将爆发","en":"If a conflict or a quarrel simmers, it does not actually happen for a period of time, but eventually builds up to the point where it does.","ex":{"en":"...bitter divisions that have simmered for more than half a century","cn":"酝酿了半个多世纪的严重分歧"}},{"pos":"","cn":"","en":"相关词组：simmer down"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cook food in very hot water","cn":""},{"en":"to cook food slowly in water that is boiling very gently","cn":""},{"en":"to cook food in hot oil, butter, or fat","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"Usually when you're making a soup, you want to bring it to a boil and then let it simmer , cooking it just below the boiling point to get all the flavors to release."}]},"collocations":{"phrases":["ADV. gently, slowly Allow the soup to simmer gently for ten minutes. | quietly (figurative) She was still quietly simmering from her row wit","VERB + SIMMER allow sth to","PREP. in a mixture of vegetables simmered in yogurt"]},"media":{"uk":"media/ldoce/hwd/bre/6/simmer_n0205.mp3","us":"media/ldoce/hwd/ame/b/simmer1.mp3"},"examples":[{"en":"Bring the sauce to a simmer and cook for 5 minutes.","cn":"改用文火，把调味汁炖 5 分钟。"},{"en":"Simmer the sauce gently for 10 minutes.","cn":"把调味汁用文火炖 10 分钟。"}],"oxford":{"phon":"ˈsɪmə(r)","pos":"verb","senses":[{"en":"to cook something by keeping it almost at boiling point; to be cooked in this way","cn":"用文火炖；煨","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"Simmer the sauce gently for 10 minutes.","cn":"把调味汁用文火炖 10 分钟。"}},{"en":"to be filled with a strong feeling, especially anger, which you have difficulty controlling","cn":"充满（难以控制的感情，尤指愤怒）","g":"[intransitive]","ex":{"en":"She was still simmering with resentment.","cn":"她依旧憋着一肚子的怨恨。"}},{"en":"to develop for a period of time without any real anger or violence being shown","cn":"即将爆发；酝酿","g":"[intransitive]","ex":{"en":"This argument has been simmering for months.","cn":"这场争论已酝酿了几个月了。"}},{"en":"the state when something is almost boiling","cn":"即将沸腾状态；文火炖；小火煨","ex":{"en":"Bring the sauce to a simmer and cook for 5 minutes.","cn":"改用文火，把调味汁炖 5 分钟。"},"pos":"noun"}]}},"singly":{"collins":{"senses":[{"pos":"ADV 副词","cn":"单个地;单独地;一个接一个地","en":"If people do something singly, they each do it on their own, or do it one by one.","ex":{"en":"They marched out singly or in pairs","cn":"他们一个一个地或成双成对地走出来。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"alone, or one at a time","cn":"单独地﹔一个一个地﹐各自地"}]},"media":{"uk":"media/ldoce/hwd/bre/8/singly0205.mp3","us":"media/ldoce/hwd/ame/a/singly.mp3"},"examples":[{"en":"Guests arrived singly or in groups.","cn":"客人有单个来的，也有三三两两一起到的。"},{"en":"The stamps are available singly or in books of ten.","cn":"邮票有单枚的，也有十枚一册的。"}],"oxford":{"phon":"ˈsɪŋɡli","pos":"adverb","senses":[{"en":"alone; one at a time","cn":"单个地；单独地；一个一个地","ex":{"en":"The stamps are available singly or in books of ten.","cn":"邮票有单枚的，也有十枚一册的。"}}]}},"sightseeing":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"游览;观光;旅游","en":"If you go sightseeing or do some sightseeing, you travel around visiting the interesting places that tourists usually visit.","ex":{"en":"...a day's sight-seeing in Venice.","cn":"威尼斯一日观光游"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to visit a place, especially because you are near it","cn":""},{"en":"to visit a well-known place or building while you are in a city or country","cn":""},{"en":"to visit a city or country and look at the famous and interesting places there","cn":""}]},"collocations":{"phrases":["VERB + SIGHTSEEING do, go We did some sightseeing in the morning. It's too hot to go sightseeing.","SIGHTSEEING + NOUN excursion, tour, trip"]},"media":{"uk":"media/ldoce/hwd/bre/5/sightseeing0205.mp3","us":"media/ldoce/hwd/ame/f/sightseeing.mp3"},"examples":[{"en":"Did you have a chance to do any sightseeing?","cn":"你有没有出去游览的机会？"},{"en":"Oxford attracts large numbers of sightseers.","cn":"牛津吸引着大量观光客。"}],"oxford":{"phon":"ˈsaɪtsiːɪŋ","pos":"noun","senses":[{"en":"the activity of visiting interesting buildings and places as a tourist","cn":"观光；游览","lab":"British English","ex":{"en":"to go sightseeing","cn":"去观光"}}]}},"sinful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不道德的;邪恶的","en":"If you describe someone or something as sinful, you mean that they are wicked or immoral.","ex":{"en":"'I am a sinful man,' he said.","cn":"“我是个邪恶的人，”他说。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"against religious rules, or doing something that is against religious rules 〔","cn":"宗教上〕有罪过的"},{"en":"very wrong or bad","cn":"有严重过错的﹐极不应该的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/sinful0205.mp3","us":"media/ldoce/hwd/ame/6/sinful.mp3"},"examples":[{"en":"( informal ) It's sinful to waste good food!","cn":"浪费好好的食物是有罪的！"},{"en":"It is sinful to lie.","cn":"说谎是不道德的。"}],"oxford":{"phon":"ˈsɪnfl","pos":"adjective","senses":[{"en":"morally wrong or evil","cn":"不道德的；邪恶的","lab":"informal","ex":{"en":"sinful thoughts","cn":"邪恶的想法"}}]}},"single-handed":{"collins":{"senses":[{"pos":"ADV 副词","cn":"独自地;单独地;无人帮助地;单枪匹马地","en":"If you do something single-handed, you do it on your own, without help from anyone else.","ex":{"en":"I brought up my seven children single-handed","cn":"我独自一人抚养了 7 个孩子。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"if you do something on your own or by yourself , you do it without anyone helping you","cn":""},{"en":"if you do something difficult unaided you do it without the help of anyone or anything","cn":""},{"en":"if you do something very difficult or very impressive single-handedly or single-handed , you succeed in doing it without the help of anyone else","cn":""}]},"vocab":{"pos":"adj adv","senses":[{"en":"If something is completely independent, with no help from anyone, it's single-handed . Your solo hiking expedition, for example, is single-handed ."}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdesingle-handedly.mp3","us":"media/ldoce/hwd/ame/e/laadsingle-handedly.mp3"},"examples":[{"en":"to sail around the world single-handed","cn":"单人环球航行"},{"en":"a single-handed voyage","cn":"单人航行"}],"oxford":{"phon":"ˌsɪŋɡl ˈhændɪd","pos":"adjective","senses":[{"en":"done on your own with nobody helping you","cn":"独自；单枪匹马地；独立","ex":{"en":"a single-handed voyage","cn":"单人航行"}},{"en":"on your own with nobody helping you","cn":"独自；单枪匹马地；独立","ex":{"en":"to sail around the world single-handed","cn":"单人环球航行"},"pos":"adverb"}]}},"sids":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"婴儿猝死综合征","en":"SIDS is used to talk about the sudden death of a baby while it is asleep, when it had not previously been ill. SIDS is an abbreviation for (缩略=) 'sudden infant death syndrome'.","ex":{"en":"SIDS appears to be somewhat more common among babies who sleep on their stomachs.","cn":"趴着睡的婴儿似乎患婴儿猝死综合征的几率更高。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a baby stops breathing and dies while it is sleeping, for no known reason","cn":"婴儿猝死综合征"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld42sids.mp3","us":"media/ldoce/hwd/ame/6/sids.mp3"},"oxford":{"phon":"sɪdz","pos":"noun","senses":[{"en":"the sudden death while sleeping of a baby that appears to be healthy (the abbreviation for ‘sudden infant death syndrome’)","cn":"婴儿猝死综合征（全写为 sudden infant death syndrome）"}]}},"sidebar":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a separate part of something such as a newspaper article where extra information is given 〔","cn":"报纸新闻等的〕补充报道﹐花絮报道"},{"en":"an occasion when the lawyers and the judge in a trial discuss something without letting the jury hear what they are saying","cn":"私谈﹐私下商量〔审判时律师和法官之间不让陪审团听到的讨论〕"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld42sidebar.mp3","us":"media/ldoce/hwd/ame/3/laadsidebar.mp3"},"oxford":{"phon":"ˈsaɪdbɑː(r)","pos":"noun","senses":[{"en":"a short article in a newspaper or magazine that is printed next to a main article, and gives extra information","cn":"（报纸或杂志的）花絮报道"},{"en":"a narrow area on the side of a computer screen or a web page that is separate from the main part of the page","cn":"（电脑屏幕或网页的）侧边栏，边注栏"},{"en":"an issue, event, action, etc. that is less important than the main one","cn":"次要问题（或事件、行动等）","lab":"especially North American English","ex":{"en":"The promoter provided free concerts as a sidebar to the festival.","cn":"筹办单位举办免费音乐会为节日助兴。"}},{"en":"(in a court of law) a discussion between the judge and the lawyers that the jury cannot hear","cn":"（法庭上）旁厅会议（法官和律师之间避开陪审团的小会）","lab":"US English"}]}}});
